function workDistributionSubjectIconPaths(subjectName = "") {
  const name = String(subjectName || "").toLowerCase();
  if (name.includes("math")) {
    return `<path d="M7 3h10a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z"/><path d="M8 7h8"/><path d="M8 11h2"/><path d="M14 11h2"/><path d="M8 15h2"/><path d="M14 15h2"/><path d="M8 18h2"/><path d="M14 18h2"/>`;
  }
  if (name.includes("bible") || name.includes("literature") || name.includes("reading")) {
    return `<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v15H7a3 3 0 0 0-3 3z"/><path d="M4 5.5v15"/><path d="M8 7h8"/><path d="M8 11h8"/><path d="M8 15h6"/>`;
  }
  if (name.includes("science") || name.includes("lab")) {
    return `<path d="M9 3h6"/><path d="M10 3v5l-5 9a3 3 0 0 0 2.6 4.5h8.8A3 3 0 0 0 19 17l-5-9V3"/><path d="M8 15h8"/>`;
  }
  if (name.includes("history") || name.includes("government")) {
    return `<path d="M3 9h18"/><path d="M5 9l7-5 7 5"/><path d="M6 10v8"/><path d="M10 10v8"/><path d="M14 10v8"/><path d="M18 10v8"/><path d="M4 18h16"/><path d="M3 21h18"/>`;
  }
  if (name.includes("spell") || name.includes("grammar")) {
    return `<path d="M4 16h5"/><path d="M6.5 8 3 16"/><path d="m6.5 8 3.5 8"/><path d="M14 8h2.5a2.5 2.5 0 0 1 0 5H14z"/><path d="M14 13h3a2.5 2.5 0 0 1 0 5h-3z"/>`;
  }
  if (name.includes("english") || name.includes("writing")) {
    return `<path d="M21 12a8 8 0 0 1-8 8H7l-4 3 1.5-5A8 8 0 1 1 21 12z"/>`;
  }
  if (name.includes("music")) {
    return `<path d="M9 18V5l10-2v13"/><circle cx="7" cy="18" r="3"/><circle cx="17" cy="16" r="3"/>`;
  }
  return `<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M4 4.5A2.5 2.5 0 0 1 6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5z"/><path d="M8 7h8"/><path d="M8 11h8"/>`;
}

function getPlanEligibleCourses(studentId) {
  if (!studentId) return [];
  const enrolledCourseIds = studentEnrolledCourseIds(studentId);
  return state.courses.filter((course) => enrolledCourseIds.has(course.id));
}

function getStudentEnrollmentEligibleCourses(studentId) {
  if (!studentId) return [];
  const sourceEnrollments = studentEnrollmentDraftStudentId === studentId
    ? studentEnrollmentDraft
    : state.enrollments;
  const enrolledCourseIds = new Set(
    sourceEnrollments
      .filter((entry) => entry.studentId === studentId)
      .map((entry) => entry.courseId)
  );
  state.sectionEnrollments
    .filter((entry) => entry.studentId === studentId)
    .forEach((entry) => {
      const section = getCourseSection(entry.courseSectionId);
      if (section?.courseId) enrolledCourseIds.add(section.courseId);
    });
  return state.courses.filter((course) => !enrolledCourseIds.has(course.id));
}

function getStudentEnrollmentEligibleScheduleBlocks(studentId) {
  if (!studentId) return [];
  const sourceBlocks = studentEnrollmentDraftStudentId === studentId
    ? studentEnrollmentDraft.filter((entry) => entry.itemType === "scheduleBlock")
    : state.studentScheduleBlocks.filter((entry) => entry.studentId === studentId);
  const assignedIds = new Set(sourceBlocks.map((entry) => entry.scheduleBlockId));
  return state.scheduleBlocks.filter((entry) => !assignedIds.has(entry.id));
}

function renderStudentEnrollmentCourseChecklist(preselectedCourseIds = [], studentId = "") {
  const container = document.getElementById("student-enroll-course-dropdown");
  const optionsWrap = document.getElementById("student-enroll-course-options");
  if (!container || !optionsWrap) return;
  const workingEntries = studentId
    ? (studentEnrollmentDraftStudentId === studentId ? studentEnrollmentDraft : workingStudentEnrollments(studentId))
    : [];
  const draftCourseIds = new Set(
    workingEntries
      .filter((entry) => entry.studentId === studentId && entry.itemType !== "scheduleBlock")
      .map((entry) => entryCourseId(entry))
      .filter(Boolean)
  );
  const draftSectionIds = new Set(
    workingEntries
      .filter((entry) => entry.studentId === studentId && entry.itemType === "courseSection")
      .map((entry) => entry.courseSectionId)
  );
  const eligibleCourses = getStudentEnrollmentEligibleCourses(studentId)
    .filter((course) => !getCourseSectionsForCourse(course.id).length);
  const eligibleSections = sortedCourseSections()
    .filter((section) => !studentId || !draftSectionIds.has(section.id))
    .filter((section) => !studentId || !draftCourseIds.has(section.courseId));
  const eligibleBlocks = getStudentEnrollmentEligibleScheduleBlocks(studentId);
  const eligibleItemKeys = new Set([
    ...eligibleSections.map((section) => `courseSection:${section.id}`),
    ...eligibleCourses.map((course) => `course:${course.id}`),
    ...eligibleBlocks.map((block) => `scheduleBlock:${block.id}`)
  ]);
  const selected = new Set(preselectedCourseIds.filter((id) => eligibleItemKeys.has(id)));
  const focusSubject = studentEnrollmentSubjectFocusId ? getSubject(studentEnrollmentSubjectFocusId) : null;
  const focusSubjectId = focusSubject?.id || "";
  const sectionSubjectId = (section) => getCourse(section.courseId)?.subjectId || "";
  const courseSubjectId = (course) => course.subjectId || "";
  const subjectFocusClass = (subjectId) => focusSubjectId && subjectId === focusSubjectId ? " student-enroll-focus-match" : "";
  const subjectFocusAttr = (subjectId) => subjectId ? ` data-subject-id="${escapeHtml(subjectId)}"` : "";
  const focusMatchCount = focusSubjectId
    ? eligibleSections.filter((section) => sectionSubjectId(section) === focusSubjectId).length
      + eligibleCourses.filter((course) => courseSubjectId(course) === focusSubjectId).length
    : 0;
  const focusNotice = focusSubject
    ? `<div class="student-enrollment-focus-note${focusMatchCount ? "" : " warning"}">
        <span><strong>${escapeHtml(focusSubject.name)}</strong><em>${focusMatchCount ? `${focusMatchCount} available scheduled item${focusMatchCount === 1 ? "" : "s"} highlighted below.` : "No available scheduled items for this subject."}</em></span>
        <button type="button" data-clear-student-enrollment-focus="1">Show All</button>
      </div>`
    : "";
  const sectionCheckboxes = eligibleSections.map((section, idx) => {
    const key = `courseSection:${section.id}`;
    const checked = selected.has(key) ? " checked" : "";
    const inputId = `student-enroll-section-${idx}-${section.id}`;
    const course = getCourse(section.courseId);
    const subjectId = course ? course.subjectId : "";
    const meta = [
      subjectId ? getSubjectName(subjectId) : "",
      ...courseSectionSchoolDayMeta(section).filter((item) => !/ enrolled$/.test(item))
    ];
    const requiredBadge = subjectId && isRequiredSubject(subjectId) ? " <span class=\"subject-required-badge\">Required</span>" : "";
    return `<div class="checklist-row${subjectFocusClass(subjectId)}"${subjectFocusAttr(subjectId)}><input id="${inputId}" type="checkbox" class="student-enroll-course-checkbox" data-subject-id="${escapeHtml(subjectId)}" value="${key}"${checked}><label for="${inputId}">${renderScheduleSourceCell(sectionDisplayName(section.id), meta, requiredBadge)}</label></div>`;
  }).join("");
  const courseCheckboxes = eligibleCourses.map((course, idx) => {
    const key = `course:${course.id}`;
    const checked = selected.has(key) ? " checked" : "";
    const inputId = `student-enroll-course-${idx}-${course.id}`;
    const subjectId = courseSubjectId(course);
    const requiredBadge = isRequiredSubject(course.subjectId) ? " <span class=\"subject-required-badge\">Required</span>" : "";
    return `<div class="checklist-row${subjectFocusClass(subjectId)}"${subjectFocusAttr(subjectId)}><input id="${inputId}" type="checkbox" class="student-enroll-course-checkbox" data-subject-id="${escapeHtml(subjectId)}" value="${key}"${checked}><label for="${inputId}">${renderScheduleSourceCell(course.name, [getSubjectName(course.subjectId), ...courseSchoolDayMeta(course)], requiredBadge)}</label></div>`;
  }).join("");
  const blockCheckboxes = eligibleBlocks.map((block, idx) => {
    const key = `scheduleBlock:${block.id}`;
    const checked = selected.has(key) ? " checked" : "";
    const inputId = `student-enroll-block-${idx}-${block.id}`;
    const typeLabel = SCHEDULE_BLOCK_TYPE_LABELS[block.type] || "Schedule Block";
    return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="student-enroll-course-checkbox" value="${key}"${checked}><label for="${inputId}">${renderScheduleSourceCell(block.name, [typeLabel, ...scheduleBlockSchoolDayMeta(block)])}</label></div>`;
  }).join("");
  const sections = [];
  if (focusNotice) sections.push(focusNotice);
  if (sectionCheckboxes) sections.push(`<div class="checklist-group-label">Classes</div>${sectionCheckboxes}`);
  if (courseCheckboxes) sections.push(`<div class="checklist-group-label">Courses</div>${courseCheckboxes}`);
  if (blockCheckboxes) sections.push(`<div class="checklist-group-label">Schedule Blocks</div>${blockCheckboxes}`);
  optionsWrap.innerHTML = sections.join("") || `<span>${studentId ? "No additional scheduled items available for this student." : "Select a student first."}</span>`;
  updateStudentEnrollmentCourseSummary();
}

function focusStudentRequiredSubjectEnrollment(subjectId) {
  if (!selectedStudentId || !subjectId || !getSubject(subjectId)) return;
  studentEnrollmentSubjectFocusId = subjectId;
  renderStudentEnrollmentCourseChecklist(getSelectedStudentEnrollmentCourseIds(), selectedStudentId);
  const dropdown = document.getElementById("student-enroll-course-dropdown");
  if (dropdown) dropdown.open = true;
  const matchRow = Array.from(document.querySelectorAll("#student-enroll-course-options .checklist-row"))
    .find((row) => row.getAttribute("data-subject-id") === subjectId);
  const matchInput = matchRow?.querySelector(".student-enroll-course-checkbox");
  matchInput?.focus();
  matchRow?.scrollIntoView({ block: "nearest" });
  const enrollmentSection = document.querySelector(".student-detail-section-profile");
  if (enrollmentSection) {
    enrollmentSection.classList.add("student-detail-enrollment-focused");
    window.setTimeout(() => enrollmentSection.classList.remove("student-detail-enrollment-focused"), 1200);
  }
}

function clearStudentRequiredSubjectEnrollmentFocus() {
  studentEnrollmentSubjectFocusId = "";
  renderStudentEnrollmentCourseChecklist(getSelectedStudentEnrollmentCourseIds(), selectedStudentId);
  const dropdown = document.getElementById("student-enroll-course-dropdown");
  if (dropdown) dropdown.open = true;
}

