function renderAdministrationSectionVisibility() {
  const visibleTab = currentAdministrationTab || "workspace-configuration";
  document.querySelectorAll("[data-administration-tab]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-administration-tab") === visibleTab);
  });
  const panels = {
    "workspace-configuration": document.getElementById("administration-workspace-configuration-wrap"),
    alerts: document.getElementById("administration-alerts-wrap"),
    instructors: document.getElementById("administration-instructors-wrap"),
    users: document.getElementById("administration-users-wrap")
  };
  Object.entries(panels).forEach(([key, panel]) => {
    if (panel) panel.classList.toggle("hidden", key !== visibleTab);
  });
  updateAdministrationActiveSummary(visibleTab);
}

function updateAdministrationActiveSummary(visibleTab = currentAdministrationTab || "workspace-configuration") {
  const summary = document.getElementById("administration-active-summary");
  if (!summary) return;
  const labels = {
    "workspace-configuration": "Workspace controls for School Day and Dashboard visibility.",
    alerts: "Operational alert thresholds and alert visibility.",
    instructors: "Instructor records used by classes, reports, and School Day.",
    users: "Admin and student account access."
  };
  summary.textContent = labels[visibleTab] || labels["workspace-configuration"];
}

function updateAdministrationWorkspaceSummary(config) {
  const schoolDayValues = Object.entries(config?.schoolDay || {})
    .filter(([, value]) => typeof value === "boolean");
  const dashboardValues = Object.entries(config?.dashboard || {})
    .filter(([, value]) => typeof value === "boolean");
  const schoolDayEnabled = schoolDayValues.filter(([, value]) => value).length;
  const dashboardEnabled = dashboardValues.filter(([, value]) => value).length;
  const schoolDaySummary = document.getElementById("admin-config-school-day-summary");
  const dashboardSummary = document.getElementById("admin-config-dashboard-summary");
  const workspaceSummary = document.getElementById("administration-workspace-summary");
  if (schoolDaySummary) schoolDaySummary.textContent = `${schoolDayEnabled}/${schoolDayValues.length} shown`;
  if (dashboardSummary) dashboardSummary.textContent = `${dashboardEnabled}/${dashboardValues.length} shown`;
  if (workspaceSummary) {
    workspaceSummary.innerHTML = `
      <span><strong>${schoolDayEnabled}</strong> School Day controls</span>
      <span><strong>${dashboardEnabled}</strong> Dashboard modules</span>`;
  }
}

function renderDashboardSectionVisibility() {
  const visibleTab = normalizedDashboardTab();
  currentDashboardTab = visibleTab;
  const config = workspaceConfig || DEFAULT_WORKSPACE_CONFIG;
  const tabSectionMap = {
    overview: [
      ["dashboard-section-overview", true],
      ["dashboard-overview-instruction-days-card", config.dashboard.showOverviewInstructionDays],
      ["dashboard-overview-instruction-hours-card", config.dashboard.showOverviewInstructionHours],
      ["kpi-attendance-card", config.dashboard.showOverviewAttendance],
      ["kpi-grade-card", config.dashboard.showOverviewRunningGradeAverage],
      ["dashboard-overview-school-year-progress-card", config.dashboard.showOverviewSchoolYearProgress],
      ["dashboard-overview-quarter-progress-card", config.dashboard.showOverviewQuarterProgress],
      ["dashboard-overview-completion-card", config.dashboard.showOverviewCompletedToday],
      ["dashboard-overview-open-items-card", config.dashboard.showOverviewOpenItemsToday],
      ["dashboard-overview-open-classes-card", config.dashboard.showOverviewOpenClasses],
      ["dashboard-overview-grade-risk-card", config.dashboard.showOverviewGradesAtRisk],
      ["dashboard-overview-required-subject-card", config.dashboard.showOverviewMissingRequiredSubjects]
    ],
    execution: [
      ["dashboard-section-needs-attention-today", config.dashboard.showExecutionOpenItemsToday],
      ["dashboard-section-completion-today", config.dashboard.showExecutionCompletedToday]
    ],
    performance: [
      ["dashboard-section-grade-risk-watchlist", config.dashboard.showCourseWatchlist],
      ["dashboard-section-student-performance", config.dashboard.showStudentPerformance],
      ["dashboard-section-grade-trending", config.dashboard.showStudentGradeTrending],
      ["dashboard-section-instructor-grade-trending", config.dashboard.showInstructorGradeTrending],
      ["dashboard-section-gpa-trending", config.dashboard.showGpaTrending],
      ["dashboard-section-grade-type-volume", config.dashboard.showGradeTypeVolume],
      ["dashboard-section-work-distribution", config.dashboard.showWorkDistribution]
    ],
    compliance: [
      ["dashboard-section-instruction-hour-pace", config.dashboard.showRequiredInstructionalHours],
      ["dashboard-section-instruction-day-compliance", config.dashboard.showRequiredInstructionalDays],
      ["dashboard-section-compliance-hours-monthly", config.dashboard.showInstructionHoursPerMonth],
      ["dashboard-section-compliance-days-monthly", config.dashboard.showInstructionDaysPerMonth],
      ["dashboard-section-student-attendance", config.dashboard.showStudentAttendance],
      ["dashboard-section-student-instructional-hours", config.dashboard.showStudentInstructionalHours],
      ["dashboard-section-instructional-hours-trending", config.dashboard.showInstructionHoursTrending],
      ["dashboard-section-instructional-days-trending", config.dashboard.showInstructionDaysTrending],
      ["dashboard-section-required-subject-compliance", config.dashboard.showRequiredSubjectCompliance]
    ]
  };
  const allSections = [
    "dashboard-section-overview",
    "dashboard-overview-instruction-days-card",
    "dashboard-overview-instruction-hours-card",
    "kpi-attendance-card",
    "kpi-grade-card",
    "dashboard-overview-school-year-progress-card",
    "dashboard-overview-quarter-progress-card",
    "dashboard-overview-completion-card",
    "dashboard-overview-open-items-card",
    "dashboard-overview-open-classes-card",
    "dashboard-overview-grade-risk-card",
    "dashboard-overview-required-subject-card",
    "dashboard-section-completion-today",
    "dashboard-section-needs-attention-today",
    "dashboard-execution-placeholder",
    "dashboard-section-grade-risk-watchlist",
    "dashboard-performance-placeholder",
    "dashboard-section-instruction-hour-pace",
    "dashboard-section-instruction-day-compliance",
    "dashboard-section-compliance-hours-monthly",
    "dashboard-section-compliance-days-monthly",
    "dashboard-section-required-subject-compliance",
    "dashboard-section-student-performance",
    "dashboard-section-student-attendance",
    "dashboard-section-student-instructional-hours",
    "dashboard-section-grade-trending",
    "dashboard-section-instructor-grade-trending",
    "dashboard-section-gpa-trending",
    "dashboard-section-instructional-hours-trending",
    "dashboard-section-instructional-days-trending",
    "dashboard-section-grade-type-volume",
    "dashboard-section-work-distribution"
  ];
  const visibleSections = new Map(tabSectionMap[visibleTab] || []);
  if (visibleTab === "execution") {
    visibleSections.set("dashboard-execution-placeholder", !Array.from(visibleSections.values()).some(Boolean));
  } else if (visibleTab === "performance") {
    visibleSections.set("dashboard-performance-placeholder", !Array.from(visibleSections.values()).some(Boolean));
  } else if (visibleTab === "compliance") {
    const complianceTabs = ["instructional-hours", "instructional-days", "required-subjects"];
    if (!complianceTabs.includes(currentComplianceTab)) currentComplianceTab = "instructional-hours";
    visibleSections.forEach((isVisible, sectionId) => {
      const section = document.getElementById(sectionId);
      if (section?.dataset.complianceSection && section.dataset.complianceSection !== currentComplianceTab) {
        visibleSections.set(sectionId, false);
      }
    });
    visibleSections.set("dashboard-section-required-subject-compliance", currentComplianceTab === "required-subjects" && !!config.dashboard.showRequiredSubjectCompliance);
  }
  allSections.forEach((id) => {
    const node = document.getElementById(id);
    if (node) node.classList.toggle("hidden", !visibleSections.get(id));
  });
  const complianceSubtabs = document.getElementById("dashboard-compliance-subtabs");
  if (complianceSubtabs) complianceSubtabs.classList.toggle("hidden", visibleTab !== "compliance");
  document.querySelectorAll("[data-dashboard-tab]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-dashboard-tab") === visibleTab);
  });
  document.querySelectorAll("[data-compliance-tab]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-compliance-tab") === currentComplianceTab);
  });
}

function mountAdministrationManagedPanels() {
  const mappings = [
    ["tab-instructors", "administration-instructors-host"],
    ["tab-users", "administration-users-host"]
  ];
  mappings.forEach(([sourceId, hostId]) => {
    const source = document.getElementById(sourceId);
    const host = document.getElementById(hostId);
    if (!source || !host || host.childElementCount > 0) return;
    Array.from(source.children)
      .filter((child) => !(child.tagName === "H2"))
      .forEach((child) => host.appendChild(child));
  });
}

