function studentRequiredFocusForList(studentId) {
  const focusSubject = studentTableRequiredSubjectFilterId ? getSubject(studentTableRequiredSubjectFilterId) : null;
  const student = state.students.find((entry) => entry.id === studentId);
  if (studentIsArchived(student)) {
    return {
      focusSubject,
      missingSubjects: [],
      requiredComplete: true,
      notEvaluated: true
    };
  }
  const missingSubjects = focusSubject
    ? (studentHasRequiredSubject(studentId, focusSubject.id) ? [] : [focusSubject])
    : studentMissingRequiredSubjects(studentId);
  return {
    focusSubject,
    missingSubjects,
    requiredComplete: missingSubjects.length === 0,
    notEvaluated: false
  };
}

function renderStudentWorkQueueSummary(filteredStudents) {
  const form = document.getElementById("student-table-filter-form");
  if (!form) return;
  let summary = document.getElementById("student-work-queue-summary");
  if (!summary) {
    summary = document.createElement("div");
    summary.id = "student-work-queue-summary";
    summary.className = "student-work-queue-summary hidden";
    form.insertAdjacentElement("afterend", summary);
  }
  const focusSubject = studentTableRequiredSubjectFilterId ? getSubject(studentTableRequiredSubjectFilterId) : null;
  const filterLabels = [];
  if (studentsDashboardReturnContext) filterLabels.push("Dashboard Focus");
  if (focusSubject) filterLabels.push(`Subject: ${focusSubject.name}`);
  if (studentTableFilterRequired === "no") filterLabels.push("Not In Compliance");
  if (studentTableFilterRequired === "yes") filterLabels.push("Compliant");
  if (studentTableFilterGrade !== "all") filterLabels.push(`Grade: ${studentTableFilterGrade}`);
  if (studentTableFilterStatus !== "all") filterLabels.push(`Status: ${studentTableFilterStatus === "archived" ? "Archived" : "Active"}`);
  const searchValue = String(studentTableFilterStudent || "").trim();
  if (searchValue) filterLabels.push("Student Filter");
  if (!filterLabels.length) {
    summary.classList.add("hidden");
    summary.innerHTML = "";
    return;
  }
  const activeStudentsShown = filteredStudents.filter((student) => !studentIsArchived(student));
  const missingCount = activeStudentsShown.filter((student) => !studentRequiredFocusForList(student.id).requiredComplete).length;
  const contextText = missingCount
    ? `${missingCount} need enrollment attention`
    : activeStudentsShown.length
      ? "All shown active students meet the current required-subject focus"
      : "Required compliance is not evaluated for archived students";
  summary.classList.remove("hidden");
  summary.innerHTML = `
    <div class="student-work-queue-copy">
      <strong>${filteredStudents.length.toLocaleString()} student${filteredStudents.length === 1 ? "" : "s"} shown</strong>
      <span>${escapeHtml(contextText)}</span>
    </div>
    <div class="student-work-queue-chips">
      ${filterLabels.map((label) => `<span>${escapeHtml(label)}</span>`).join("")}
    </div>`;
}

function renderStudents() {
  if (!isAdminUser()) return;
  const gradeFilter = document.getElementById("student-table-filter-grade");
  if (gradeFilter) {
    const current = studentTableFilterGrade || gradeFilter.value || "all";
    const grades = Array.from(new Set(state.students.map((student) => student.grade || "").filter(Boolean)))
      .sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true }));
    gradeFilter.innerHTML = "<option value='all'>All Grades</option>";
    grades.forEach((grade) => {
      const option = document.createElement("option");
      option.value = grade;
      option.textContent = grade;
      gradeFilter.appendChild(option);
    });
    gradeFilter.value = grades.includes(current) ? current : "all";
    studentTableFilterGrade = gradeFilter.value;
  }
  const studentFilterInput = document.getElementById("student-table-filter-student");
  if (studentFilterInput && studentFilterInput.value !== studentTableFilterStudent) studentFilterInput.value = studentTableFilterStudent;
  const statusFilter = document.getElementById("student-table-filter-status");
  if (statusFilter && statusFilter.value !== studentTableFilterStatus) statusFilter.value = studentTableFilterStatus;
  const requiredFilter = document.getElementById("student-table-filter-required");
  if (requiredFilter && requiredFilter.value !== studentTableFilterRequired) requiredFilter.value = studentTableFilterRequired;
  const studentNeedles = (studentTableFilterStudent || "")
    .split(",")
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);
  const filteredStudents = state.students
    .slice()
    .sort((a, b) => {
      const archivedDelta = Number(studentIsArchived(a)) - Number(studentIsArchived(b));
      if (archivedDelta) return archivedDelta;
      return `${a.lastName || ""} ${a.firstName || ""}`.localeCompare(`${b.lastName || ""} ${b.firstName || ""}`);
    })
    .filter((student) => {
      const archived = studentIsArchived(student);
      const { requiredComplete } = studentRequiredFocusForList(student.id);
      const fullName = `${student.firstName || ""} ${student.lastName || ""}`.toLowerCase();
      if (studentNeedles.length && !studentNeedles.some((needle) => fullName.includes(needle))) return false;
      if (studentTableFilterGrade !== "all" && student.grade !== studentTableFilterGrade) return false;
      if (studentTableFilterStatus === "active" && archived) return false;
      if (studentTableFilterStatus === "archived" && !archived) return false;
      if (archived && studentTableFilterRequired !== "all") return false;
      if (studentTableFilterRequired === "yes" && !requiredComplete) return false;
      if (studentTableFilterRequired === "no" && requiredComplete) return false;
      return true;
    });
  renderStudentWorkQueueSummary(filteredStudents);
  const rows = filteredStudents.map((s) => {
    const ageNow = calculateAge(s.birthdate);
    const overallAvg = studentOverallAverage(s.id);
    const absences = studentAbsenceCount(s.id);
    const archived = studentIsArchived(s);
    const { focusSubject, missingSubjects: missingRequiredSubjects, requiredComplete, notEvaluated } = studentRequiredFocusForList(s.id);
    const status = archived
      ? `<span class="student-status-pill archived">Archived</span>`
      : `<span class="student-status-pill">Active</span>`;
      const missingSubjectText = missingRequiredSubjects.map((subject) => subject.name).join(", ");
      const rowReason = notEvaluated
        ? "Required compliance not evaluated for archived students"
        : requiredComplete
          ? (focusSubject ? `${focusSubject.name} is enrolled` : "Required subjects complete")
          : (focusSubject ? `Missing ${focusSubject.name}` : `Missing ${missingRequiredSubjects.length} required subject${missingRequiredSubjects.length === 1 ? "" : "s"}`);
      const requiredCell = notEvaluated
        ? `<div class="student-required-cell"><span class="student-required-status neutral">Not Evaluated</span><small>${escapeHtml(rowReason)}</small></div>`
        : requiredComplete
        ? `<div class="student-required-cell"><span class="student-required-status yes">Compliant</span><small>${escapeHtml(rowReason)}</small></div>`
        : `<div class="student-required-cell"><span class="student-required-status no" title="${escapeHtml(missingSubjectText)}">Not In Compliance</span><small>${escapeHtml(missingSubjectText || rowReason)}</small></div>`;
      const restoreButton = archived ? `<button data-restore-student='${s.id}' type='button'>Restore</button>` : "";
      const actionLabel = archived ? "View" : requiredComplete ? "Edit/Enroll" : "Fix Enrollment";
      const focusSubjectId = !archived && !requiredComplete ? (focusSubject?.id || missingRequiredSubjects[0]?.id || "") : "";
      const focusAttr = focusSubjectId ? ` data-student-open-focus-subject="${escapeHtml(focusSubjectId)}"` : "";
      return `<tr class="${requiredComplete || archived ? "" : "student-work-queue-row"}"><td><div class="student-name-cell"><strong>${escapeHtml(s.firstName)} ${escapeHtml(s.lastName)}</strong><small>${escapeHtml(rowReason)}</small></div></td><td>${escapeHtml(s.grade)}</td><td>${ageNow}</td><td>${status}</td><td>${requiredCell}</td><td>${overallAvg.toFixed(1)}%</td><td>${absences}</td><td class="student-table-actions"><div class="table-action-row"><button data-edit-student='${s.id}'${focusAttr} type='button'>${actionLabel}</button>${restoreButton}</div></td></tr>`;
    });
  rowOrEmpty(document.getElementById("student-table"), rows, "No students match the selected filters.", 8);
}

function renderInstructors() {
  if (!isAdminUser()) return;
  const tableBody = document.getElementById("instructor-table");
  if (!tableBody) return;
  const rows = state.instructors
    .slice()
    .sort((a, b) => `${a.lastName} ${a.firstName}`.localeCompare(`${b.lastName} ${b.firstName}`))
    .map((instructor) => {
      const ageNow = calculateAge(instructor.birthdate);
      return `<tr><td>${escapeHtml(instructor.firstName)} ${escapeHtml(instructor.lastName)}</td><td>${escapeHtml(getInstructorCategoryLabel(instructor.category))}</td><td>${escapeHtml(getInstructorEducationLevelLabel(instructor.educationLevel))}</td><td>${escapeHtml(formatDisplayDate(instructor.birthdate))}</td><td>${ageNow}</td><td><div class="table-action-row"><button data-edit-instructor="${instructor.id}" type="button">Edit</button><button data-remove-instructor="${instructor.id}" type="button">Remove</button></div></td></tr>`;
    });
  rowOrEmpty(tableBody, rows, "No instructors added yet.", 6);
}

function renderSubjects() {
  const tableBody = document.getElementById("subject-table");
  if (!tableBody) return;
  const rows = state.subjects
    .map((s) => {
      const inputId = `subject-required-${s.id}`;
      return `<tr><td>${escapeHtml(s.name)}</td><td><input id="${inputId}" class="subject-required-toggle" data-subject-required-id="${s.id}" type="checkbox"${s.required ? " checked" : ""} aria-label="Required subject: ${escapeHtml(s.name)}"></td><td><button data-remove-subject='${s.id}' type='button'>Remove</button></td></tr>`;
    });
  rowOrEmpty(tableBody, rows, "No subjects added yet.", 3);
}

function renderManagementSectionVisibility() {
  const mappings = [
    { wrapId: "management-subjects-wrap", tab: "subjects" },
    { wrapId: "management-courses-wrap", tab: "courses" },
    { wrapId: "management-grade-types-wrap", tab: "grade-types" },
    { wrapId: "management-grading-criteria-wrap", tab: "grading-criteria" }
  ];
  mappings.forEach((entry) => {
    const wrap = document.getElementById(entry.wrapId);
    if (!wrap) return;
    wrap.classList.toggle("hidden", entry.tab !== currentManagementTab);
  });
  document.querySelectorAll("[data-management-tab]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-management-tab") === currentManagementTab);
  });
  if (currentManagementTab === "courses") {
    renderManagementCoursesSectionVisibility();
  }
}

function effectiveInstructionOrderIndex(studentId, courseId, date, fallbackOrderIndex = null) {
  const existing = findInstructionActualRecord(studentId, courseId, date);
  if (existing && Number.isInteger(existing.orderIndex) && existing.orderIndex > 0) {
    return existing.orderIndex;
  }
  return Number.isFinite(fallbackOrderIndex) ? fallbackOrderIndex : null;
}

function hasInstructionOrderOverride(studentId, courseId, date) {
  const existing = findInstructionActualRecord(studentId, courseId, date);
  return !!(existing && Number.isInteger(existing.orderIndex) && existing.orderIndex > 0);
}

function studentEnrolledCourseIds(studentId, sourceEnrollments = state.enrollments, sourceSectionEnrollments = state.sectionEnrollments) {
  const enrolledCourseIds = new Set(
    sourceEnrollments
      .filter((enrollment) => enrollment.studentId === studentId)
      .map((enrollment) => enrollment.courseId)
  );
  sourceSectionEnrollments
    .filter((entry) => entry.studentId === studentId)
    .forEach((entry) => {
      const section = getCourseSection(entry.courseSectionId);
      if (section?.courseId) enrolledCourseIds.add(section.courseId);
    });
  return enrolledCourseIds;
}

function studentMissingRequiredSubjects(studentId) {
  const student = state.students.find((entry) => entry.id === studentId);
  if (studentIsArchived(student)) return [];
  const requiredSubjects = state.subjects.filter((subject) => subject.required);
  if (!requiredSubjects.length) return [];
  const enrolledCourseIds = studentEnrolledCourseIds(studentId);
  const enrolledSubjectIds = new Set(
    Array.from(enrolledCourseIds)
      .map((courseId) => getCourse(courseId)?.subjectId || "")
      .filter(Boolean)
  );
  return requiredSubjects
    .filter((subject) => !enrolledSubjectIds.has(subject.id))
    .sort((a, b) => a.name.localeCompare(b.name));
}

function studentHasAllRequiredSubjects(studentId) {
  return studentMissingRequiredSubjects(studentId).length === 0;
}

function studentHasRequiredSubject(studentId, subjectId) {
  if (!studentId || !subjectId) return false;
  const enrolledCourseIds = studentEnrolledCourseIds(studentId);
  return Array.from(enrolledCourseIds).some((courseId) => getCourse(courseId)?.subjectId === subjectId);
}

function renderStudentDetailRequiredCallout(student, missingSubjects = []) {
  const callout = document.getElementById("student-detail-required-callout");
  if (!callout) return;
  if (!student || !missingSubjects.length) {
    callout.classList.add("hidden");
    callout.innerHTML = "";
    return;
  }
  const studentName = `${student.firstName || ""} ${student.lastName || ""}`.trim();
  callout.classList.remove("hidden");
  callout.innerHTML = `
    <div>
      <strong>Missing Required Subjects</strong>
      <p>${escapeHtml(studentName)} still needs scheduled work for ${missingSubjects.length} required subject${missingSubjects.length === 1 ? "" : "s"}.</p>
    </div>
    <div class="student-detail-required-chip-row">
      ${missingSubjects.map((subject) => `<button type="button" data-student-required-subject-focus="${escapeHtml(subject.id)}">${escapeHtml(subject.name)}</button>`).join("")}
    </div>`;
}

function requiredSubjectComplianceStudents() {
  const selectedStudentIds = new Set(requiredSubjectComplianceSelectedStudentIds);
  const requiredSubjects = state.subjects.filter((subject) => subject.required);
  return visibleStudents()
    .filter((student) => {
      if (selectedStudentIds.size && !selectedStudentIds.has(student.id)) return false;
      if (requiredSubjectComplianceGrade !== "all" && student.grade !== requiredSubjectComplianceGrade) return false;
      if (requiredSubjectComplianceStatus !== "all") {
        const compliant = requiredSubjects.every((subject) => studentHasRequiredSubject(student.id, subject.id));
        if (requiredSubjectComplianceStatus === "compliant" && !compliant) return false;
        if (requiredSubjectComplianceStatus === "not-compliant" && compliant) return false;
      }
      return true;
    })
    .sort((a, b) => `${a.lastName || ""} ${a.firstName || ""}`.localeCompare(`${b.lastName || ""} ${b.firstName || ""}`));
}

function isStudentEnrolledInCourse(studentId, courseId, sourceEnrollments = state.enrollments) {
  if (sourceEnrollments.some((enrollment) =>
    enrollment.studentId === studentId
    && enrollment.courseId === courseId)) {
    return true;
  }
  return !!courseSectionForStudentCourse(studentId, courseId);
}

function legacyInstructionPlansActive() {
  return LEGACY_INSTRUCTION_PLANS_ACTIVE;
}

function normalizeScheduleTab(tab) {
  return ACTIVE_SCHEDULE_TABS.has(tab) ? tab : DEFAULT_SCHEDULE_TAB;
}

function removePlansForStudentCourse(studentId, courseId) {
  state.plans = state.plans.filter((plan) =>
    !(plan.studentId === studentId && plan.courseId === courseId));
}

function renderScheduleSectionVisibility() {
  currentScheduleTab = normalizeScheduleTab(currentScheduleTab);
  const mappings = [
    { wrapId: "schedule-school-years-wrap", tab: "school-years" },
    { wrapId: "schedule-quarters-wrap", tab: "quarters" },
    { wrapId: "schedule-school-day-wrap", tab: "school-day" },
    { wrapId: "schedule-daily-breaks-wrap", tab: "daily-breaks" },
    { wrapId: "schedule-holidays-wrap", tab: "holidays" }
  ];
  if (legacyInstructionPlansActive()) {
    mappings.push({ wrapId: "schedule-plans-wrap", tab: "plans" });
  }
  mappings.forEach((entry) => {
    const wrap = document.getElementById(entry.wrapId);
    if (!wrap) return;
    wrap.classList.toggle("hidden", entry.tab !== currentScheduleTab);
  });
  if (!legacyInstructionPlansActive()) {
    const planWrap = document.getElementById("schedule-plans-wrap");
    if (planWrap) planWrap.classList.add("hidden");
  }
  document.querySelectorAll("[data-schedule-tab]").forEach((btn) => {
    const tab = btn.getAttribute("data-schedule-tab");
    const enabled = ACTIVE_SCHEDULE_TABS.has(tab) || (tab === "plans" && legacyInstructionPlansActive());
    btn.classList.toggle("hidden", !enabled);
    btn.disabled = !enabled;
    btn.classList.toggle("active", enabled && tab === currentScheduleTab);
  });
}

function renderCourses() {
  const tableBody = document.getElementById("course-table");
  const submitBtn = document.getElementById("course-submit-btn");
  const cancelBtn = document.getElementById("course-cancel-edit-btn");
  const form = document.getElementById("course-form");
  const showFormBtn = document.getElementById("course-show-form-btn");
  if (form) form.classList.toggle("hidden", !courseFormOpen);
  if (showFormBtn) showFormBtn.classList.toggle("hidden", courseFormOpen);
  if (submitBtn) submitBtn.textContent = editingCourseId ? "Update Course" : "Add Course";
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !courseFormOpen);
  renderCourseQuarterChecklist(getSelectedCourseQuarterNames());
  renderCourseMaterialsDraft();
  if (!tableBody) return;
  const rows = state.courses
    .filter((c) => courseReadinessFilter !== "no-flex-enrollment" || courseNeedsEnrollmentReview(c))
    .map((c) => {
      const subjectCell = `${escapeHtml(getSubjectName(c.subjectId))} ${isRequiredSubject(c.subjectId) ? requiredSubjectBadge(c.subjectId) : ""}`;
      const enrolledCount = courseStudentIdsForReadiness(c.id).size;
      const needsReview = courseNeedsEnrollmentReview(c);
      const enrolledCell = `<span class="enrollment-count-pill${needsReview ? " empty" : ""}">${enrolledCount}</span>${needsReview ? `<span class="enrollment-count-note">No students enrolled</span>` : ""}`;
      return `<tr class="${needsReview ? "readiness-review-row" : ""}"><td>${renderScheduleSourceCell(c.name, courseSchoolDayMeta(c))}</td><td>${subjectCell}</td><td>${escapeHtml(c.instructorId ? getInstructorName(c.instructorId) : "Unassigned")}</td><td>${escapeHtml(dailyMinutesSummary(c.hoursPerDay))}</td><td>${enrolledCell}</td><td class="course-table-actions"><div class="table-action-row"><button data-edit-course='${c.id}' type='button'>Edit</button><button data-remove-course='${c.id}' type='button'>Remove</button></div></td></tr>`;
    });
  rowOrEmpty(tableBody, rows, courseReadinessFilter === "no-flex-enrollment" ? "No flexible courses need enrollment review." : "No courses added yet.", 6);
  renderCourseReadinessFilterPanel(rows.length);
  renderCourseSections();
  renderManagementCoursesSectionVisibility();
  renderSchoolDayReadinessPanels();
}

function scrollManagementEditorIntoView(formId, focusSelector) {
  requestAnimationFrame(() => {
    const form = document.getElementById(formId);
    if (!form || form.classList.contains("hidden")) return;
    const target = form.closest(".card") || form;
    const top = Math.max(0, window.scrollY + target.getBoundingClientRect().top - 84);
    window.scrollTo({ top, behavior: "smooth" });
    const focusTarget = focusSelector ? form.querySelector(focusSelector) : null;
    if (!focusTarget) return;
    try {
      focusTarget.focus({ preventScroll: true });
    } catch (error) {
      focusTarget.focus();
    }
  });
}

function renderQuarterChecklist({ optionsWrapId, summaryId, checkboxClass, selectedNames = [] }) {
  const optionsWrap = document.getElementById(optionsWrapId);
  const summary = document.getElementById(summaryId);
  if (!optionsWrap || !summary) return;
  const selected = new Set(selectedNames || []);
  const quarters = state.settings.quarters || [];
  if (!quarters.length) {
    optionsWrap.innerHTML = `<span>No quarters configured.</span>`;
    summary.textContent = "All Quarters";
    return;
  }
  optionsWrap.innerHTML = quarters.map((quarter, index) => {
    const inputId = `${optionsWrapId}-${index}`;
    const checked = selected.has(quarter.name) ? " checked" : "";
    return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="${checkboxClass}" value="${escapeHtml(quarter.name)}"${checked}><label for="${inputId}">${escapeHtml(quarter.name)}</label></div>`;
  }).join("");
  summary.textContent = selected.size
    ? `${selected.size} quarter${selected.size === 1 ? "" : "s"} selected`
    : "All Quarters";
}

function renderCourseQuarterChecklist(selectedNames = []) {
  renderQuarterChecklist({
    optionsWrapId: "course-quarters-options",
    summaryId: "course-quarters-summary",
    checkboxClass: "course-quarter-checkbox",
    selectedNames
  });
}

function renderCourseSectionQuarterChecklist(selectedNames = []) {
  renderQuarterChecklist({
    optionsWrapId: "course-section-quarters-options",
    summaryId: "course-section-quarters-summary",
    checkboxClass: "course-section-quarter-checkbox",
    selectedNames
  });
}

function courseSectionStudentName(student) {
  return `${student?.firstName || ""} ${student?.lastName || ""}`.trim() || "Unnamed student";
}

function effectiveCourseSectionQuarterNames(section) {
  const sectionNames = normalizeQuarterNames(section?.quarterNames);
  if (sectionNames.length) return sectionNames;
  return normalizeQuarterNames(getCourse(section?.courseId)?.quarterNames);
}

function quarterNameSetsOverlap(firstNames = [], secondNames = []) {
  const first = new Set(firstNames.filter(Boolean));
  const second = new Set(secondNames.filter(Boolean));
  if (!first.size || !second.size) return true;
  return [...first].some((name) => second.has(name));
}

function courseSectionDurationMinutes(section) {
  const hoursPerDay = Number(getCourse(section?.courseId)?.hoursPerDay || 1);
  return Math.max(15, Math.round((Number.isFinite(hoursPerDay) && hoursPerDay > 0 ? hoursPerDay : 1) * 60));
}

function courseSectionTimeWindow(section) {
  const start = parseTimeToMinutes(section?.startTime || "08:00");
  const durationMinutes = courseSectionDurationMinutes(section);
  if (!Number.isFinite(start)) return null;
  return { start, end: Math.min(24 * 60, start + durationMinutes) };
}

function courseSectionsHaveTimeConflict(firstSection, secondSection) {
  if (!firstSection || !secondSection || firstSection.id === secondSection.id) return false;
  if (firstSection.courseId && firstSection.courseId === secondSection.courseId) return false;
  const firstWeekdays = normalizeWeekdays(firstSection.weekdays, [1, 2, 3, 4, 5]);
  const secondWeekdays = normalizeWeekdays(secondSection.weekdays, [1, 2, 3, 4, 5]);
  if (!firstWeekdays.some((day) => secondWeekdays.includes(day))) return false;
  if (!quarterNameSetsOverlap(effectiveCourseSectionQuarterNames(firstSection), effectiveCourseSectionQuarterNames(secondSection))) return false;
  const firstWindow = courseSectionTimeWindow(firstSection);
  const secondWindow = courseSectionTimeWindow(secondSection);
  if (!firstWindow || !secondWindow) return false;
  return firstWindow.start < secondWindow.end && firstWindow.end > secondWindow.start;
}

function courseSectionConflictDisplay(section) {
  return `${sectionDisplayName(section.id)}, ${weekdaySummary(section.weekdays)}, ${formatClockTime(section.startTime || "08:00")}`;
}

function courseSectionDraftFromForm({ courseId = null, startTime = null, quarterNames = null, weekdays = null } = {}) {
  return {
    id: editingCourseSectionId || "__new-course-section__",
    courseId: courseId ?? (document.getElementById("course-section-course")?.value || ""),
    label: document.getElementById("course-section-label")?.value?.trim() || "Class",
    startTime: startTime ?? (document.getElementById("course-section-start-time")?.value || "08:00"),
    quarterNames: quarterNames ?? getSelectedCourseSectionQuarterNames(),
    weekdays: weekdays ?? Array.from(document.querySelectorAll("input[name='course-section-weekday']:checked")).map((checkbox) => Number(checkbox.value))
  };
}

function courseSectionConflictForStudent(studentId, draftSection) {
  if (!studentId || !draftSection?.courseId) return null;
  return state.sectionEnrollments
    .filter((entry) => entry.studentId === studentId && entry.courseSectionId !== draftSection.id)
    .map((entry) => getCourseSection(entry.courseSectionId))
    .filter(Boolean)
    .find((section) => courseSectionsHaveTimeConflict(draftSection, section)) || null;
}

function courseSectionConflictMessages(draftSection, selectedStudentIds = []) {
  return selectedStudentIds
    .map((studentId) => {
      const conflictSection = courseSectionConflictForStudent(studentId, draftSection);
      if (!conflictSection) return "";
      return `${getStudentName(studentId)} conflicts with ${courseSectionConflictDisplay(conflictSection)}.`;
    })
    .filter(Boolean);
}

function updateCourseSectionStudentSummary() {
  const summary = document.getElementById("course-section-students-summary");
  const allCheckbox = document.getElementById("course-section-student-all");
  const studentCheckboxes = Array.from(document.querySelectorAll(".course-section-student-checkbox"));
  const selectedCount = studentCheckboxes.filter((checkbox) => checkbox.checked).length;
  if (summary) {
    summary.textContent = selectedCount
      ? `${selectedCount} student${selectedCount === 1 ? "" : "s"} selected`
      : "No students selected";
  }
  if (allCheckbox instanceof HTMLInputElement) {
    allCheckbox.checked = !!studentCheckboxes.length && selectedCount === studentCheckboxes.length;
    allCheckbox.indeterminate = selectedCount > 0 && selectedCount < studentCheckboxes.length;
  }
}

function renderCourseSectionStudentChecklist(selectedStudentIds = []) {
  const optionsWrap = document.getElementById("course-section-students-options");
  const summary = document.getElementById("course-section-students-summary");
  if (!optionsWrap || !summary) return;
  const students = visibleStudents()
    .slice()
    .sort((a, b) => courseSectionStudentName(a).localeCompare(courseSectionStudentName(b), undefined, { numeric: true }));
  const selected = new Set(selectedStudentIds || []);
  if (!students.length) {
    optionsWrap.innerHTML = "<span>No active students.</span>";
    summary.textContent = "No students available";
    return;
  }
  const courseId = document.getElementById("course-section-course")?.value || "";
  const draftSection = courseSectionDraftFromForm({ courseId });
  const selectedActiveCount = students.filter((student) => selected.has(student.id)).length;
  const allChecked = selectedActiveCount === students.length;
  const allRow = `<div class="checklist-row course-section-student-all-row"><input id="course-section-student-all" type="checkbox" class="course-section-student-all-checkbox"${allChecked ? " checked" : ""}><label for="course-section-student-all">All active students</label></div>`;
  const rows = students.map((student, index) => {
    const inputId = `course-section-student-${index}`;
    const checked = selected.has(student.id) ? " checked" : "";
    const existingCourseEnrollment = courseId
      ? courseSectionEnrollmentForStudentInCourse(student.id, courseId, editingCourseSectionId)
      : null;
    const existingFlexibleEnrollment = courseId ? courseEnrollmentForStudentCourse(student.id, courseId) : null;
    const conflictSection = courseSectionConflictForStudent(student.id, draftSection);
    const meta = [
      student.grade ? `Grade ${student.grade}` : "",
      existingCourseEnrollment ? `Currently in ${sectionDisplayName(existingCourseEnrollment.courseSectionId)}` : "",
      existingFlexibleEnrollment ? "Currently enrolled outside a class" : "",
      conflictSection ? `Conflict: ${courseSectionConflictDisplay(conflictSection)}` : ""
    ].filter(Boolean);
    return `<div class="checklist-row course-section-student-row${conflictSection ? " course-section-student-conflict-row" : ""}"><input id="${inputId}" type="checkbox" class="course-section-student-checkbox" value="${escapeHtml(student.id)}"${checked}><label for="${inputId}">${renderScheduleSourceCell(courseSectionStudentName(student), meta)}</label></div>`;
  }).join("");
  optionsWrap.innerHTML = `${allRow}${rows}`;
  updateCourseSectionStudentSummary();
}

function getSelectedQuarterNames(checkboxClass) {
  return Array.from(document.querySelectorAll(`.${checkboxClass}:checked`)).map((checkbox) => checkbox.value);
}

function getSelectedCourseQuarterNames() {
  return getSelectedQuarterNames("course-quarter-checkbox");
}

function getSelectedCourseSectionQuarterNames() {
  return getSelectedQuarterNames("course-section-quarter-checkbox");
}

function getSelectedCourseSectionStudentIds() {
  return Array.from(document.querySelectorAll(".course-section-student-checkbox:checked"))
    .map((checkbox) => checkbox.value)
    .filter(Boolean);
}

function setCourseWeekdaySelection(weekdays = [1, 2, 3, 4, 5]) {
  const selected = new Set(normalizeWeekdays(weekdays, [1, 2, 3, 4, 5]));
  document.querySelectorAll("input[name='course-weekday']").forEach((checkbox) => {
    checkbox.checked = selected.has(Number(checkbox.value));
  });
}

function weekdaySummary(weekdays, fallback = [1, 2, 3, 4, 5]) {
  const days = normalizeWeekdays(weekdays, fallback);
  if (days.length === 5 && days.every((day, index) => day === index + 1)) return "Mon-Fri";
  return days.map((day) => DAY_NAMES[day]).filter(Boolean).join(", ") || "No weekdays";
}

function quarterSummary(quarterNames, fallbackLabel = "All quarters") {
  const names = Array.isArray(quarterNames) ? quarterNames.filter(Boolean) : [];
  return names.length ? names.join(", ") : fallbackLabel;
}

function courseHoursToDailyMinutes(hoursPerDay) {
  const minutes = Math.round(Number(hoursPerDay || 0) * 60);
  return Number.isFinite(minutes) ? minutes : 0;
}

function courseDailyMinutesToHours(minutesPerDay) {
  const minutes = Number(minutesPerDay || 0);
  return Number.isFinite(minutes) ? minutes / 60 : 0;
}

function dailyMinutesSummary(hoursPerDay) {
  const minutes = courseHoursToDailyMinutes(hoursPerDay);
  return minutes > 0 ? `${minutes} min/day` : "No daily minutes";
}

function durationMinutesSummary(durationMinutes) {
  const minutes = Number(durationMinutes || 0);
  return minutes > 0 ? `${minutes} min` : "No duration";
}

function renderScheduleSourceMeta(items = []) {
  const filtered = items.map((item) => String(item || "").trim()).filter(Boolean);
  if (!filtered.length) return "";
  return `<div class="schedule-source-meta">${filtered.map((item) => `<span>${escapeHtml(item)}</span>`).join("")}</div>`;
}

function renderScheduleSourceCell(title, metaItems = [], extraHtml = "") {
  return `<div class="schedule-source-cell"><strong>${escapeHtml(title)}</strong>${extraHtml || ""}${renderScheduleSourceMeta(metaItems)}</div>`;
}

function courseSchoolDayMeta(course) {
  if (!course) return [];
  const classCount = getCourseSectionsForCourse(course.id).length;
  return [
    classCount ? `${classCount} class${classCount === 1 ? "" : "es"}` : "Flexible order",
    dailyMinutesSummary(course.hoursPerDay),
    weekdaySummary(course.weekdays),
    quarterSummary(course.quarterNames)
  ];
}

function courseSectionSchoolDayMeta(section) {
  if (!section) return [];
  const instructorId = assignedInstructorIdForCourseSection(section.id);
  const course = getCourse(section.courseId);
  return [
    instructorId ? `Instructor: ${getInstructorName(instructorId)}` : "Instructor: Unassigned",
    dailyMinutesSummary(course?.hoursPerDay),
    `Fixed ${formatClockTime(section.startTime || "08:00")}`,
    weekdaySummary(section.weekdays),
    quarterSummary(section.quarterNames, "Course quarters"),
    `${courseSectionEnrollmentCount(section.id)} enrolled`
  ];
}

function scheduleBlockSchoolDayMeta(block) {
  if (!block) return [];
  return [
    durationMinutesSummary(block.durationMinutes),
    weekdaySummary(block.weekdays),
    "Assigned per student"
  ];
}

function studentScheduledEntrySchoolDayMeta(entry) {
  if (!entry) return [];
  if (entry.itemType === "scheduleBlock") {
    return scheduleBlockSchoolDayMeta(getScheduleBlock(entry.scheduleBlockId));
  }
  if (entry.itemType === "courseSection") {
    return courseSectionSchoolDayMeta(getCourseSection(entry.courseSectionId));
  }
  return courseSchoolDayMeta(getCourse(entry.courseId));
}

function activeStudentIdSetForReadiness() {
  return new Set(visibleStudents().map((student) => student.id));
}

function courseStudentIdsForReadiness(courseId) {
  const activeStudentIds = activeStudentIdSetForReadiness();
  const studentIds = new Set();
  state.enrollments
    .filter((entry) => entry.courseId === courseId && activeStudentIds.has(entry.studentId))
    .forEach((entry) => studentIds.add(entry.studentId));
  state.sectionEnrollments.forEach((entry) => {
    if (!activeStudentIds.has(entry.studentId)) return;
    const section = getCourseSection(entry.courseSectionId);
    if (section?.courseId === courseId) studentIds.add(entry.studentId);
  });
  return studentIds;
}

function courseHasClasses(courseId) {
  return state.courseSections.some((section) => section.courseId === courseId);
}

function courseNeedsEnrollmentReview(course) {
  return !!course && !courseHasClasses(course.id) && !courseStudentIdsForReadiness(course.id).size;
}

function classNeedsEnrollmentReview(section) {
  return !!section && courseSectionEnrollmentCount(section.id) === 0;
}

function scheduleBlockAssignedStudentIdsForReadiness(scheduleBlockId) {
  const activeStudentIds = activeStudentIdSetForReadiness();
  const studentIds = new Set();
  (state.studentScheduleBlocks || [])
    .filter((entry) => entry.scheduleBlockId === scheduleBlockId && activeStudentIds.has(entry.studentId))
    .forEach((entry) => studentIds.add(entry.studentId));
  return studentIds;
}

function scheduleBlockNeedsAssignmentReview(block) {
  return !!block && !scheduleBlockAssignedStudentIdsForReadiness(block.id).size;
}

function availableScheduledItemsForSubject(subjectId) {
  return state.courses
    .filter((course) => course.subjectId === subjectId)
    .flatMap((course) => {
      const sections = getCourseSectionsForCourse(course.id);
      return sections.length
        ? sections.map((section) => ({ type: "class", id: section.id, label: sectionDisplayName(section.id) }))
        : [{ type: "course", id: course.id, label: course.name }];
    });
}

function buildSchoolDayReadinessSnapshot() {
  const activeStudents = visibleStudents();
  const classesWithoutStudents = sortedCourseSections()
    .filter((section) => classNeedsEnrollmentReview(section));
  const flexibleCoursesWithoutStudents = state.courses
    .filter((course) => courseNeedsEnrollmentReview(course));
  const requiredSubjectsWithoutItems = state.subjects
    .filter((subject) => subject.required && !availableScheduledItemsForSubject(subject.id).length)
    .sort((a, b) => a.name.localeCompare(b.name));
  const studentsMissingRequired = activeStudents
    .map((student) => ({
      student,
      missingSubjects: studentMissingRequiredSubjects(student.id)
    }))
    .filter((entry) => entry.missingSubjects.length);
  const unassignedScheduleBlocks = (state.scheduleBlocks || [])
    .filter((block) => scheduleBlockNeedsAssignmentReview(block));
  const issues = [
    {
      id: "courses",
      label: "Flexible Courses",
      count: flexibleCoursesWithoutStudents.length,
      detail: flexibleCoursesWithoutStudents.length
        ? `${flexibleCoursesWithoutStudents.length} course${flexibleCoursesWithoutStudents.length === 1 ? "" : "s"} have no enrolled students.`
        : "All flexible courses have enrolled students.",
      action: "courses",
      actionLabel: "Review Courses"
    },
    {
      id: "classes",
      label: "Classes",
      count: classesWithoutStudents.length,
      detail: classesWithoutStudents.length
        ? `${classesWithoutStudents.length} class${classesWithoutStudents.length === 1 ? "" : "es"} have no enrolled students.`
        : "All classes have enrolled students.",
      action: "classes",
      actionLabel: "Review Classes"
    },
    {
      id: "required-items",
      label: "Required Subjects",
      count: requiredSubjectsWithoutItems.length,
      detail: requiredSubjectsWithoutItems.length
        ? `${requiredSubjectsWithoutItems.length} required subject${requiredSubjectsWithoutItems.length === 1 ? "" : "s"} have no scheduled item available.`
        : "Every required subject has a scheduled item available.",
      action: "subjects",
      actionLabel: "Review Subjects"
    },
    {
      id: "student-compliance",
      label: "Student Compliance",
      count: studentsMissingRequired.length,
      detail: studentsMissingRequired.length
        ? `${studentsMissingRequired.length} student${studentsMissingRequired.length === 1 ? "" : "s"} are missing required subjects.`
        : "All active students meet required subject enrollment.",
      action: "students-required",
      actionLabel: "Review Students"
    },
    {
      id: "blocks",
      label: "Schedule Blocks",
      count: unassignedScheduleBlocks.length,
      detail: unassignedScheduleBlocks.length
        ? `${unassignedScheduleBlocks.length} schedule block${unassignedScheduleBlocks.length === 1 ? "" : "s"} are not assigned to any student.`
        : "All schedule blocks are assigned to at least one student.",
      action: "schedule-blocks",
      actionLabel: "Review Blocks"
    }
  ];
  const issueCount = issues.reduce((sum, issue) => sum + issue.count, 0);
  const clearCount = issues.filter((issue) => issue.count === 0).length;
  return {
    issues,
    issueCount,
    clearCount,
    flexibleCoursesWithoutStudents,
    classesWithoutStudents,
    requiredSubjectsWithoutItems,
    studentsMissingRequired,
    unassignedScheduleBlocks
  };
}

function renderReadinessIssueRow(issue) {
  const stateLabel = issue.count ? "Review" : "Ready";
  const stateClass = issue.count ? "needs-review" : "ready";
  const action = issue.count
    ? `<button type="button" data-school-day-readiness-action="${escapeHtml(issue.action)}">${escapeHtml(issue.actionLabel)}</button>`
    : "";
  return `<div class="school-day-readiness-row ${stateClass}">
    <span class="school-day-readiness-status">${stateLabel}</span>
    <div class="school-day-readiness-copy">
      <strong>${escapeHtml(issue.label)}</strong>
      <span>${escapeHtml(issue.detail)}</span>
    </div>
    ${action}
  </div>`;
}

function renderSchoolDayReadinessPanels() {
  const snapshot = buildSchoolDayReadinessSnapshot();
  const panel = document.getElementById("school-day-readiness-panel");
  if (panel) {
    panel.innerHTML = `
      <div class="school-day-readiness-header">
        <div>
          <strong>School Day Readiness</strong>
          <span>${snapshot.issueCount ? `${snapshot.issueCount} setup item${snapshot.issueCount === 1 ? "" : "s"} need review before School Day is fully predictable.` : "Source setup looks ready for School Day."}</span>
        </div>
        <div class="school-day-readiness-score">${snapshot.clearCount}/5 clear</div>
      </div>
      <div class="school-day-readiness-grid">
        ${snapshot.issues.map(renderReadinessIssueRow).join("")}
      </div>`;
  }

  const blockPanel = document.getElementById("schedule-block-readiness-panel");
  if (blockPanel) {
    const blockIssue = snapshot.issues.find((issue) => issue.id === "blocks");
    blockPanel.innerHTML = blockIssue
      ? `<div class="school-day-readiness-header">
          <div>
            <strong>Schedule Block Readiness</strong>
            <span>${escapeHtml(blockIssue.detail)}</span>
          </div>
          ${blockIssue.count ? `<button type="button" data-school-day-readiness-action="schedule-blocks">Review Blocks</button>` : `<div class="school-day-readiness-score">Ready</div>`}
        </div>`
      : "";
  }
}

function renderReadinessFilterPanel({ panelId, active, title, detail, clearAction }) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  panel.classList.toggle("hidden", !active);
  if (!active) {
    panel.innerHTML = "";
    return;
  }
  panel.innerHTML = `
    <div>
      <strong>${escapeHtml(title)}</strong>
      <span>${escapeHtml(detail)}</span>
    </div>
    <button type="button" data-clear-readiness-filter="${escapeHtml(clearAction)}">Clear filter</button>`;
}

function renderCourseReadinessFilterPanel(visibleCount) {
  const active = courseReadinessFilter === "no-flex-enrollment";
  renderReadinessFilterPanel({
    panelId: "course-readiness-filter-panel",
    active,
    title: `Showing ${visibleCount} flexible course${visibleCount === 1 ? "" : "s"} with no enrolled students`,
    detail: "This is the same set counted by School Day Readiness > Flexible Courses.",
    clearAction: "courses"
  });
}

function renderClassReadinessFilterPanel(visibleCount) {
  const active = classReadinessFilter === "no-enrollment";
  renderReadinessFilterPanel({
    panelId: "class-readiness-filter-panel",
    active,
    title: `Showing ${visibleCount} class${visibleCount === 1 ? "" : "es"} with no enrolled students`,
    detail: "This is the same set counted by School Day Readiness > Classes.",
    clearAction: "classes"
  });
}

function renderScheduleBlockReadinessFilterPanel(visibleCount) {
  const active = scheduleBlockReadinessFilter === "unassigned";
  renderReadinessFilterPanel({
    panelId: "schedule-block-filter-panel",
    active,
    title: `Showing ${visibleCount} schedule block${visibleCount === 1 ? "" : "s"} not assigned to any active student`,
    detail: "This is the same set counted by School Day Readiness > Schedule Blocks.",
    clearAction: "schedule-blocks"
  });
}

function openSchoolDayReadinessAction(action) {
  if (action === "courses") {
    currentManagementTab = "courses";
    currentManagementCoursesTab = "course-form";
    courseReadinessFilter = "no-flex-enrollment";
    classReadinessFilter = "";
    scheduleBlockReadinessFilter = "";
    activateTab("management");
    return;
  }
  if (action === "classes") {
    currentManagementTab = "courses";
    currentManagementCoursesTab = "course-sections";
    classReadinessFilter = "no-enrollment";
    courseReadinessFilter = "";
    scheduleBlockReadinessFilter = "";
    activateTab("management");
    return;
  }
  if (action === "subjects") {
    currentManagementTab = "subjects";
    activateTab("management");
    return;
  }
  if (action === "schedule-blocks") {
    currentScheduleTab = "daily-breaks";
    scheduleBlockReadinessFilter = "unassigned";
    courseReadinessFilter = "";
    classReadinessFilter = "";
    activateTab("planning");
    return;
  }
  if (action === "students-required") {
    studentTableFilterStudent = "";
    studentTableFilterGrade = "all";
    studentTableFilterStatus = "active";
    studentTableFilterRequired = "no";
    studentTableRequiredSubjectFilterId = "";
    studentsDashboardReturnContext = null;
    setStudentViewMode("list");
    activateTab("students");
    return;
  }
  if (action === "students") {
    studentTableFilterStudent = "";
    studentTableFilterGrade = "all";
    studentTableFilterStatus = "active";
    studentTableFilterRequired = "all";
    studentTableRequiredSubjectFilterId = "";
    studentsDashboardReturnContext = null;
    setStudentViewMode("list");
    activateTab("students");
  }
}

function clearReadinessFilter(target) {
  if (target === "courses") {
    courseReadinessFilter = "";
    renderCourses();
    return;
  }
  if (target === "classes") {
    classReadinessFilter = "";
    renderCourseSections();
    return;
  }
  if (target === "schedule-blocks") {
    scheduleBlockReadinessFilter = "";
    renderScheduleBlocks();
  }
}

function syncCourseSectionFormFromCourse(courseId, { preserveExisting = true } = {}) {
  const course = getCourse(courseId);
  const resourceGroupInput = document.getElementById("course-section-resource-group");
  const capacityInput = document.getElementById("course-section-capacity");
  const instructorInput = document.getElementById("course-section-instructor");
  if (!course || !resourceGroupInput || !capacityInput) return;
  if (!preserveExisting && instructorInput) {
    instructorInput.value = "";
  }
  if (!preserveExisting || !resourceGroupInput.value.trim()) {
    resourceGroupInput.value = courseResourceGroup(course);
  }
  if (!preserveExisting || !capacityInput.value.trim()) {
    const capacity = courseResourceCapacity(course);
    capacityInput.value = capacity == null ? "" : String(capacity);
  }
  if (!preserveExisting || !getSelectedCourseSectionQuarterNames().length) {
    renderCourseSectionQuarterChecklist(course.quarterNames || []);
  }
  renderCourseSectionStudentChecklist(getSelectedCourseSectionStudentIds());
}

function resetCourseSectionForm() {
  editingCourseSectionId = "";
  courseSectionFormOpen = false;
  const form = document.getElementById("course-section-form");
  if (form) form.reset();
  document.querySelectorAll("input[name='course-section-weekday']").forEach((checkbox) => {
    checkbox.checked = true;
  });
  renderCourseSectionQuarterChecklist([]);
  renderCourseSectionStudentChecklist([]);
  const timeInput = document.getElementById("course-section-start-time");
  if (timeInput) timeInput.value = normalizeSchoolDayStartTime(currentSchoolYear()?.schoolDayStartTime);
  const instructorInput = document.getElementById("course-section-instructor");
  if (instructorInput) instructorInput.value = "";
  const courseSelect = document.getElementById("course-section-course");
  if (courseSelect?.value) syncCourseSectionFormFromCourse(courseSelect.value, { preserveExisting: false });
  renderCourseSections();
}

function beginCourseSectionEdit(sectionId) {
  const section = getCourseSection(sectionId);
  if (!section) return;
  editingCourseSectionId = section.id;
  courseSectionFormOpen = true;
  document.getElementById("course-section-course").value = section.courseId;
  document.getElementById("course-section-label").value = section.label || "";
  document.getElementById("course-section-instructor").value = section.instructorId || "";
  document.getElementById("course-section-resource-group").value = section.resourceGroup || "";
  document.getElementById("course-section-capacity").value = section.concurrentCapacity == null ? "" : String(section.concurrentCapacity);
  document.getElementById("course-section-start-time").value = section.startTime || "08:00";
  renderCourseSectionQuarterChecklist(section.quarterNames || []);
  renderCourseSectionStudentChecklist(enrolledStudentIdsForCourseSection(section.id));
  document.querySelectorAll("input[name='course-section-weekday']").forEach((checkbox) => {
    checkbox.checked = Array.isArray(section.weekdays) && section.weekdays.includes(Number(checkbox.value));
  });
  renderCourseSections();
  scrollManagementEditorIntoView("course-section-form", "#course-section-course");
}

function beginCourseSectionCreate() {
  editingCourseSectionId = "";
  courseSectionFormOpen = true;
  const form = document.getElementById("course-section-form");
  if (form) form.reset();
  document.querySelectorAll("input[name='course-section-weekday']").forEach((checkbox) => {
    checkbox.checked = true;
  });
  renderCourseSectionQuarterChecklist([]);
  renderCourseSectionStudentChecklist([]);
  const timeInput = document.getElementById("course-section-start-time");
  if (timeInput) timeInput.value = normalizeSchoolDayStartTime(currentSchoolYear()?.schoolDayStartTime);
  const instructorInput = document.getElementById("course-section-instructor");
  if (instructorInput) instructorInput.value = "";
  const courseSelect = document.getElementById("course-section-course");
  if (courseSelect?.value) syncCourseSectionFormFromCourse(courseSelect.value, { preserveExisting: false });
  renderCourseSections();
  scrollManagementEditorIntoView("course-section-form", "#course-section-course");
}

function renderCourseSections() {
  const tableBody = document.getElementById("course-section-table");
  const submitBtn = document.getElementById("course-section-submit-btn");
  const form = document.getElementById("course-section-form");
  const showFormBtn = document.getElementById("course-section-show-form-btn");
  if (form) form.classList.toggle("hidden", !courseSectionFormOpen);
  if (showFormBtn) showFormBtn.classList.toggle("hidden", courseSectionFormOpen);
  if (submitBtn) submitBtn.textContent = editingCourseSectionId ? "Update Class" : "Add Class";
  renderCourseSectionQuarterChecklist(getSelectedCourseSectionQuarterNames());
  renderCourseSectionStudentChecklist(getSelectedCourseSectionStudentIds());
  if (!tableBody) return;
  const rows = sortedCourseSections()
  .filter((section) => classReadinessFilter !== "no-enrollment" || classNeedsEnrollmentReview(section))
  .map((section) => {
    const course = getCourse(section.courseId);
    const resourceSummary = section.concurrentCapacity == null
      ? (section.resourceGroup || "Unrestricted")
      : `${section.resourceGroup || getCourseName(section.courseId)} (${section.concurrentCapacity})`;
    const courseMeta = [course ? getSubjectName(course.subjectId) : "Unknown Subject"];
    if (course?.subjectId && isRequiredSubject(course.subjectId)) courseMeta.push("Required subject");
    const enrolledCount = courseSectionEnrollmentCount(section.id);
    const enrolledNames = enrolledStudentIdsForCourseSection(section.id)
      .map((studentId) => getStudentName(studentId))
      .filter(Boolean)
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
    const needsReview = classNeedsEnrollmentReview(section);
    const enrolledCell = `<span class="enrollment-count-pill${needsReview ? " empty" : ""}">${enrolledCount}</span>${enrolledNames.length ? `<span class="enrollment-count-note">${escapeHtml(enrolledNames.join(", "))}</span>` : `<span class="enrollment-count-note">No students enrolled</span>`}`;
    return `<tr class="${needsReview ? "readiness-review-row" : ""}"><td>${renderScheduleSourceCell(getCourseName(section.courseId), courseMeta)}</td><td>${renderScheduleSourceCell(section.label, ["Class row"])}</td><td>${renderScheduleSourceMeta(courseSectionSchoolDayMeta(section))}</td><td>${escapeHtml(resourceSummary)}</td><td>${enrolledCell}</td><td class="course-table-actions"><div class="table-action-row"><button data-edit-course-section='${section.id}' type='button'>Edit</button><button data-remove-course-section='${section.id}' type='button'>Remove</button></div></td></tr>`;
  });
  rowOrEmpty(tableBody, rows, classReadinessFilter === "no-enrollment" ? "No classes need enrollment review." : "No classes added yet.", 6);
  renderClassReadinessFilterPanel(rows.length);
}

function renderManagementCoursesSectionVisibility() {
  const visibleTab = currentManagementCoursesTab === "course-sections" ? "course-sections" : "course-form";
  currentManagementCoursesTab = visibleTab;
  const mappings = [
    { wrapId: "management-course-form-wrap", tab: "course-form" },
    { wrapId: "management-course-sections-wrap", tab: "course-sections" }
  ];
  mappings.forEach((entry) => {
    const wrap = document.getElementById(entry.wrapId);
    if (!wrap) return;
    wrap.classList.toggle("hidden", entry.tab !== visibleTab);
  });
  document.querySelectorAll("[data-management-courses-tab]").forEach((btn) => {
    btn.classList.toggle("active", btn.getAttribute("data-management-courses-tab") === visibleTab);
  });
}

function renderGradeTypes() {
  const tableBody = document.getElementById("grade-type-table");
  const totalEl = document.getElementById("grade-type-total");
  const submitBtn = document.getElementById("grade-type-submit-btn");
  const cancelBtn = document.getElementById("grade-type-cancel-edit-btn");
  const applyBtn = document.getElementById("grade-type-apply-btn");
  const cancelChangesBtn = document.getElementById("grade-type-cancel-changes-btn");
  if (!tableBody || !totalEl) return;
  if (!gradeTypeDraftDirty) gradeTypesDraft = cloneGradeTypes(state.settings.gradeTypes);
  renderGradeTypeIconSelect();

  const rows = draftGradeTypes().map((gt) => {
    const weightText = gt.weight == null ? "Not set" : `${Number(gt.weight).toFixed(1)}%`;
    return `<tr><td><span class="grade-type-icon-preview">${gradeTypeIconMarkup(gt.iconKey, gt.name)}</span></td><td>${escapeHtml(gt.name)}</td><td>${weightText}</td><td><button data-edit-grade-type="${gt.id}" type="button">Edit</button> <button data-remove-grade-type="${gt.id}" type="button">Remove</button></td></tr>`;
  });
  const totalWeight = draftGradeTypes().reduce((sum, gt) => sum + (gt.weight == null ? 0 : Number(gt.weight) || 0), 0);
  if (rows.length) rows.push(`<tr><td></td><td><strong>Total Weight</strong></td><td><strong>${totalWeight.toFixed(1)}%</strong></td><td></td></tr>`);
  rowOrEmpty(tableBody, rows, "No grade types configured.", 4);

  totalEl.textContent = totalWeight > 0 && Math.abs(totalWeight - 100) > 0.05
    ? `Configured Weight Total: ${totalWeight.toFixed(1)}% (remaining weight is distributed equally across unweighted grade types)`
    : `Configured Weight Total: ${totalWeight.toFixed(1)}%`;
  if (gradeTypeDraftDirty) totalEl.textContent = `${totalEl.textContent} - Pending changes not applied`;
  if (submitBtn) submitBtn.textContent = editingGradeTypeId ? "Update Grade Type" : "Add Grade Type";
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !editingGradeTypeId);
  if (applyBtn) applyBtn.disabled = !gradeTypeDraftDirty;
  if (cancelChangesBtn) {
    cancelChangesBtn.classList.toggle("hidden", !gradeTypeDraftDirty);
    cancelChangesBtn.disabled = !gradeTypeDraftDirty;
  }
}

function setGradingCriteriaMessage(kind, message) {
  const el = document.getElementById("grading-criteria-message");
  if (!el) return;
  el.className = kind ? `status-text ${kind}` : "muted";
  el.textContent = message || "";
}

function updateGradingCriteriaFormMode() {
  const scaleSelect = document.getElementById("grading-gpa-scale");
  const otherWrap = document.getElementById("grading-gpa-other-wrap");
  const otherInput = document.getElementById("grading-gpa-other");
  if (!scaleSelect || !otherWrap || !otherInput) return;
  const isOther = scaleSelect.value === "other";
  otherWrap.classList.toggle("hidden", !isOther);
  otherInput.required = gradingCriteriaEditMode && isOther;
  if (!isOther) otherInput.value = "";
}

function renderGradingCriteria() {
  const criteria = gradingCriteriaSettings();
  LETTER_GRADE_ORDER.forEach((label) => {
    const entry = (criteria.letterScale || []).find((row) => row.label === label) || { start: null, end: null };
    const startInput = document.getElementById(`grading-scale-${label.toLowerCase()}-start`);
    const endInput = document.getElementById(`grading-scale-${label.toLowerCase()}-end`);
    if (startInput) startInput.value = entry.start == null ? "" : String(entry.start);
    if (endInput) endInput.value = entry.end == null ? "" : String(entry.end);
  });
  const gpaScaleSelect = document.getElementById("grading-gpa-scale");
  const gpaOtherInput = document.getElementById("grading-gpa-other");
  const editBtn = document.getElementById("grading-criteria-edit-btn");
  const saveBtn = document.getElementById("grading-criteria-submit-btn");
  const cancelBtn = document.getElementById("grading-criteria-cancel-btn");
  if (gpaScaleSelect) gpaScaleSelect.value = criteria.gpaScaleOption || "4";
  if (gpaOtherInput) gpaOtherInput.value = criteria.gpaScaleOption === "other" ? String(criteria.gpaMax || "") : "";
  document.querySelectorAll("#grading-criteria-form input, #grading-criteria-form select").forEach((element) => {
    if (!(element instanceof HTMLInputElement) && !(element instanceof HTMLSelectElement)) return;
    element.disabled = !gradingCriteriaEditMode;
  });
  if (editBtn) editBtn.classList.toggle("hidden", gradingCriteriaEditMode);
  if (saveBtn) saveBtn.classList.toggle("hidden", !gradingCriteriaEditMode);
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !gradingCriteriaEditMode);
  updateGradingCriteriaFormMode();
}

function readLetterScaleForm() {
  return LETTER_GRADE_ORDER.map((label) => {
    const startRaw = document.getElementById(`grading-scale-${label.toLowerCase()}-start`)?.value ?? "";
    const endRaw = document.getElementById(`grading-scale-${label.toLowerCase()}-end`)?.value ?? "";
    return {
      label,
      start: startRaw === "" ? null : Number(startRaw),
      end: endRaw === "" ? null : Number(endRaw)
    };
  });
}

function validateLetterScale(letterScale) {
  const hasAnyValues = letterScale.some((entry) => entry.start != null || entry.end != null);
  if (!hasAnyValues) {
    return {
      valid: true,
      scale: DEFAULT_LETTER_GRADE_SCALE.map(({ label }) => ({ label, start: null, end: null }))
    };
  }
  const hasMissingValues = letterScale.some((entry) => entry.start == null || entry.end == null);
  if (hasMissingValues) {
    return { valid: false, message: "If you customize the Letter Grading Scale, all A-F starting and ending scores must be filled in." };
  }
  for (const entry of letterScale) {
    if (!Number.isInteger(entry.start) || !Number.isInteger(entry.end) || entry.start < 0 || entry.end < 0 || entry.start > 100 || entry.end > 100) {
      return { valid: false, message: "Letter grade scores must be whole numbers between 0 and 100." };
    }
    if (entry.start > entry.end) {
      return { valid: false, message: `${entry.label} must have a starting score that is less than or equal to its ending score.` };
    }
  }
  if (letterScale[0].end !== 100 || letterScale[letterScale.length - 1].start !== 0) {
    return { valid: false, message: "Custom letter grade ranges must cover the full 0-100 scale with no gaps." };
  }
  for (let index = 0; index < letterScale.length - 1; index += 1) {
    const current = letterScale[index];
    const next = letterScale[index + 1];
    if (current.start !== (next.end + 1)) {
      return { valid: false, message: "Custom letter grade ranges cannot overlap or leave gaps between A, B, C, D, and F." };
    }
  }
  return {
    valid: true,
    scale: letterScale.map((entry) => ({ label: entry.label, start: entry.start, end: entry.end }))
  };
}

function beginGradeTypeEdit(gradeTypeId) {
  const gradeType = draftGradeTypes().find((gt) => gt.id === gradeTypeId);
  if (!gradeType) return;
  editingGradeTypeId = gradeType.id;
  const nameInput = document.getElementById("grade-type-name");
  const weightInput = document.getElementById("grade-type-weight");
  const iconSelect = document.getElementById("grade-type-icon");
  if (nameInput) nameInput.value = gradeType.name;
  if (weightInput) weightInput.value = gradeType.weight == null ? "" : String(gradeType.weight);
  if (iconSelect) iconSelect.value = normalizeGradeTypeIconKey(gradeType.iconKey, gradeType.name);
  renderGradeTypes();
}

function cancelGradeTypeEdit() {
  editingGradeTypeId = "";
  const form = document.getElementById("grade-type-form");
  if (form) form.reset();
  renderGradeTypeIconSelect();
  renderGradeTypes();
}

function renderStudentDetailOverview({ student, archived, selectedQuarter, studentEnrollments, missingRequiredSubjects, gradeSummary, attendanceSummary }) {
  const studentName = `${student.firstName || ""} ${student.lastName || ""}`.trim();
  const gradeLabel = student.grade ? `Grade ${student.grade}` : "Grade not set";
  const ageLabel = student.birthdate ? `Age ${calculateAge(student.birthdate)}` : "Age not set";
  const quarterLabel = selectedQuarter === "all" ? "All quarters" : selectedQuarter;
  const statusLabel = archived ? "Archived" : "Active";
  const averageDisplay = gradeSummary.overallAverage > 0 ? `${gradeSummary.overallAverage.toFixed(1)}%` : "No grades";
  const requiredDisplay = archived
    ? "N/A"
    : missingRequiredSubjects.length
      ? `${missingRequiredSubjects.length} gap${missingRequiredSubjects.length === 1 ? "" : "s"}`
      : "Complete";

  setTextById("student-detail-title", studentName || "Student");
  setTextById("student-detail-subtitle", `${gradeLabel} | ${ageLabel} | ${statusLabel} | ${quarterLabel}`);
  setTextById("student-detail-scheduled-count", studentEnrollments.length.toLocaleString());
  setTextById("student-detail-required-status", requiredDisplay);
  setTextById("student-detail-average", averageDisplay);
  setTextById("student-detail-absence-count", Number(attendanceSummary.absent || 0).toLocaleString());

  const avatar = document.getElementById("student-detail-avatar");
  if (avatar) {
    avatar.textContent = (student.firstName || student.lastName || "S").charAt(0).toUpperCase();
    avatar.classList.toggle("archived", archived);
  }
  const requiredMetric = document.getElementById("student-detail-required-metric");
  if (requiredMetric) {
    requiredMetric.classList.toggle("attention", !archived && missingRequiredSubjects.length > 0);
    requiredMetric.classList.toggle("neutral", archived);
  }
}

function renderStudentDetail() {
  const panel = document.getElementById("student-detail-panel");
  if (!panel) return;

  const student = state.students.find((s) => s.id === selectedStudentId);
  if (!student) {
    selectedStudentId = "";
    resetStudentEnrollmentDraft();
    setStudentViewMode("list");
    renderStudentViewMode();
    return;
  }

  const archived = studentIsArchived(student);
  renderStudentDetailSectionVisibility();
  const summaryFirst = document.getElementById("student-summary-first");
  const summaryLast = document.getElementById("student-summary-last");
  const summaryBirthdate = document.getElementById("student-summary-birthdate");
  const summaryGrade = document.getElementById("student-summary-grade");
  const summaryDeleteBtn = document.getElementById("student-summary-delete-btn");
  const summaryRestoreBtn = document.getElementById("student-summary-restore-btn");
  if (summaryFirst) summaryFirst.value = student.firstName || "";
  if (summaryLast) summaryLast.value = student.lastName || "";
  if (summaryBirthdate) summaryBirthdate.value = normalizeApiDate(student.birthdate);
  if (summaryGrade) summaryGrade.value = student.grade || "";
  if (summaryDeleteBtn) {
    summaryDeleteBtn.textContent = archived ? "Student Archived" : "Delete Student";
    summaryDeleteBtn.disabled = archived;
    summaryDeleteBtn.classList.toggle("hidden", archived);
  }
  if (summaryRestoreBtn) {
    summaryRestoreBtn.classList.toggle("hidden", !archived);
  }
  const applyBtn = document.getElementById("student-detail-apply-btn");
  if (applyBtn) {
    applyBtn.textContent = "Save Schedule Changes";
    applyBtn.classList.toggle("hidden", !studentEnrollmentEditMode);
  }
  const cancelScheduleEditBtn = document.getElementById("student-detail-cancel-schedule-edit-btn");
  if (cancelScheduleEditBtn) {
    cancelScheduleEditBtn.classList.toggle("hidden", !studentEnrollmentEditMode);
  }

  const quarterSelect = document.getElementById("student-detail-quarter-filter");
  const selectedQuarter = quarterSelect ? quarterSelect.value || "all" : "all";
  const quarterRange = state.settings.quarters.find((q) => q.name === selectedQuarter);
  const schoolYear = currentSchoolYear();
  const rangeStart = quarterRange ? quarterRange.startDate : state.settings.schoolYear.startDate;
  const rangeEnd = quarterRange ? quarterRange.endDate : state.settings.schoolYear.endDate;
  const gradeSummary = studentGradeSummary(student.id, { quarterName: selectedQuarter });

  const studentEnrollments = sortedStudentScheduledEntries(student.id, workingStudentEnrollments(student.id));
  const enrolledSubjectIds = new Set(
    studentEnrollments
      .map((entry) => getCourse(entryCourseId(entry))?.subjectId || "")
      .filter(Boolean)
  );
  const missingRequiredSubjects = archived ? [] : state.subjects
    .filter((subject) => subject.required && !enrolledSubjectIds.has(subject.id))
    .sort((a, b) => a.name.localeCompare(b.name));
  if (studentEnrollmentSubjectFocusId && !missingRequiredSubjects.some((subject) => subject.id === studentEnrollmentSubjectFocusId)) {
    studentEnrollmentSubjectFocusId = "";
  }
  const summary = studentAttendanceSummaryByRange(student.id, rangeStart, rangeEnd);
  renderStudentDetailOverview({
    student,
    archived,
    selectedQuarter,
    studentEnrollments,
    missingRequiredSubjects,
    gradeSummary,
    attendanceSummary: summary
  });
  renderStudentDetailRequiredCallout(student, missingRequiredSubjects);
  renderStudentEnrollmentCourseChecklist(getSelectedStudentEnrollmentCourseIds(), student.id);
  const enrollmentRows = studentEnrollments
    .map((e) => {
      const isScheduleBlock = e.itemType === "scheduleBlock";
      const isCourseSection = e.itemType === "courseSection";
      const course = isScheduleBlock ? null : getCourse(entryCourseId(e));
      const subject = studentScheduledEntrySubjectLabel(e);
      const courseAvg = isScheduleBlock ? 0 : gradeSummary.courseAverage(entryCourseId(e));
      const avgDisplay = isScheduleBlock ? "-" : (courseAvg === 0 ? "No grades" : `${courseAvg.toFixed(1)}%`);
      const orderOptions = [`<option value="">Auto</option>`]
        .concat(studentEnrollments.map((_, index) => {
          const value = index + 1;
          const selected = parseScheduleOrderValue(e.scheduleOrder) === value ? " selected" : "";
          return `<option value="${value}"${selected}>${value}</option>`;
        }))
        .join("");
      const entryType = isScheduleBlock ? "scheduleBlock" : (e.itemType === "courseSection" ? "courseSection" : "course");
      const orderControl = isCourseSection
        ? `<span class="muted">Managed by class time</span>`
        : isAdminUser()
        ? `<select class="student-schedule-order-select" data-enrollment-order-id="${e.id}" data-enrollment-item-type="${entryType}" aria-label="Schedule order for ${escapeHtml(studentScheduledEntryDisplayName(e))}"${studentEnrollmentEditMode ? "" : " disabled"}>${orderOptions}</select>`
        : (parseScheduleOrderValue(e.scheduleOrder) != null ? String(parseScheduleOrderValue(e.scheduleOrder)) : "Auto");
      const actions = studentEnrollmentEditMode
        ? `<div class="table-action-row"><button data-edit-student-enrollment='${e.id}' data-enrollment-item-type='${entryType}' type='button' disabled>Editing Schedule</button><button data-remove-student-enrollment='${e.id}' data-enrollment-item-type='${entryType}' type='button'>Remove</button></div>`
        : `<div class="table-action-row"><button data-edit-student-enrollment='${e.id}' data-enrollment-item-type='${entryType}' type='button'>Edit Schedule</button></div>`;
      const requiredCell = course?.subjectId ? requiredSubjectBadge(course.subjectId) : "<span class=\"muted\">-</span>";
      return `<tr><td>${renderScheduleSourceCell(studentScheduledEntryDisplayName(e), studentScheduledEntrySchoolDayMeta(e))}</td><td>${escapeHtml(subject)}</td><td>${requiredCell}</td><td>${orderControl}</td><td>${avgDisplay}</td><td>${actions}</td></tr>`;
    });
  missingRequiredSubjects.forEach((subject) => {
    enrollmentRows.push(`<tr class="student-required-subject-missing"><td>${escapeHtml(subject.name)}</td><td>Missing required subject</td><td>${requiredSubjectBadge(subject.id)}</td><td>-</td><td>-</td><td><div class="table-action-row"><button type="button" class="student-detail-required-action-btn" data-student-required-subject-focus="${escapeHtml(subject.id)}">Find Item</button></div></td></tr>`);
  });
  if (enrollmentRows.length) {
    const overallAverage = gradeSummary.overallAverage;
    const averageDisplay = overallAverage > 0 ? `${overallAverage.toFixed(1)}%` : "No grades";
    enrollmentRows.push(`<tr><td colspan="4"><strong>Average</strong></td><td><strong>${averageDisplay}</strong></td><td></td></tr>`);
  }
  rowOrEmpty(document.getElementById("student-enrollment-table"), enrollmentRows, "No scheduled items for this student.", 6);

  const requiredDaysDisplay = schoolYear.requiredInstructionalDays == null ? "-" : String(schoolYear.requiredInstructionalDays);
  const attendanceRows = [
    `<tr><td>${student.firstName} ${student.lastName}</td><td>${requiredDaysDisplay}</td><td>${summary.attended}</td><td>${summary.absent}</td></tr>`
  ];
  rowOrEmpty(document.getElementById("student-attendance-summary-table"), attendanceRows, "No students available.", 4);

  const instructionalHoursSnapshot = buildInstructionalHoursSnapshot([student.id]);
  const selectedBucketKey = selectedQuarter === "all" ? "total" : selectedQuarter.toLowerCase();
  const bucketSummary = instructionalHoursSnapshot.summaryByStudent.get(student.id)?.buckets?.[selectedBucketKey] || { earned: 0, projected: 0 };
  const completionPct = bucketSummary.projected > 0
    ? ((bucketSummary.earned / bucketSummary.projected) * 100).toFixed(1)
    : "0.0";
  const requiredHoursDisplay = schoolYear.requiredInstructionalHours == null ? "-" : Number(schoolYear.requiredInstructionalHours).toFixed(1);
  const instructionalHoursRows = [
    `<tr${selectedQuarter === "all" && schoolYear.requiredInstructionalHours != null && bucketSummary.projected < schoolYear.requiredInstructionalHours ? " class='warning-row'" : ""}><td>${student.firstName} ${student.lastName}</td><td>${requiredHoursDisplay}</td><td>${bucketSummary.earned.toFixed(1)}</td><td>${bucketSummary.projected.toFixed(1)}</td><td>${completionPct}%</td></tr>`
  ];
  rowOrEmpty(
    document.getElementById("student-instructional-hours-summary-table"),
    instructionalHoursRows,
    "No instructional hours available.",
    5
  );
  const hoursWarningId = "student-instructional-hours-warning";
  const detailPanel = document.getElementById("student-detail-panel");
  let warningEl = document.getElementById(hoursWarningId);
  if (!warningEl && detailPanel) {
    warningEl = document.createElement("p");
    warningEl.id = hoursWarningId;
    warningEl.className = "warning-text hidden";
    const hoursTable = document.getElementById("student-instructional-hours-summary-table");
    hoursTable?.closest(".table-wrap")?.insertAdjacentElement("afterend", warningEl);
  }
  if (warningEl) {
    const requiredHours = schoolYear.requiredInstructionalHours;
    const showWarning = selectedQuarter === "all" && requiredHours != null && bucketSummary.projected < requiredHours;
    warningEl.textContent = showWarning
      ? `Warning: Projected instructional hours (${bucketSummary.projected.toFixed(1)}) are below the required instructional hours (${Number(requiredHours).toFixed(1)}).`
      : "";
    warningEl.classList.toggle("hidden", !showWarning);
  }
}

function renderHolidays() {
  const tableBody = document.getElementById("holiday-table");
  if (!tableBody) return;
  const rows = [...state.settings.holidays].sort((a,b)=>a.startDate.localeCompare(b.startDate));
  const htmlRows = rows
    .map((h) => `<tr><td>${h.name}</td><td>${h.type}</td><td>${formatDisplayDate(h.startDate)}</td><td>${formatDisplayDate(h.endDate)}</td><td class="schedule-actions-cell"><div class="table-action-row"><button data-edit-holiday='${h.id}' type='button'>Edit</button><button data-remove-holiday='${h.id}' type='button'>Remove</button></div></td></tr>`);
  rowOrEmpty(tableBody, htmlRows, "No holidays/breaks defined.", 5);
  const submitBtn = document.getElementById("holiday-submit-btn");
  const cancelBtn = document.getElementById("holiday-cancel-edit-btn");
  if (submitBtn) submitBtn.textContent = editingHolidayId ? "Update" : "Add";
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !editingHolidayId);
}

function renderDailyBreaks() {
  const tableBody = document.getElementById("daily-break-table");
  if (!tableBody) return;
  const allDailyBreaks = [...(state.settings.dailyBreaks || [])];
  const visibleDailyBreaks = allDailyBreaks.filter((entry) =>
    !entry.schoolYearId || entry.schoolYearId === state.settings.currentSchoolYearId);
  const rows = (visibleDailyBreaks.length ? visibleDailyBreaks : allDailyBreaks)
    .sort((a, b) => a.startTime.localeCompare(b.startTime) || dailyBreakLabel(a).localeCompare(dailyBreakLabel(b)))
    .map((entry) => {
      const students = entry.studentIds.map((studentId) => getStudentName(studentId)).join(", ");
      const weekdays = (entry.weekdays || []).map((day) => DAY_NAMES[day]).join(", ");
      const description = entry.type === "other" ? escapeHtml(entry.description || "") : "";
      return `<tr><td>${students}</td><td>${dailyBreakLabel(entry)}</td><td>${description || "-"}</td><td>${formatClockTime(entry.startTime)}</td><td>${Number(entry.durationMinutes || 0)} min</td><td>${weekdays}</td><td class="schedule-actions-cell"><div class="table-action-row"><button data-edit-daily-break='${entry.id}' type='button'>Edit</button><button data-remove-daily-break='${entry.id}' type='button'>Remove</button></div></td></tr>`;
    });
  rowOrEmpty(tableBody, rows, "No daily lunch or break schedules defined.", 7);
  const submitBtn = document.getElementById("daily-break-submit-btn");
  const cancelBtn = document.getElementById("daily-break-cancel-edit-btn");
  if (submitBtn) submitBtn.textContent = editingDailyBreakId ? "Update Break" : "Add Break";
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !editingDailyBreakId);
  updateDailyBreakFormMode();
}

function updateScheduleBlockFormMode() {
  const typeSelect = document.getElementById("schedule-block-type");
  const descriptionWrap = document.getElementById("schedule-block-description-wrap");
  const descriptionInput = document.getElementById("schedule-block-description");
  if (!typeSelect || !descriptionWrap || !descriptionInput) return;
  const isOther = typeSelect.value === "other_break";
  descriptionWrap.classList.toggle("hidden", !isOther);
  descriptionInput.required = isOther;
  if (!isOther) descriptionInput.value = "";
}

function resetScheduleBlockForm() {
  editingScheduleBlockId = "";
  const form = document.getElementById("schedule-block-form");
  if (form) form.reset();
  const durationInput = document.getElementById("schedule-block-duration");
  if (durationInput) durationInput.value = "60";
  document.querySelectorAll("input[name='schedule-block-weekday']").forEach((checkbox) => {
    checkbox.checked = true;
  });
  updateScheduleBlockFormMode();
}

function beginScheduleBlockEdit(scheduleBlockId) {
  const entry = state.scheduleBlocks.find((block) => block.id === scheduleBlockId);
  if (!entry) return;
  editingScheduleBlockId = entry.id;
  document.getElementById("schedule-block-name").value = entry.name || "";
  document.getElementById("schedule-block-type").value = entry.type || "lunch";
  document.getElementById("schedule-block-description").value = entry.description || "";
  document.getElementById("schedule-block-duration").value = String(Number(entry.durationMinutes || 60));
  document.querySelectorAll("input[name='schedule-block-weekday']").forEach((checkbox) => {
    checkbox.checked = Array.isArray(entry.weekdays) && entry.weekdays.includes(Number(checkbox.value));
  });
  updateScheduleBlockFormMode();
  renderScheduleBlocks();
}

function renderScheduleBlocks() {
  const tableBody = document.getElementById("schedule-block-table");
  if (!tableBody) return;
  const rows = [...(state.scheduleBlocks || [])]
    .filter((entry) => scheduleBlockReadinessFilter !== "unassigned" || scheduleBlockNeedsAssignmentReview(entry))
    .sort((a, b) => scheduleBlockLabel(a).localeCompare(scheduleBlockLabel(b)))
    .map((entry) => {
      const weekdays = (entry.weekdays || []).map((day) => DAY_NAMES[day]).join(", ");
      const typeLabel = SCHEDULE_BLOCK_TYPE_LABELS[entry.type] || "Schedule Block";
      const enrolledCount = scheduleBlockAssignedStudentIdsForReadiness(entry.id).size;
      const needsReview = scheduleBlockNeedsAssignmentReview(entry);
      const enrolledCell = `<span class="enrollment-count-pill${needsReview ? " empty" : ""}">${enrolledCount}</span>${needsReview ? `<span class="enrollment-count-note">No students assigned</span>` : ""}`;
      return `<tr class="${needsReview ? "readiness-review-row" : ""}"><td>${renderScheduleSourceCell(scheduleBlockLabel(entry), scheduleBlockSchoolDayMeta(entry))}</td><td>${escapeHtml(typeLabel)}</td><td>${escapeHtml(entry.description || "-")}</td><td>${Number(entry.durationMinutes || 0)} min</td><td>${escapeHtml(weekdays || "Mon-Fri")}</td><td>${enrolledCell}</td><td class="schedule-actions-cell"><div class="table-action-row"><button data-edit-schedule-block="${entry.id}" type="button">Edit</button><button data-remove-schedule-block="${entry.id}" type="button">Remove</button></div></td></tr>`;
    });
  rowOrEmpty(tableBody, rows, scheduleBlockReadinessFilter === "unassigned" ? "No schedule blocks need assignment review." : "No ordered schedule blocks defined.", 7);
  renderScheduleBlockReadinessFilterPanel(rows.length);
  renderSchoolDayReadinessPanels();
  const submitBtn = document.getElementById("schedule-block-submit-btn");
  const cancelBtn = document.getElementById("schedule-block-cancel-edit-btn");
  if (submitBtn) submitBtn.textContent = editingScheduleBlockId ? "Update Block" : "Add Block";
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !editingScheduleBlockId);
  updateScheduleBlockFormMode();
}

function selectedQuarterSchoolYearId() {
  const select = document.getElementById("quarter-school-year");
  const selected = select instanceof HTMLSelectElement ? select.value : "";
  return selected || state.settings.currentSchoolYearId || currentSchoolYear()?.id || "";
}

function setQuarterFormValues(quarters = []) {
  ["q1", "q2", "q3", "q4"].forEach((prefix, index) => {
    const quarter = quarters[index] || {};
    const startInput = document.getElementById(`${prefix}-start`);
    const endInput = document.getElementById(`${prefix}-end`);
    if (startInput) startInput.value = quarter.startDate || "";
    if (endInput) endInput.value = quarter.endDate || "";
  });
}

function renderQuarterRecommendationPanel() {
  const card = document.getElementById("quarter-recommendation-card");
  if (!card) return;
  const schoolYearId = selectedQuarterSchoolYearId();
  const schoolYear = getSchoolYear(schoolYearId);
  const summary = document.getElementById("quarter-recommendation-summary");
  const grid = document.getElementById("quarter-recommendation-grid");
  const note = document.getElementById("quarter-recommendation-note");
  const useButton = document.getElementById("quarter-use-recommendation-btn");
  const saveButton = document.getElementById("quarter-save-recommendation-btn");
  if (!schoolYear) {
    if (summary) summary.textContent = "Select a school year to calculate recommended quarters.";
    if (grid) grid.innerHTML = "";
    if (note) note.textContent = "";
    if (useButton) useButton.disabled = true;
    if (saveButton) saveButton.disabled = true;
    return;
  }
  const recommendation = recommendedQuartersForSchoolYear(schoolYear);
  const canRecommend = !recommendation.error && recommendation.quarters.length === 4;
  if (summary) {
    summary.textContent = canRecommend
      ? `${recommendation.totalInstructionalDays} instructional days balanced as ${recommendation.counts.join(" / ")}.`
      : recommendation.error;
  }
  if (grid) {
    grid.innerHTML = canRecommend
      ? recommendation.quarters.map((quarter) => {
        const days = instructionalDaysCountForRange(quarter.startDate, quarter.endDate);
        return `<div class="quarter-recommendation-item">
          <strong>${escapeHtml(quarter.name)}</strong>
          <span>${escapeHtml(formatDisplayDate(quarter.startDate))} - ${escapeHtml(formatDisplayDate(quarter.endDate))}</span>
          <em>${days} school day${days === 1 ? "" : "s"}</em>
        </div>`;
      }).join("")
      : "";
  }
  const existing = sortedQuartersForSchoolYear(schoolYear.id);
  const matches = canRecommend && quartersMatchRecommended(schoolYear.id, schoolYear);
  if (note) {
    note.textContent = matches
      ? "Saved quarters already match the current recommendation."
      : existing.length
        ? "Saving recommended quarters will replace the saved quarter dates for this school year."
        : "No quarters are saved yet for this school year.";
    note.className = "muted";
  }
  if (useButton) useButton.disabled = !canRecommend;
  if (saveButton) saveButton.disabled = !canRecommend || matches;
}

function renderPlanningSettings() {
  const schoolYear = currentSchoolYear();
  const schoolYearCurrent = document.getElementById("school-year-current");
  if (schoolYearCurrent) {
    const daysText = schoolYear.requiredInstructionalDays == null ? "not set" : String(schoolYear.requiredInstructionalDays);
    const hoursText = schoolYear.requiredInstructionalHours == null ? "not set" : Number(schoolYear.requiredInstructionalHours).toFixed(1);
    schoolYearCurrent.textContent = `Current School Year: ${schoolYear.label} (${formatDisplayDate(schoolYear.startDate)} to ${formatDisplayDate(schoolYear.endDate)}) | Required Days: ${daysText} | Required Hours: ${hoursText}`;
  }

  const schoolYearRows = state.settings.schoolYears
    .slice()
    .sort((a, b) => toDate(a.startDate) - toDate(b.startDate))
    .map((year) => {
      const instructionalDays = instructionalDaysCountForRange(year.startDate, year.endDate);
      const requiredDays = year.requiredInstructionalDays == null ? "-" : String(year.requiredInstructionalDays);
      const requiredHours = year.requiredInstructionalHours == null ? "-" : Number(year.requiredInstructionalHours).toFixed(1);
      const belowDaysRequirement = year.requiredInstructionalDays != null && instructionalDays < year.requiredInstructionalDays;
      const status = belowDaysRequirement
        ? `<span class="warning-text">Below required days by ${year.requiredInstructionalDays - instructionalDays}</span>`
        : "OK";
      const isCurrentYear = year.id === state.settings.currentSchoolYearId;
      const actionButtons = [
        isCurrentYear ? "" : `<button type="button" data-set-current-school-year="${year.id}">Set Current</button>`,
        `<button type="button" data-edit-school-year="${year.id}">Edit</button>`,
        `<button type="button" data-remove-school-year="${year.id}">Delete</button>`
      ].filter(Boolean).join("");
      return `<tr${belowDaysRequirement ? " class='warning-row'" : ""}><td>${year.label}${isCurrentYear ? " (Current)" : ""}</td><td>${formatDisplayDate(year.startDate)}</td><td>${formatDisplayDate(year.endDate)}</td><td>${requiredDays}</td><td>${requiredHours}</td><td>${instructionalDays}</td><td>${status}</td><td class="schedule-actions-cell"><div class="table-action-row">${actionButtons}</div></td></tr>`;
    });
  rowOrEmpty(document.getElementById("school-year-summary-table"), schoolYearRows, "No school years saved yet.", 8);

  const quarterRows = state.settings.schoolYears
    .slice()
    .sort((a, b) => toDate(a.startDate) - toDate(b.startDate))
    .flatMap((year) => {
      const yearQuarters = state.settings.allQuarters
        .filter((quarter) => quarter.schoolYearId === year.id)
        .sort((a, b) => toDate(a.startDate) - toDate(b.startDate));
      const rows = yearQuarters.map((quarter) => {
        const instructionalDays = instructionalDaysCountForRange(quarter.startDate, quarter.endDate);
        return `<tr><td>${year.label}</td><td>${quarter.name}</td><td>${formatDisplayDate(quarter.startDate)}</td><td>${formatDisplayDate(quarter.endDate)}</td><td>${instructionalDays}</td><td class="schedule-actions-cell"><div class="table-action-row"><button type="button" data-edit-quarters-year="${quarter.schoolYearId}">Edit</button></div></td></tr>`;
      });
      if (rows.length) {
        const totalInstructionalDays = yearQuarters.reduce((sum, quarter) =>
          sum + instructionalDaysCountForRange(quarter.startDate, quarter.endDate), 0);
        rows.push(`<tr><td colspan="3"></td><td class="quarter-summary-total-label"><strong>${year.label} Total</strong></td><td class="quarter-summary-total-value"><strong>${totalInstructionalDays}</strong></td><td></td></tr>`);
      }
      return rows;
    });
  rowOrEmpty(document.getElementById("quarter-summary-table"), quarterRows, "No quarters saved yet.", 6);
  const quarterWarningEl = document.getElementById("quarter-summary-warning");
  if (quarterWarningEl) {
    const mismatches = state.settings.schoolYears
      .filter((year) => year.requiredInstructionalDays != null)
      .map((year) => {
        const quarterInstructionalDays = state.settings.allQuarters
          .filter((quarter) => quarter.schoolYearId === year.id)
          .reduce((sum, quarter) => sum + instructionalDaysCountForRange(quarter.startDate, quarter.endDate), 0);
        return {
          year,
          quarterInstructionalDays,
          difference: quarterInstructionalDays - Number(year.requiredInstructionalDays)
        };
      })
      .filter((entry) => entry.difference < 0);
    if (mismatches.length) {
      quarterWarningEl.className = "warning-text";
      quarterWarningEl.textContent = mismatches
        .map((entry) => `${entry.year.label}: defined quarters total ${entry.quarterInstructionalDays} instructional days, which is below Required Instructional Days of ${entry.year.requiredInstructionalDays}.`)
        .join(" ");
    } else {
      quarterWarningEl.className = "muted hidden";
      quarterWarningEl.textContent = "";
    }
  }

  const schoolYearSubmitBtn = document.getElementById("school-year-submit-btn");
  const schoolYearCancelBtn = document.getElementById("school-year-cancel-edit-btn");
  if (schoolYearSubmitBtn) schoolYearSubmitBtn.textContent = editingSchoolYearId ? "Update School Year" : "Save School Year";
  if (schoolYearCancelBtn) schoolYearCancelBtn.classList.toggle("hidden", !editingSchoolYearId);

  const quartersSubmitBtn = document.getElementById("quarters-submit-btn");
  const quartersCancelBtn = document.getElementById("quarters-cancel-edit-btn");
  if (quartersSubmitBtn) quartersSubmitBtn.textContent = editingQuarterSchoolYearId ? "Update Quarters" : "Save Quarters";
  if (quartersCancelBtn) quartersCancelBtn.classList.toggle("hidden", !editingQuarterSchoolYearId);

  renderQuarterRecommendationPanel();
  renderSchoolDaySettings();
}

function renderSchoolDaySettings() {
  const schoolYearSelect = document.getElementById("school-day-school-year");
  if (!schoolYearSelect) return;
  const selectedSchoolYearId = schoolYearSelect.value && state.settings.schoolYears.some((year) => year.id === schoolYearSelect.value)
    ? schoolYearSelect.value
    : state.settings.currentSchoolYearId;
  options("school-day-school-year", state.settings.schoolYears, (year) => year.label);
  schoolYearSelect.value = selectedSchoolYearId;
  fillSchoolDaySettingsForm(selectedSchoolYearId);
}

function fillSchoolDaySettingsForm(schoolYearId = "") {
  const schoolYear = getSchoolYear(schoolYearId) || currentSchoolYear();
  if (!schoolYear) return;
  const schoolYearSelect = document.getElementById("school-day-school-year");
  const startTimeInput = document.getElementById("school-day-start-time");
  const gapInput = document.getElementById("school-day-gap-minutes");
  const currentSummary = document.getElementById("school-day-settings-current");
  if (schoolYearSelect) schoolYearSelect.value = schoolYear.id;
  if (startTimeInput) startTimeInput.value = normalizeSchoolDayStartTime(schoolYear.schoolDayStartTime);
  if (gapInput) gapInput.value = String(normalizeMinutesBetweenClasses(schoolYear.minutesBetweenClasses));
  if (currentSummary) {
    currentSummary.textContent = `${schoolYear.label}: School day starts at ${formatClockTime(schoolYear.schoolDayStartTime || DEFAULT_SCHOOL_DAY_START_TIME)} with ${normalizeMinutesBetweenClasses(schoolYear.minutesBetweenClasses)} minute${normalizeMinutesBetweenClasses(schoolYear.minutesBetweenClasses) === 1 ? "" : "s"} between classes.`;
  }
}

function confirmEarlyClassStart(startTime) {
  const schoolYear = currentSchoolYear();
  const classStartMinutes = parseTimeToMinutes(startTime);
  const schoolDayStartMinutes = parseTimeToMinutes(schoolYear?.schoolDayStartTime || DEFAULT_SCHOOL_DAY_START_TIME);
  if (!Number.isFinite(classStartMinutes) || !Number.isFinite(schoolDayStartMinutes) || classStartMinutes >= schoolDayStartMinutes) {
    return true;
  }
  return window.confirm(
    `This class is scheduled to start at ${formatClockTime(classStartMinutes)}, which is before the ${schoolYear?.label || "current"} School Day start time of ${formatClockTime(schoolDayStartMinutes)}. Do you want to save it anyway?`
  );
}

function renderPlans() {
  const tableBody = document.getElementById("plan-table");
  if (!tableBody) return;
  const viewerStudentId = currentStudentId();
  const typeFilter = document.getElementById("plan-filter-type")?.value || "all";
  const studentFilter = viewerStudentId || document.getElementById("plan-filter-student")?.value || "all";

  const rows = [...state.plans]
    .filter((plan) => {
      if (typeFilter !== "all" && plan.planType !== typeFilter) return false;
      if (studentFilter !== "all" && plan.studentId !== studentFilter) return false;
      return true;
    })
    .sort((a,b)=>a.startDate.localeCompare(b.startDate));
  const htmlRows = rows.map((p) => {
    const periodLabel = p.planType === "quarterly" && p.quarterName ? ` (${p.quarterName})` : "";
    const weekdays = (Array.isArray(p.weekdays) ? p.weekdays : []).map((w) => DAY_NAMES[w]).join(", ");
    const range = resolvedPlanRange(p);
    const actions = isAdminUser() ? `<button data-edit-plan='${p.id}' type='button'>Edit</button> <button data-remove-plan='${p.id}' type='button'>Remove</button>` : "View only";
    return `<tr><td>${p.planType.toUpperCase()}${periodLabel}</td><td>${getStudentName(p.studentId)}</td><td>${getCourseName(p.courseId)}</td><td>${formatDisplayDate(range.startDate)} to ${formatDisplayDate(range.endDate)}</td><td>${weekdays}</td><td class="schedule-actions-cell">${typeof actions === "string" && actions.includes("<button") ? `<div class="table-action-row">${actions}</div>` : actions}</td></tr>`;
  });
  rowOrEmpty(tableBody, htmlRows, "No instruction plans defined.", 6);
  const submitBtn = document.getElementById("plan-submit-btn");
  const cancelBtn = document.getElementById("plan-cancel-edit-btn");
  if (submitBtn) submitBtn.textContent = editingPlanId ? "Update Plan" : "Add Plan";
  if (cancelBtn) cancelBtn.classList.toggle("hidden", !editingPlanId);
}

function paginateSearchResults(records, requestedPage, pageSize = SEARCH_RESULTS_PAGE_SIZE) {
  const total = records.length;
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  const page = Math.min(Math.max(1, Number(requestedPage) || 1), pageCount);
  const startIndex = (page - 1) * pageSize;
  const endIndex = Math.min(startIndex + pageSize, total);
  return {
    page,
    pageCount,
    total,
    startIndex,
    endIndex,
    records: records.slice(startIndex, endIndex)
  };
}

function renderSearchPaginationRow(target, pageInfo, colspan) {
  if (!pageInfo || pageInfo.pageCount <= 1) return "";
  const from = pageInfo.total ? pageInfo.startIndex + 1 : 0;
  const to = pageInfo.endIndex;
  return `<tr class="search-pagination-row"><td colspan="${colspan}">
    <div class="search-pagination-controls">
      <button type="button" data-search-page-target="${target}" data-search-page="${pageInfo.page - 1}"${pageInfo.page <= 1 ? " disabled" : ""}>Previous</button>
      <span>Records ${from.toLocaleString()}-${to.toLocaleString()} of ${pageInfo.total.toLocaleString()} | Page ${pageInfo.page.toLocaleString()} of ${pageInfo.pageCount.toLocaleString()}</span>
      <button type="button" data-search-page-target="${target}" data-search-page="${pageInfo.page + 1}"${pageInfo.page >= pageInfo.pageCount ? " disabled" : ""}>Next</button>
    </div>
  </td></tr>`;
}

function renderAttendance() {
  const viewerStudentId = currentStudentId();
  const useSearchFilters = currentAttendanceTab === "search";
  const studentFilter = viewerStudentId || (useSearchFilters ? document.getElementById("attendance-filter-student")?.value : "all") || "all";
  const startDateFilter = useSearchFilters ? document.getElementById("attendance-filter-start-date")?.value || "" : "";
  const endDateFilter = useSearchFilters ? document.getElementById("attendance-filter-end-date")?.value || "" : "";
  const quarterFilter = useSearchFilters ? document.getElementById("attendance-filter-quarter")?.value || "all" : "all";
  const statusFilter = useSearchFilters ? document.getElementById("attendance-filter-status")?.value || "all" : "all";
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);

  const filtered = state.attendance.filter((a) => {
    if (studentFilter !== "all" && a.studentId !== studentFilter) return false;
    if (startDateFilter && a.date < startDateFilter) return false;
    if (endDateFilter && a.date > endDateFilter) return false;
    if (!startDateFilter && !endDateFilter && !recordDateInActiveYear(a)) return false;
    if (quarterFilter !== "all" && quarterRange && !inRange(a.date, quarterRange.startDate, quarterRange.endDate)) return false;
    if (statusFilter === "present" && !a.present) return false;
    if (statusFilter === "absent" && a.present) return false;
    return true;
  });

  const sortedAttendance = [...filtered]
    .sort((a,b)=>b.date.localeCompare(a.date));
  const attendancePageInfo = useSearchFilters ? paginateSearchResults(sortedAttendance, attendanceSearchPage) : null;
  if (attendancePageInfo) attendanceSearchPage = attendancePageInfo.page;
  const visibleAttendance = attendancePageInfo ? attendancePageInfo.records : sortedAttendance.slice(0,100);
  const rows = visibleAttendance.flatMap((a) => {
      const actions = isAdminUser()
        ? `<button type='button' data-edit-attendance='${a.id}'>Edit</button> <button type='button' data-remove-attendance='${a.id}'>Remove</button>`
        : "View only";
      const attendanceStatus = a.present
        ? "<span class=\"attendance-status-pill present\">Present</span>"
        : "<span class=\"attendance-status-pill absent\">Absent</span>";
      const recordRow = `<tr><td>${formatDisplayDate(a.date)}</td><td>${getStudentName(a.studentId)}</td><td>${attendanceStatus}</td><td>${typeof actions === "string" && actions.includes("<button") ? `<div class="table-action-row">${actions}</div>` : actions}</td></tr>`;
      if (!useSearchFilters || editingSearchAttendanceId !== a.id) return [recordRow];
      const studentOptions = visibleStudents()
        .map((student) => `<option value="${student.id}"${student.id === a.studentId ? " selected" : ""}>${escapeHtml(student.firstName)} ${escapeHtml(student.lastName)}</option>`)
        .join("");
      const editRow = `<tr class="search-inline-edit-row attendance-search-edit-row">
        <td><label>Date<input data-search-attendance-date="${a.id}" type="date" value="${escapeHtml(a.date)}"></label></td>
        <td><label>Student<select data-search-attendance-student="${a.id}">${studentOptions}</select></label></td>
        <td><label>Status<select data-search-attendance-status="${a.id}"><option value="present"${a.present ? " selected" : ""}>Present</option><option value="absent"${!a.present ? " selected" : ""}>Absent</option></select></label></td>
        <td><div class="table-action-row"><button type="button" data-save-search-attendance="${a.id}">Save</button><button type="button" data-cancel-search-attendance="${a.id}">Cancel</button></div></td>
      </tr>`;
      return [recordRow, editRow];
    });
  const paginationRow = renderSearchPaginationRow("attendance", attendancePageInfo, 4);
  if (paginationRow && rows.length) rows.push(paginationRow);
  rowOrEmpty(document.getElementById("attendance-table"), rows, "No attendance recorded yet.", 4);
}

function createLegacyLocalScheduleBlock(payload) {
  state.scheduleBlocks.push({ id: payload.id || uid(), ...payload });
}

function updateLegacyLocalScheduleBlock(existing, payload) {
  if (!existing) return;
  existing.name = payload.name;
  existing.type = payload.type;
  existing.description = payload.description || "";
  existing.durationMinutes = payload.durationMinutes;
  existing.weekdays = [...payload.weekdays];
}

function deleteLegacyLocalScheduleBlock(scheduleBlockId) {
  state.scheduleBlocks = state.scheduleBlocks.filter((entry) => entry.id !== scheduleBlockId);
  state.studentScheduleBlocks = state.studentScheduleBlocks.filter((entry) => entry.scheduleBlockId !== scheduleBlockId);
}

function attendanceRecordForStudentDate(studentId, date) {
  return state.attendance.find((record) => record.studentId === studentId && record.date === date) || null;
}

function gradeRecordsForStudentCourseDate(studentId, courseId, date) {
  return state.tests.filter((record) =>
    record.studentId === studentId
    && record.courseId === courseId
    && record.date === date);
}

function schoolDayRosterStudents(referenceISO) {
  const selectedStudentIds = getSchoolDaySelectedStudentIds();
  if (selectedStudentIds.length) {
    return visibleStudents().filter((student) => selectedStudentIds.includes(student.id));
  }
  const subjectFilterIds = getSchoolDaySelectedSubjectIds();
  const courseFilterIds = getSchoolDaySelectedCourseIds();
  const scheduledStudentIds = new Set(
    Array.from(dailyScheduledBlocks(referenceISO, [], subjectFilterIds, courseFilterIds).values())
      .flat()
      .map((block) => block.studentId)
      .filter(Boolean)
  );
  if (scheduledStudentIds.size) {
    return visibleStudents().filter((student) => scheduledStudentIds.has(student.id));
  }
  return visibleStudents();
}

function renderSchoolDayStudentSummaries(referenceISO, studentFilterIds = [], subjectFilterIds = [], courseFilterIds = [], scheduledItemKeys = []) {
  const host = document.getElementById("school-day-student-summaries");
  const toggle = document.getElementById("school-day-student-summaries-toggle");
  if (!host) return;
  if (!workspaceConfig.schoolDay.showStudentSummaries) {
    host.innerHTML = "";
    host.classList.add("hidden");
    if (toggle) toggle.classList.add("hidden");
    updateSchoolDaySecondaryPanelsVisibility();
    return;
  }
  const roster = schoolDayRosterStudents(referenceISO);
  const blocksByStudent = dailyScheduledBlocks(referenceISO, studentFilterIds);
  const singleSelectedStudentId = studentFilterIds.length === 1 ? studentFilterIds[0] : "";
  const cards = roster
    .map((student) => {
      const instructionBlocks = (blocksByStudent.get(student.id) || [])
        .filter((block) => block.type === "instruction")
        .filter((block) => schoolDayBlockMatchesDisplayFilters(block, subjectFilterIds, courseFilterIds, scheduledItemKeys));
      if (!instructionBlocks.length) return "";
      const attendance = attendanceRecordForStudentDate(student.id, referenceISO);
      const activeInstructionBlocks = instructionBlocks.filter((block) => !effectiveInstructionExcused(student.id, block.courseId, referenceISO));
      const excusedCount = instructionBlocks.length - activeInstructionBlocks.length;
      const completedCount = activeInstructionBlocks.filter((block) => effectiveInstructionCompleted(student.id, block.courseId, referenceISO)).length;
      const needsGradeCount = activeInstructionBlocks.filter((block) => gradeRecordsForStudentCourseDate(student.id, block.courseId, referenceISO).length === 0).length;
      const plannedMinutes = instructionBlocks.reduce((sum, block) => sum + plannedInstructionMinutesForCourse(block.courseId), 0);
      const completedMinutes = instructionBlocks.reduce((sum, block) => (
        effectiveInstructionCompleted(student.id, block.courseId, referenceISO)
          ? sum + effectiveInstructionMinutes(student.id, block.courseId, referenceISO)
          : sum
      ), 0);
      const attendanceText = attendance ? (attendance.present ? "Present" : "Absent") : "Open";
      const attendanceClass = attendance ? (attendance.present ? "success" : "warning") : "muted";
      const activeClass = singleSelectedStudentId === student.id ? " active" : "";
      return `
        <button type="button" class="school-day-student-summary-card${activeClass}" data-school-day-summary-student="${student.id}">
          <div class="school-day-student-summary-header">
            <div class="school-day-card-student">
              <span class="school-day-card-student-label">Student</span>
              <h4>${escapeHtml(student.firstName)} ${escapeHtml(student.lastName)}</h4>
            </div>
            <span class="school-day-status-badge ${attendanceClass}">${attendanceText}</span>
          </div>
          <div class="school-day-student-summary-stats">
            <span><strong>${completedCount}/${activeInstructionBlocks.length}</strong> completed</span>
            ${excusedCount ? `<span><strong>${excusedCount}</strong> excused</span>` : ""}
            <span><strong>${needsGradeCount}</strong> need${needsGradeCount === 1 ? "s" : ""} grade</span>
            <span><strong>${(completedMinutes / 60).toFixed(2)}</strong> / ${(plannedMinutes / 60).toFixed(2)} hrs</span>
          </div>
        </button>`;
    })
    .filter(Boolean);
  const summaryCount = cards.length;
  if (!schoolDayStudentSummariesManual) {
    const pref = workspaceConfig.schoolDay.studentSummariesDefault;
    schoolDayStudentSummariesCollapsed = pref === "expanded" ? false : true;
  }
  host.innerHTML = cards.join("");
  host.classList.toggle("hidden", !summaryCount || schoolDayStudentSummariesCollapsed);
  if (toggle) {
    toggle.classList.toggle("hidden", !summaryCount);
    toggle.textContent = schoolDayStudentSummariesCollapsed
      ? `+ Student Summaries (${summaryCount})`
      : "- Student Summaries";
    toggle.classList.toggle("active", !schoolDayStudentSummariesCollapsed);
    toggle.setAttribute("aria-expanded", schoolDayStudentSummariesCollapsed ? "false" : "true");
  }
  updateSchoolDaySecondaryPanelsVisibility();
  saveSchoolDayPreferences();
}

function updateSchoolDaySecondaryPanelsVisibility() {
  const toolbar = document.getElementById("school-day-secondary-panels");
  if (!toolbar) return;
  const hasVisibleToggle = Array.from(toolbar.querySelectorAll("button"))
    .some((button) => !button.classList.contains("hidden"));
  toolbar.classList.toggle("hidden", !hasVisibleToggle);
}

function schoolDayOverviewBlockLabel(block) {
  if (!block) return "";
  if (block.type === "instruction") return getCourseName(block.courseId);
  return block.label || SCHEDULE_BLOCK_TYPE_LABELS[block.type] || "Scheduled Break";
}

function currentClockMinutes() {
  const now = new Date();
  return (now.getHours() * 60) + now.getMinutes();
}

function schoolDayPlannedEndHasPassed(block, referenceISO) {
  if (!block || !referenceISO) return false;
  const today = todayISO();
  if (referenceISO !== today) return false;
  const plannedEnd = Number.isFinite(block.plannedEnd) ? block.plannedEnd : Number(block.end || 0);
  return plannedEnd <= currentClockMinutes();
}

function schoolDayInstructionPastDue(block, referenceISO) {
  return !!block
    && block.type === "instruction"
    && schoolDayPlannedEndHasPassed(block, referenceISO)
    && effectiveInstructionStatus(block.studentId, block.courseId, referenceISO) === INSTRUCTION_STATUS_SCHEDULED;
}

function schoolDayOverviewBlockStatus(block, referenceISO) {
  if (!block) return { className: "open", label: "Open" };
  if (block.type !== "instruction") {
    if (block.type === "flex") return { className: "flex", label: "Flex" };
    return { className: "break", label: block.scheduleBlockId ? "Schedule" : "Break" };
  }
  const isCompleted = effectiveInstructionCompleted(block.studentId, block.courseId, referenceISO);
  const isExcused = effectiveInstructionExcused(block.studentId, block.courseId, referenceISO);
  const isPastDue = schoolDayInstructionPastDue(block, referenceISO);
  const needsGrade = gradeRecordsForStudentCourseDate(block.studentId, block.courseId, referenceISO).length === 0;
  return {
    className: isCompleted ? "complete" : isExcused ? "excused" : isPastDue ? "past-due" : (needsGrade ? "needs-grade" : "open"),
    label: isCompleted ? "Completed" : isExcused ? "Excused" : isPastDue ? "Past Due" : (needsGrade ? "Needs Grade" : "Open")
  };
}

function schoolDayOverviewSummaryLabel(blocks) {
  const instructionCount = blocks.filter((block) => block.type === "instruction").length;
  const breakCount = blocks.length - instructionCount;
  const parts = [];
  if (instructionCount) parts.push(`${instructionCount} class${instructionCount === 1 ? "" : "es"}`);
  if (breakCount) parts.push(`${breakCount} break${breakCount === 1 ? "" : "s"}`);
  return parts.join(", ") || "No items";
}

function schoolDayOverviewBlockMatchesDisplayFilters(block, subjectFilterIds = [], courseFilterIds = [], scheduledItemKeys = []) {
  if (!block) return false;
  return schoolDayBlockMatchesDisplayFilters(block, subjectFilterIds, courseFilterIds, scheduledItemKeys);
}

function renderSchoolDayOverviewGrid(referenceISO, studentFilterIds = [], subjectFilterIds = [], courseFilterIds = [], scheduledItemKeys = []) {
  const host = document.getElementById("school-day-overview-grid");
  const toggle = document.getElementById("school-day-overview-toggle");
  if (!host) return;
  if (!workspaceConfig.schoolDay.showSideBySideOverview) {
    host.innerHTML = "";
    host.classList.add("hidden");
    if (toggle) toggle.classList.add("hidden");
    updateSchoolDaySecondaryPanelsVisibility();
    return;
  }
  const roster = schoolDayRosterStudents(referenceISO);
  const singleSelectedStudentId = studentFilterIds.length === 1 ? studentFilterIds[0] : "";
  const showOverview = roster.length > 1 && !singleSelectedStudentId;
  if (!showOverview) {
    host.innerHTML = "";
    host.classList.add("hidden");
    if (toggle) toggle.classList.add("hidden");
    updateSchoolDaySecondaryPanelsVisibility();
    return;
  }
  const cards = roster.map((student) => {
    const studentBlocks = dailyScheduledBlocks(referenceISO, [student.id]);
    const visibleBlocks = (studentBlocks.get(student.id) || [])
      .filter((block) => schoolDayOverviewBlockMatchesDisplayFilters(block, subjectFilterIds, courseFilterIds, scheduledItemKeys))
      .sort((a, b) => a.start - b.start || schoolDayOverviewBlockLabel(a).localeCompare(schoolDayOverviewBlockLabel(b)));
    if (!visibleBlocks.length) return "";
    const rows = visibleBlocks.map((block) => {
      const status = schoolDayOverviewBlockStatus(block, referenceISO);
      return `<div class="school-day-overview-row">
        <span class="school-day-overview-time">${escapeHtml(formatClockTime(block.start))}</span>
        <span class="school-day-overview-course">${escapeHtml(schoolDayOverviewBlockLabel(block))}</span>
        <span class="school-day-overview-status ${status.className}">${escapeHtml(status.label)}</span>
      </div>`;
    }).join("");
    return `<button type="button" class="school-day-overview-card" data-school-day-summary-student="${student.id}">
      <div class="school-day-overview-card-header">
        <div class="school-day-card-student">
          <span class="school-day-card-student-label">Student</span>
          <h4>${escapeHtml(student.firstName)} ${escapeHtml(student.lastName)}</h4>
        </div>
        <span>${escapeHtml(schoolDayOverviewSummaryLabel(visibleBlocks))}</span>
      </div>
      <div class="school-day-overview-body">${rows}</div>
    </button>`;
  }).filter(Boolean);
  if (!schoolDayOverviewManual) {
    const pref = workspaceConfig.schoolDay.overviewDefault;
    schoolDayOverviewCollapsed = pref === "collapsed" ? true : pref === "expanded" ? false : cards.length > 0;
  }
  host.innerHTML = cards.join("");
  host.classList.toggle("hidden", !cards.length || schoolDayOverviewCollapsed);
  if (toggle) {
    toggle.classList.toggle("hidden", !cards.length);
    toggle.textContent = schoolDayOverviewCollapsed
      ? `+ Side-By-Side (${cards.length})`
      : "- Side-By-Side";
    toggle.classList.toggle("active", !schoolDayOverviewCollapsed);
    toggle.setAttribute("aria-expanded", schoolDayOverviewCollapsed ? "false" : "true");
  }
  updateSchoolDaySecondaryPanelsVisibility();
  saveSchoolDayPreferences();
}

function applyWorkspaceConfiguration() {
  const config = workspaceConfig || DEFAULT_WORKSPACE_CONFIG;
  const schoolDayFieldVisibility = [
    ["school-day-reference-date-field", config.schoolDay.showReferenceDateFilter],
    ["school-day-student-filter-field", config.schoolDay.showStudentFilter],
    ["school-day-subject-filter-field", config.schoolDay.showSubjectFilter],
    ["school-day-course-filter-field", config.schoolDay.showCourseFilter],
    ["school-day-status-filter-field", config.schoolDay.showStatusFilter]
  ];
  schoolDayFieldVisibility.forEach(([id, visible]) => {
    const node = document.getElementById(id);
    if (node) node.classList.toggle("hidden", !visible);
  });

  document.querySelectorAll(".school-day-quick-filter-btn[data-school-day-quick-filter]").forEach((btn) => {
    const filterName = btn.getAttribute("data-school-day-quick-filter");
    const visible =
      (filterName === "needs-attendance" && config.schoolDay.showNeedsAttendanceFilter) ||
      (filterName === "needs-completion" && config.schoolDay.showNeedsCompletionFilter) ||
      (filterName === "needs-grade" && config.schoolDay.showNeedsGradeFilter) ||
      (filterName === "completed" && config.schoolDay.showCompletedFilter) ||
      (filterName === "past-due" && config.schoolDay.showPastDueFilter) ||
      (filterName === "overridden" && config.schoolDay.showOverriddenFilter);
    btn.classList.toggle("hidden", !visible);
  });

  const resetStudentDayBtn = document.getElementById("school-day-reset-student-btn");
  if (resetStudentDayBtn) resetStudentDayBtn.classList.toggle("hidden", !config.schoolDay.showResetStudentDayButton);
  const resetFilteredDayBtn = document.getElementById("school-day-reset-day-btn");
  if (resetFilteredDayBtn) resetFilteredDayBtn.classList.toggle("hidden", !config.schoolDay.showResetFilteredDayButton);
  renderDashboardSectionVisibility();
}

async function saveAttendanceUpserts(records) {
  if (hostedModeEnabled) {
    await Promise.all(records.map(async (record) => {
      const existing = attendanceRecordForStudentDate(record.studentId, record.date);
      if (existing) {
        const saved = await updateHostedAttendance(existing.id, {
          studentId: record.studentId,
          date: record.date,
          present: record.present
        });
        if (saved) upsertHostedAttendanceState(saved);
      } else {
        const created = await createHostedAttendance({
          id: uid(),
          studentId: record.studentId,
          date: record.date,
          present: record.present
        });
        if (created) upsertHostedAttendanceState(created);
      }
    }));
    return autoExcuseScheduledInstructionsForAbsentAttendance(records);
  }

  records.forEach((record) => {
    const existing = attendanceRecordForStudentDate(record.studentId, record.date);
    if (existing) {
      updateLegacyLocalAttendance(existing, {
        studentId: record.studentId,
        date: record.date,
        present: record.present
      });
    } else {
      createLegacyLocalAttendance({
        studentId: record.studentId,
        date: record.date,
        present: record.present
      });
    }
  });
  saveState();
  return autoExcuseScheduledInstructionsForAbsentAttendance(records);
}

function scheduledOpenInstructionBlocksForAttendanceExcusal(studentId, date) {
  const blocks = dailyScheduledBlocks(date, [studentId]).get(studentId) || [];
  const seen = new Set();
  return blocks
    .filter((block) => block.type === "instruction")
    .filter((block) => effectiveInstructionStatus(block.studentId, block.courseId, date) === INSTRUCTION_STATUS_SCHEDULED)
    .filter((block) => {
      const key = `${block.studentId}::${block.courseId}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

async function autoExcuseScheduledInstructionsForAbsentAttendance(records = []) {
  const absentRecords = [];
  const seen = new Set();
  records.forEach((record) => {
    if (record.present !== false || !record.studentId || !record.date) return;
    const key = `${record.studentId}::${record.date}`;
    if (seen.has(key)) return;
    seen.add(key);
    absentRecords.push(record);
  });

  let excusedCount = 0;
  const excusedStudentIds = new Set();
  for (const record of absentRecords) {
    const blocks = scheduledOpenInstructionBlocksForAttendanceExcusal(record.studentId, record.date);
    for (const block of blocks) {
      const existing = findInstructionActualRecord(block.studentId, block.courseId, record.date);
      await saveInstructionActualMinutes({
        studentId: block.studentId,
        courseId: block.courseId,
        instructorId: effectiveInstructionInstructorId(block.studentId, block.courseId, record.date),
        date: record.date,
        actualMinutes: persistedInstructionActualMinutes(block.studentId, block.courseId, record.date),
        startMinutes: existing?.startMinutes ?? null,
        orderIndex: existing?.orderIndex ?? null,
        status: INSTRUCTION_STATUS_EXCUSED
      });
      excusedCount += 1;
      excusedStudentIds.add(record.studentId);
    }
  }
  return {
    excusedCount,
    studentCount: excusedStudentIds.size
  };
}

function attendanceExcusalSummaryText(summary) {
  const count = Number(summary?.excusedCount || 0);
  if (!count) return "";
  return ` Excused ${count} scheduled ${count === 1 ? "class" : "classes"}.`;
}

