function activeSchoolDayQuickFilterLabels() {
  const keys = [
    ["needs-attendance", schoolDayQuickFilters.needsAttendance],
    ["needs-completion", schoolDayQuickFilters.needsCompletion],
    ["needs-grade", schoolDayQuickFilters.needsGrade],
    ["completed", schoolDayQuickFilters.completed],
    ["past-due", schoolDayQuickFilters.pastDue],
    ["overridden", schoolDayQuickFilters.overridden]
  ];
  return keys
    .filter(([, active]) => !!active)
    .map(([key]) => schoolDayQuickFilterLabel(key))
    .filter(Boolean);
}

function schoolDaySelectedFilterChip(prefix, ids, resolver) {
  if (!ids.length) return "";
  if (ids.length === 1) return `${prefix}: ${resolver(ids[0])}`;
  return `${prefix}: ${ids.length} selected`;
}

function hasActiveSchoolDayQueueFilters({ statusFilter = "all", studentIds = [], subjectIds = [], courseIds = [], scheduledItemKeys = [] } = {}) {
  return schoolDayActiveQuickFilterCount() > 0
    || (statusFilter && statusFilter !== "all")
    || studentIds.length > 0
    || subjectIds.length > 0
    || courseIds.length > 0
    || scheduledItemKeys.length > 0;
}

function renderSchoolDayFilterSummary({ date, statusFilter = "all", studentIds = [], subjectIds = [], courseIds = [], scheduledItemKeys = [] } = {}) {
  const summary = document.getElementById("school-day-filter-summary");
  if (!summary) return;
  const parts = [
    formatDisplayDate(date || document.getElementById("school-day-date")?.value || todayISO()),
    statusFilter && statusFilter !== "all" ? instructionStatusLabel(statusFilter) : "",
    ...activeSchoolDayQuickFilterLabels(),
    schoolDaySelectedFilterChip("Student", studentIds, getStudentName).replace(/^Student: /, ""),
    schoolDaySelectedFilterChip("Subject", subjectIds, getSubjectName).replace(/^Subject: /, ""),
    schoolDaySelectedFilterChip("Scheduled Item", scheduledItemKeys, schoolDayScheduledItemLabel).replace(/^Scheduled Item: /, "")
  ].filter(Boolean);
  summary.textContent = parts.length ? parts.join(" | ") : "All scheduled rows";
}

function renderSchoolDayFilteredEmptyState() {
  return `
    <div class="school-day-empty-state">
      <strong>No rows match the active filters.</strong>
      <span>Use the queue chips above to see what is narrowing the list, or reset the queue.</span>
      <button type="button" data-school-day-clear-filters="1">Clear filters</button>
    </div>`;
}

function renderSchoolDayActiveQueue({ date, rowCount, statusFilter, studentIds = [], subjectIds = [], courseIds = [], scheduledItemKeys = [] } = {}) {
  const host = document.getElementById("school-day-active-queue");
  if (!host) return;
  const hasActiveFilters = hasActiveSchoolDayQueueFilters({ statusFilter, studentIds, subjectIds, courseIds, scheduledItemKeys });
  const emptyFilteredQueue = rowCount === 0 && hasActiveFilters;
  const filterChips = [
    `Date: ${formatDisplayDate(date || todayISO())}`,
    statusFilter && statusFilter !== "all" ? `Status: ${instructionStatusLabel(statusFilter)}` : "",
    ...activeSchoolDayQuickFilterLabels().map((label) => `Filter: ${label}`),
    schoolDaySelectedFilterChip("Student", studentIds, getStudentName),
    schoolDaySelectedFilterChip("Subject", subjectIds, getSubjectName),
    schoolDaySelectedFilterChip("Scheduled Item", scheduledItemKeys, schoolDayScheduledItemLabel)
  ].filter(Boolean);
  if (!hasActiveFilters) filterChips.push("All scheduled rows");
  host.classList.remove("hidden");
  host.innerHTML = `
    <div class="school-day-active-queue-summary">
      <strong>${emptyFilteredQueue ? "No matching rows" : `${rowCount} row${rowCount === 1 ? "" : "s"} shown`}</strong>
      <span>${emptyFilteredQueue ? "Active filters are hiding the queue" : "Daily Schedule work queue"}</span>
    </div>
    <div class="school-day-active-queue-right">
      <div class="school-day-active-queue-chips">
        ${filterChips.map((chip) => `<span>${escapeHtml(chip)}</span>`).join("")}
      </div>
      ${hasActiveFilters ? `<div class="school-day-active-queue-actions"><button type="button" data-school-day-clear-filters="1">Clear filters</button></div>` : ""}
    </div>`;
}

function resetSchoolDayQuickFilters() {
  schoolDayQuickFilters.needsAttendance = false;
  schoolDayQuickFilters.needsCompletion = false;
  schoolDayQuickFilters.needsGrade = false;
  schoolDayQuickFilters.completed = false;
  schoolDayQuickFilters.pastDue = false;
  schoolDayQuickFilters.overridden = false;
}

function openSchoolDayFromDashboard({
  date = todayISO(),
  tab = "daily-schedule",
  studentIds = [],
  subjectIds = [],
  courseIds = [],
  quickFilter = "",
  statusFilter = "all",
  contextLabel = ""
} = {}) {
  const dateInput = document.getElementById("school-day-date");
  const normalizedDate = date || todayISO();
  const normalizedTab = ["daily-schedule", "attendance", "grades"].includes(tab) ? tab : "daily-schedule";
  const normalizedQuickFilters = String(quickFilter || "").split(",").map((key) => key.trim()).filter(Boolean);
  const normalizedStudentIds = Array.isArray(studentIds) ? studentIds : [];
  const normalizedSubjectIds = Array.isArray(subjectIds) ? subjectIds : [];
  const normalizedCourseIds = Array.isArray(courseIds) ? courseIds : [];
  if (dateInput) dateInput.value = normalizedDate;
  resetSchoolDayQuickFilters();
  setSchoolDaySelectedStatus(statusFilter);
  normalizedQuickFilters.forEach((key) => {
    setSchoolDayQuickFilterState(key, true);
  });
  applySchoolDayFilterSelection({
    studentIds: normalizedStudentIds,
    subjectIds: normalizedSubjectIds,
    courseIds: normalizedCourseIds
  });
  syncSchoolDayFilterSubjectCourseOptions();
  currentSchoolDayTab = normalizedTab;
  schoolDayInlineGradeKey = "";
  const dashboardTabLabel = currentDashboardTab === "execution"
    ? "Execution"
    : currentDashboardTab === "performance"
      ? "Performance"
      : currentDashboardTab === "compliance"
        ? "Compliance"
        : "Overview";
  schoolDayDashboardReturnContext = {
    dashboardTab: currentDashboardTab,
    date: normalizedDate,
    tab: normalizedTab,
    studentIds: normalizedStudentIds,
    subjectIds: normalizedSubjectIds,
    courseIds: normalizedCourseIds,
    quickFilters: normalizedQuickFilters,
    statusFilter: statusFilter || "all",
    message: contextLabel
      ? `${contextLabel} from Dashboard > ${dashboardTabLabel} for ${formatDisplayDate(normalizedDate)}.`
      : `Opened from Dashboard > ${dashboardTabLabel} for ${formatDisplayDate(normalizedDate)}.`
  };
  saveSchoolDayPreferences();
  activateTab("school-day");
  renderSchoolDay();
}

function schoolDayGradeKey(studentId, courseId, date) {
  return `${studentId}::${courseId}::${date}`;
}

function getGradesFilterSelectedScheduledItemKeys() {
  const checked = Array.from(document.querySelectorAll(".grades-filter-scheduled-item-checkbox:checked"))
    .map((el) => normalizeSchoolDayScheduledItemKey(el.value))
    .filter(Boolean);
  if (checked.length || document.querySelectorAll(".grades-filter-scheduled-item-checkbox").length) return checked;
  return Array.from(gradesFilterSelectedScheduledItemKeys).map(normalizeSchoolDayScheduledItemKey).filter(Boolean);
}

function updateGradesFilterScheduledItemSummary() {
  const summary = document.getElementById("grades-filter-scheduled-item-summary");
  if (!summary) return;
  const selectedCount = getGradesFilterSelectedScheduledItemKeys().length;
  const totalCount = document.querySelectorAll(".grades-filter-scheduled-item-checkbox").length;
  summary.textContent = selectedCount === 0 || selectedCount === totalCount
    ? "Course/Class/Block (All)"
    : `Course/Class/Block (${selectedCount} selected)`;
}

function setGradesFilterScheduledItemSelection(keys = []) {
  gradesFilterSelectedScheduledItemKeys = new Set(
    keys.map((key) => normalizeSchoolDayScheduledItemKey(key)).filter(Boolean)
  );
  setCalendarChecklistSelection("grades-filter-scheduled-item-checkbox", Array.from(gradesFilterSelectedScheduledItemKeys));
  syncCalendarAllCheckbox("grades-filter-scheduled-item-checkbox", "grades-filter-scheduled-item-all-checkbox");
  updateGradesFilterScheduledItemSummary();
}

function renderGradesScheduledItemChecklist(courses, preselectedScheduledItemKeys = []) {
  const optionsWrap = document.getElementById("grades-filter-scheduled-item-options");
  if (!optionsWrap) return;
  const studentFilter = document.getElementById("grades-filter-student")?.value || "all";
  const courseIds = new Set(courses.map((course) => course.id));
  const enrolledSectionIds = studentFilter === "all"
    ? null
    : new Set(
      state.sectionEnrollments
        .filter((entry) => entry.studentId === studentFilter)
        .map((entry) => entry.courseSectionId)
        .filter(Boolean)
    );
  const sectionOptions = sortedCourseSections()
    .filter((section) => courseIds.has(section.courseId))
    .filter((section) => !enrolledSectionIds || enrolledSectionIds.has(section.id));
  const blockOptions = schoolDayScheduleBlockFilterOptions(studentFilter === "all" ? [] : [studentFilter]);
  const availableKeys = new Set([
    ...sectionOptions.map((section) => `courseSection:${section.id}`),
    ...courses.map((course) => `course:${course.id}`),
    ...blockOptions.map((block) => `scheduleBlock:${block.id}`)
  ]);
  const selected = new Set(
    preselectedScheduledItemKeys
      .map((key) => normalizeSchoolDayScheduledItemKey(key))
      .filter((key) => availableKeys.has(key))
  );
  gradesFilterSelectedScheduledItemKeys = selected;
  const allChecked = availableKeys.size > 0 && Array.from(availableKeys).every((key) => selected.has(key));
  const allRow = availableKeys.size
    ? `<div class="checklist-row"><input id="grades-filter-scheduled-item-all" type="checkbox" class="grades-filter-scheduled-item-all-checkbox"${allChecked ? " checked" : ""}><label for="grades-filter-scheduled-item-all">All</label></div>`
    : "";
  const sectionCheckboxes = sectionOptions.map((section, idx) => {
    const key = `courseSection:${section.id}`;
    const checked = selected.has(key) ? " checked" : "";
    const inputId = `grades-filter-section-${idx}-${section.id}`;
    const course = getCourse(section.courseId);
    const subjectId = course?.subjectId || "";
    const requiredBadge = subjectId && isRequiredSubject(subjectId) ? " <span class=\"subject-required-badge\">Required</span>" : "";
    const meta = [
      subjectId ? getSubjectName(subjectId) : "",
      ...courseSectionSchoolDayMeta(section).filter((item) => !/ enrolled$/.test(item))
    ];
    return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="grades-filter-scheduled-item-checkbox" value="${key}"${checked}><label for="${inputId}">${renderSchoolDayScheduledItemOption(sectionDisplayName(section.id), meta, requiredBadge)}</label></div>`;
  }).join("");
  const courseCheckboxes = courses.map((course, idx) => {
    const key = `course:${course.id}`;
    const checked = selected.has(key) ? " checked" : "";
    const inputId = `grades-filter-course-${idx}-${course.id}`;
    const requiredBadge = isRequiredSubject(course.subjectId) ? " <span class=\"subject-required-badge\">Required</span>" : "";
    return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="grades-filter-scheduled-item-checkbox" value="${key}"${checked}><label for="${inputId}">${renderSchoolDayScheduledItemOption(course.name, [getSubjectName(course.subjectId), ...courseSchoolDayMeta(course)], requiredBadge)}</label></div>`;
  }).join("");
  const blockCheckboxes = blockOptions.map((block, idx) => {
    const key = `scheduleBlock:${block.id}`;
    const checked = selected.has(key) ? " checked" : "";
    const inputId = `grades-filter-block-${idx}-${block.id}`;
    const typeLabel = SCHEDULE_BLOCK_TYPE_LABELS[block.type] || "Schedule Block";
    return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="grades-filter-scheduled-item-checkbox" value="${key}"${checked}><label for="${inputId}">${renderSchoolDayScheduledItemOption(block.name, [typeLabel, ...scheduleBlockSchoolDayMeta(block)])}</label></div>`;
  }).join("");
  const sections = [];
  if (sectionCheckboxes) sections.push(`<div class="checklist-group-label">Classes</div>${sectionCheckboxes}`);
  if (courseCheckboxes) sections.push(`<div class="checklist-group-label">Courses</div>${courseCheckboxes}`);
  if (blockCheckboxes) sections.push(`<div class="checklist-group-label">Schedule Blocks</div>${blockCheckboxes}`);
  optionsWrap.innerHTML = sections.length ? `${allRow}${sections.join("")}` : "<span>No scheduled items available.</span>";
  syncCalendarAllCheckbox("grades-filter-scheduled-item-checkbox", "grades-filter-scheduled-item-all-checkbox");
  updateGradesFilterScheduledItemSummary();
}

function syncGradesFilterSubjectCourseOptions() {
  const studentFilter = document.getElementById("grades-filter-student")?.value || "all";
  const instructorFilter = document.getElementById("grades-filter-instructor")?.value || "all";
  const subjectSelect = document.getElementById("grades-filter-subject");
  if (!subjectSelect) return;

  const previousSubject = subjectSelect.value || "all";
  const previousScheduledItemKeys = getGradesFilterSelectedScheduledItemKeys();
  let coursePool = state.courses;

  if (studentFilter !== "all") {
    const enrolledCourses = getEnrolledCoursesForStudent(studentFilter);
    coursePool = enrolledCourses;
  }
  if (instructorFilter !== "all") {
    coursePool = coursePool.filter((course) => courseMatchesInstructorFilter(course.id, instructorFilter));
  }
  const subjectIds = new Set(coursePool.map((course) => course.subjectId));
  const subjectPool = state.subjects.filter((subject) => subjectIds.has(subject.id));

  subjectSelect.innerHTML = "<option value='all'>All Subjects</option>";
  subjectPool.forEach((s) => {
    const option = document.createElement("option");
    option.value = s.id;
    option.textContent = s.name;
    subjectSelect.appendChild(option);
  });
  if (Array.from(subjectSelect.options).some((o) => o.value === previousSubject)) {
    subjectSelect.value = previousSubject;
  }

  const activeSubject = subjectSelect.value || "all";
  const filteredCourses = activeSubject === "all"
    ? coursePool
    : coursePool.filter((c) => c.subjectId === activeSubject);

  renderGradesScheduledItemChecklist(filteredCourses, previousScheduledItemKeys);
}

function getEligibleCoursesForStudentSubject(studentId, subjectId, includeCourseId) {
  const enrolledCourseIds = new Set(
    state.enrollments
      .filter((e) => e.studentId === studentId)
      .map((e) => e.courseId)
  );

  if (includeCourseId) enrolledCourseIds.add(includeCourseId);

  return state.courses.filter((c) => enrolledCourseIds.has(c.id));
}

function buildGradeEntryRow(existingGrade, preset = {}) {
  const tr = document.createElement("tr");
  tr.setAttribute("data-grade-entry-row-id", existingGrade?.id || uid());
  const useSchoolDayInlineActions = !!preset.schoolDayInline;

  const dateValue = existingGrade ? existingGrade.date : (preset.date || defaultReferenceDateForActiveYear());
  const gradeValue = existingGrade ? Number(existingGrade.score || 0) : "";
  const selectedGradeStudentId = existingGrade ? existingGrade.studentId : (preset.studentId || (state.students[0] ? state.students[0].id : ""));
  const selectedSubjectId = existingGrade ? existingGrade.subjectId : (preset.subjectId || (state.subjects[0] ? state.subjects[0].id : ""));
  const selectedCourseId = existingGrade ? existingGrade.courseId : (preset.courseId || "");
  const allGradeTypes = availableGradeTypes();
  const selectedGradeType = existingGrade
    ? gradeTypeName(existingGrade)
    : (preset.gradeType || (allGradeTypes.includes("Quiz") ? "Quiz" : (allGradeTypes[0] || "Test")));

  const studentOptions = state.students
    .map((s) => `<option value="${s.id}"${s.id === selectedGradeStudentId ? " selected" : ""}>${s.firstName} ${s.lastName}</option>`)
    .join("");

  const eligibleSubjects = getEligibleSubjectsForStudent(selectedGradeStudentId, selectedSubjectId);
  const defaultSubjectId = eligibleSubjects.some((s) => s.id === selectedSubjectId)
    ? selectedSubjectId
    : (eligibleSubjects[0] ? eligibleSubjects[0].id : "");
  const subjectOptions = eligibleSubjects.length
    ? eligibleSubjects.map((s) => `<option value="${s.id}"${s.id === defaultSubjectId ? " selected" : ""}>${s.name}</option>`).join("")
    : "<option value=''>No enrolled subjects</option>";

  const courseOptions = getEligibleCoursesForStudentSubject(selectedGradeStudentId, defaultSubjectId, selectedCourseId)
    .map((c) => `<option value="${c.id}"${c.id === selectedCourseId ? " selected" : ""}>${c.name}</option>`)
    .join("") || "<option value=''>No enrolled courses</option>";
  const gradeTypeOptions = allGradeTypes
    .map((type) => `<option value="${type}"${selectedGradeType === type ? " selected" : ""}>${type}</option>`)
    .join("");

  if (existingGrade) {
    tr.setAttribute("data-edit-grade-id", existingGrade.id);
  }

  const saveLabel = useSchoolDayInlineActions ? "Save Grade" : (existingGrade ? "Update" : "Save");
  const calculateLabel = useSchoolDayInlineActions ? "Calculate Score" : "Calculate";
  const actionsMarkup = `<div class="table-action-row grade-entry-actions${useSchoolDayInlineActions ? " school-day-inline-grade-actions" : ""}">
      <button type="button" data-grade-save="1">${saveLabel}</button>
      <button type="button" data-grade-calc-toggle="1">${calculateLabel}</button>
      <button type="button" data-grade-cancel="1">Cancel</button>
    </div>`;

  tr.innerHTML = `
    <td><input class="grade-row-date" type="date" value="${dateValue}"></td>
    <td><select class="grade-row-student">${studentOptions}</select></td>
    <td><select class="grade-row-subject">${subjectOptions}</select></td>
    <td><select class="grade-row-course">${courseOptions}</select></td>
    <td>
      <select class="grade-row-type">
        ${gradeTypeOptions}
      </select>
    </td>
    <td><input class="grade-row-value" type="number" min="0" max="100" step="0.1" placeholder="0-100" value="${gradeValue}"></td>
    <td>
      ${actionsMarkup}
    </td>
  `;

  return tr;
}

function buildGradeCalculatorRow(sourceRowId) {
  const tr = document.createElement("tr");
  tr.className = "grade-calc-row";
  tr.setAttribute("data-grade-calc-for", sourceRowId);
  tr.innerHTML = `
    <td colspan="7">
      <div class="grade-calc-panel">
        <label>
          <span>Missed Items</span>
          <input class="grade-calc-missed" type="number" min="0" step="1" value="0">
        </label>
        <label>
          <span>Total Items</span>
          <input class="grade-calc-total" type="number" min="1" step="1" value="">
        </label>
        <div class="table-action-row grade-calc-actions">
          <button type="button" data-grade-calc-apply="1">Calculate Grade</button>
          <button type="button" data-grade-calc-close="1">Cancel</button>
        </div>
      </div>
    </td>
  `;
  return tr;
}

function removeGradeCalculatorRow(sourceRowId) {
  const calcRow = document.querySelector(`tr[data-grade-calc-for="${sourceRowId}"]`);
  if (calcRow) calcRow.remove();
}

function setInlineGradeCalculateButtonVisibility(target, visible) {
  let calculateBtn = null;
  if (target?.matches?.("[data-grade-calc-toggle]")) {
    calculateBtn = target;
  } else if (target?.matches?.("tr")) {
    calculateBtn = target.querySelector("[data-grade-calc-toggle]");
  } else if (target) {
    calculateBtn = target.querySelector?.("[data-grade-calc-toggle]") || null;
  }
  if (!calculateBtn) return;
  calculateBtn.hidden = !visible;
  calculateBtn.disabled = !visible;
  calculateBtn.style.display = visible ? "" : "none";
}

function findInlineGradeActionRow(rowId, sourceRow) {
  if (sourceRow?.nextElementSibling?.getAttribute("data-grade-action-for") === rowId) {
    return sourceRow.nextElementSibling;
  }
  return Array.from(sourceRow?.parentElement?.querySelectorAll?.("tr[data-grade-action-for]") || [])
    .find((candidate) => candidate.getAttribute("data-grade-action-for") === rowId) || null;
}

function toggleGradeCalculatorRow(row, triggerBtn) {
  if (!row) return;
  const rowId = row.getAttribute("data-grade-entry-row-id");
  if (!rowId) return;
  const actionRow = findInlineGradeActionRow(rowId, row);
  const existing = document.querySelector(`tr[data-grade-calc-for="${rowId}"]`);
  if (existing) {
    existing.remove();
    setInlineGradeCalculateButtonVisibility(triggerBtn || actionRow, true);
    return;
  }
  removeGradeCalculatorRow(rowId);
  const calcRow = buildGradeCalculatorRow(rowId);
  row.insertAdjacentElement("afterend", calcRow);
  setInlineGradeCalculateButtonVisibility(triggerBtn || actionRow, false);
  calcRow.querySelector(".grade-calc-total")?.focus();
}

function applyGradeCalculator(calcRow) {
  if (!calcRow) return;
  const rowId = calcRow.getAttribute("data-grade-calc-for");
  const sourceRow = rowId ? document.querySelector(`tr[data-grade-entry-row-id="${rowId}"]`) : null;
  if (!sourceRow) {
    calcRow.remove();
    return;
  }

  const missed = Number(calcRow.querySelector(".grade-calc-missed")?.value);
  const total = Number(calcRow.querySelector(".grade-calc-total")?.value);
  if (!Number.isFinite(total) || total <= 0) {
    alert("Total Items must be greater than 0.");
    return;
  }
  if (!Number.isFinite(missed) || missed < 0) {
    alert("Missed Items cannot be negative.");
    return;
  }
  if (missed > total) {
    alert("Missed Items cannot be greater than Total Items.");
    return;
  }

  const percentage = Math.round(((total - missed) / total) * 100);
  const gradeInput = sourceRow.querySelector(".grade-row-value");
  if (gradeInput) {
    gradeInput.value = String(percentage);
  }
  setInlineGradeCalculateButtonVisibility(findInlineGradeActionRow(rowId, sourceRow) || sourceRow, true);
  calcRow.remove();
}

function updateGradeRowCourses(row) {
  const studentSelect = row.querySelector(".grade-row-student");
  const subjectSelect = row.querySelector(".grade-row-subject");
  const courseSelect = row.querySelector(".grade-row-course");
  if (!studentSelect || !subjectSelect || !courseSelect) return;

  const studentId = studentSelect.value;
  const currentSubjectId = subjectSelect.value;
  const currentCourseId = courseSelect.value;

  const eligibleSubjects = getEligibleSubjectsForStudent(studentId, currentSubjectId);
  subjectSelect.innerHTML = eligibleSubjects.length
    ? eligibleSubjects.map((s) => `<option value="${s.id}"${s.id === currentSubjectId ? " selected" : ""}>${s.name}</option>`).join("")
    : "<option value=''>No enrolled subjects</option>";

  const subjectId = eligibleSubjects.some((s) => s.id === currentSubjectId)
    ? currentSubjectId
    : (eligibleSubjects[0] ? eligibleSubjects[0].id : "");
  if (subjectId) subjectSelect.value = subjectId;

  const courseOptions = getEligibleCoursesForStudentSubject(studentId, subjectId, currentCourseId);
  courseSelect.innerHTML = courseOptions.length
    ? courseOptions.map((c) => `<option value="${c.id}"${c.id === currentCourseId ? " selected" : ""}>${c.name}</option>`).join("")
    : "<option value=''>No enrolled courses</option>";

  const resolvedCourseId = courseOptions.some((c) => c.id === currentCourseId)
    ? currentCourseId
    : (courseOptions[0] ? courseOptions[0].id : "");
  if (resolvedCourseId) courseSelect.value = resolvedCourseId;

  const resolvedCourse = courseOptions.find((c) => c.id === resolvedCourseId);
  if (resolvedCourse && eligibleSubjects.some((s) => s.id === resolvedCourse.subjectId)) {
    subjectSelect.value = resolvedCourse.subjectId;
  }
}

function updateGradeEntryVisibility() {
  const wrap = document.getElementById("grade-entry-wrap");
  const body = document.getElementById("grade-entry-body");
  if (!wrap || !body) return;
  const shouldShowDefaultRow = currentTab === "grades"
    && currentGradesTab !== "search"
    && !isStudentUser()
    && state.students.length
    && state.subjects.length
    && state.courses.length;
  if (shouldShowDefaultRow && !body.querySelector("tr")) {
    body.appendChild(buildGradeEntryRow());
  }
  wrap.classList.toggle("hidden", !body.querySelector("tr"));
}

function gradeAnalytics(options = {}) {
  const instructorId = options.instructorId || "all";
  const { startDate, endDate } = activeSchoolYearRange();
  const tests = state.tests
    .filter((test) => testMatchesInstructorFilter(test, instructorId))
    .filter((test) => inRange(test.date, startDate, endDate))
    .map((t) => ({ ...t, grade: pct(t.score, t.maxScore) }));
  const byStudent = new Map(); const bySubject = new Map();
  tests.forEach((t) => {
    if (!byStudent.has(t.studentId)) byStudent.set(t.studentId, []);
    byStudent.get(t.studentId).push(t);
    if (!bySubject.has(t.subjectId)) bySubject.set(t.subjectId, []);
    bySubject.get(t.subjectId).push(t);
  });
  const student = Array.from(byStudent.entries()).map(([studentId, testsForStudent]) => {
    const quarterRowsForStudent = state.settings.quarters.map((q) => {
      const quarterTests = testsForStudent.filter((t) => inRange(t.date, q.startDate, q.endDate));
      return { avg: weightedAverageForTests(quarterTests, { quarterScoped: true }), count: quarterTests.length };
    });
    return { studentId, avg: averageOfQuarterAverages(quarterRowsForStudent), count: testsForStudent.length };
  });
  const subject = Array.from(bySubject.entries()).map(([subjectId, testsForSubject]) => {
    const quarterRowsForSubject = state.settings.quarters.map((q) => {
      const quarterTests = testsForSubject.filter((t) => inRange(t.date, q.startDate, q.endDate));
      return { avg: weightedAverageForTests(quarterTests, { quarterScoped: true }), count: quarterTests.length };
    });
    return { subjectId, avg: averageOfQuarterAverages(quarterRowsForSubject), count: testsForSubject.length };
  });

  const quarterRows = state.settings.quarters.map((q) => {
    const quarterTests = tests.filter((t) => inRange(t.date, q.startDate, q.endDate));
    return { label: q.name, avg: weightedAverageForTests(quarterTests, { quarterScoped: true }), count: quarterTests.length };
  });
  const runningAverages = Array.from(byStudent.values())
    .map((testsForStudent) => weightedAverageForTests(testsForStudent))
    .filter((value) => Number.isFinite(value));
  const running = runningAverages.length ? avg(runningAverages) : 0;

  const sy = state.settings.schoolYear;
  const annualTests = tests.filter((t) => inRange(t.date, sy.startDate, sy.endDate));
  const cq = currentQuarter(toDate(defaultReferenceDateForActiveYear()));
  const cqTests = cq ? tests.filter((t) => inRange(t.date, cq.startDate, cq.endDate)) : [];

  return {
    student, subject, running,
    quarterRows,
    annualAvg: running,
    annualCount: annualTests.length,
    currentQuarterAvg: weightedAverageForTests(cqTests, { quarterScoped: true })
  };
}

function schoolYearMonths(startDate, endDate) {
  const start = toDate(startDate);
  const end = toDate(endDate);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end < start) return [];
  const cursor = new Date(start.getFullYear(), start.getMonth(), 1, 12, 0, 0);
  const limit = new Date(end.getFullYear(), end.getMonth(), 1, 12, 0, 0);
  const out = [];
  while (cursor <= limit) {
    out.push({ year: cursor.getFullYear(), month: cursor.getMonth() });
    cursor.setMonth(cursor.getMonth() + 1);
  }
  return out;
}

function renderGradeTrending() {
  const chartHost = document.getElementById("grade-trending-chart");
  if (!chartHost) return;
  const allowedStudentIds = visibleStudentIds();

  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const syEnd = toDate(sy.endDate);
  const today = toDate(todayISO());
  const effectiveEnd = syEnd < today ? syEnd : today;

  const quarterFilter = document.getElementById("trend-filter-quarter")?.value || "all";
  const subjectFilter = document.getElementById("trend-filter-subject")?.value || "all";
  const instructorFilter = document.getElementById("trend-filter-instructor")?.value || "all";
  const gradeTypeFilter = document.getElementById("trend-filter-grade-type")?.value || "all";
  const selectedStudentIds = getTrendSelectedStudentIds();
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);
  const effectiveEndIso = toISO(effectiveEnd);
  let monthStartIso = sy.startDate;
  let monthEndIso = effectiveEndIso;
  if (quarterRange && quarterFilter !== "all") {
    if (toDate(quarterRange.startDate) > toDate(monthStartIso)) monthStartIso = quarterRange.startDate;
    if (toDate(quarterRange.endDate) < toDate(monthEndIso)) monthEndIso = quarterRange.endDate;
  }

  const months = schoolYearMonths(monthStartIso, monthEndIso);
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : (quarterFilter !== "all"
        ? "<p class='muted'>No elapsed months in the selected quarter yet.</p>"
        : "<p class='muted'>No school year range set.</p>");
    return;
  }

  const filteredTests = state.tests.filter((t) => {
    if (!allowedStudentIds.has(t.studentId)) return false;
    if (!inRange(t.date, sy.startDate, sy.endDate)) return false;
    if (quarterRange && quarterFilter !== "all" && !inRange(t.date, quarterRange.startDate, quarterRange.endDate)) return false;
    if (subjectFilter !== "all" && t.subjectId !== subjectFilter) return false;
    if (!testMatchesInstructorFilter(t, instructorFilter)) return false;
    const gradeType = gradeTypeName(t);
    if (gradeTypeFilter !== "all" && gradeType !== gradeTypeFilter) return false;
    return true;
  });

  const seriesBase = selectedStudentIds.length
    ? selectedStudentIds.map((studentId) => ({ id: studentId, label: getStudentName(studentId), tests: filteredTests.filter((t) => t.studentId === studentId) }))
    : (isStudentUser()
      ? visibleStudents().map((student) => ({ id: student.id, label: getStudentName(student.id), tests: filteredTests.filter((t) => t.studentId === student.id) }))
      : [{ id: "all", label: "All Students", tests: filteredTests }]);
  const palette = ["#f97316", "#20a65a", "#2563eb", "#8b5cf6", "#ef4444", "#0f766e", "#a16207", "#db2777"];

  const series = seriesBase.map((entry, idx) => {
    const monthly = months.map((monthEntry) => {
      const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
      const monthEnd = new Date(monthEntry.year, monthEntry.month + 1, 0, 12, 0, 0);
      const monthStartIso = toISO(monthStart);
      const monthEndIso = toISO(monthEnd);
      const monthTests = entry.tests.filter((t) => inRange(t.date, monthStartIso, monthEndIso));
      return {
        label: monthStart.toLocaleDateString(undefined, { month: "short" }),
        avg: weightedAverageForTests(monthTests),
        count: monthTests.length
      };
    });
    return { ...entry, color: palette[idx % palette.length], monthly };
  });

  const plottedValues = series.flatMap((lineSeries) =>
    lineSeries.monthly.filter((row) => row.count > 0).map((row) => row.avg));
  let yMin = 50;
  let yMax = 100;
  if (plottedValues.length) {
    const rawMin = Math.min(...plottedValues);
    const rawMax = Math.max(...plottedValues);
    yMin = Math.max(50, Math.floor((rawMin - 2) / 5) * 5);
    yMax = Math.min(100, Math.ceil((rawMax + 2) / 5) * 5);
    if (yMax - yMin < 10) {
      yMax = Math.min(100, yMin + 10);
      yMin = Math.max(50, yMax - 10);
    }
  }
  const yTickStep = (yMax - yMin) <= 30 ? 5 : 10;
  const yTicks = [];
  for (let tick = yMin; tick <= yMax; tick += yTickStep) yTicks.push(tick);
  if (yTicks[yTicks.length - 1] !== yMax) yTicks.push(yMax);

  const width = 1120;
  const height = 330;
  const margin = { top: 40, right: 34, bottom: 58, left: 74 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = months.length > 1 ? xSpan / (months.length - 1) : 0;
  const xFor = (idx) => margin.left + xPad + (xStep * idx);
  const yFor = (value) => {
    const clamped = clamp(value, yMin, yMax);
    return margin.top + ((yMax - clamped) / (yMax - yMin)) * plotH;
  };
  const baselineY = yFor(yMin);

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick}</text></g>`;
  }).join("");

  const xTickSvg = months.map((row, idx) => {
    const monthStart = new Date(row.year, row.month, 1, 12, 0, 0);
    const x = xFor(idx);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${monthStart.toLocaleDateString(undefined, { month: "short" })}</text>`;
  }).join("");

  const lineSvg = series.map((lineSeries) => {
    let path = "";
    lineSeries.monthly.forEach((row, idx) => {
      if (row.count <= 0) return;
      const x = xFor(idx);
      const y = yFor(row.avg || 0);
      if (!path) path += `M ${x.toFixed(2)} ${y.toFixed(2)} `;
      else path += `L ${x.toFixed(2)} ${y.toFixed(2)} `;
    });
    return path ? `<path d="${path.trim()}" class="trend-line" style="stroke:${lineSeries.color}" fill="none"></path>` : "";
  }).join("");

  const areaSvg = gradeTrendViewMode === "area" ? series.map((lineSeries) => {
    const points = lineSeries.monthly
      .map((row, idx) => row.count > 0 ? { x: xFor(idx), y: yFor(row.avg || 0) } : null)
      .filter(Boolean);
    if (points.length < 2) return "";
    const linePath = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    const first = points[0];
    const last = points[points.length - 1];
    return `<path d="${linePath} L ${last.x.toFixed(2)} ${baselineY.toFixed(2)} L ${first.x.toFixed(2)} ${baselineY.toFixed(2)} Z" class="trend-area" style="fill:${lineSeries.color}"></path>`;
  }).join("") : "";

  const pointSvg = gradeTrendShowDataPoints ? series.flatMap((lineSeries) => lineSeries.monthly.map((row, idx) => {
    if (row.count <= 0) return "";
    const x = xFor(idx);
    const y = yFor(row.avg || 0);
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${lineSeries.color};stroke:${lineSeries.color}"><title>${lineSeries.label} ${row.label}: ${row.avg.toFixed(1)}%</title></circle>`;
  })).join("") : "";

  const labelTop = margin.top + 10;
  const labelBottom = height - margin.bottom - 6;
  const minLabelGap = 12;
  const valueLabelParts = [];
  months.forEach((_, monthIdx) => {
    const monthLabels = series.map((lineSeries, lineIdx) => {
      const row = lineSeries.monthly[monthIdx];
      if (row.count <= 0) return null;
      const x = xFor(monthIdx);
      const y = yFor(row.avg || 0);
      const nearTop = y <= margin.top + 16;
      const nearBottom = y >= (height - margin.bottom - 10);
      const offsetBase = ((monthIdx + lineIdx) % 2 === 0) ? -10 : 14;
      const offset = nearTop ? 22 : (nearBottom ? -10 : offsetBase);
      const preferredY = clamp(y + offset, labelTop, labelBottom);
      return {
        color: lineSeries.color,
        text: `${(row.avg || 0).toFixed(1)}%`,
        x,
        preferredY
      };
    }).filter(Boolean).sort((a, b) => a.preferredY - b.preferredY);

    // Push labels down to enforce a minimum vertical gap.
    for (let i = 1; i < monthLabels.length; i += 1) {
      if (monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
        monthLabels[i].preferredY = monthLabels[i - 1].preferredY + minLabelGap;
      }
    }
    // If we overflow bottom, pull labels up while preserving spacing.
    const overflow = monthLabels.length ? monthLabels[monthLabels.length - 1].preferredY - labelBottom : 0;
    if (overflow > 0) {
      for (let i = monthLabels.length - 1; i >= 0; i -= 1) {
        monthLabels[i].preferredY -= overflow;
        if (i > 0 && monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
          monthLabels[i - 1].preferredY = monthLabels[i].preferredY - minLabelGap;
        }
      }
    }
    // Final clamp safety.
    monthLabels.forEach((label) => {
      label.preferredY = clamp(label.preferredY, labelTop, labelBottom);
      const labelWidth = 37;
      valueLabelParts.push(`<g class="trend-value-pill"><rect x="${(label.x - labelWidth / 2).toFixed(2)}" y="${(label.preferredY - 12).toFixed(2)}" width="${labelWidth}" height="18" rx="6" style="fill:${label.color};stroke:${label.color}"></rect><text x="${label.x.toFixed(2)}" y="${label.preferredY.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${label.color}">${label.text}</text></g>`);
    });
  });
  const valueLabelSvg = gradeTrendShowDataPoints ? valueLabelParts.join("") : "";

  const monthHoverZoneSvg = months.map((monthEntry, monthIdx) => {
    const x = xFor(monthIdx);
    const previousX = monthIdx > 0 ? xFor(monthIdx - 1) : margin.left;
    const nextX = monthIdx < months.length - 1 ? xFor(monthIdx + 1) : width - margin.right;
    const left = monthIdx > 0 ? (previousX + x) / 2 : margin.left;
    const right = monthIdx < months.length - 1 ? (x + nextX) / 2 : width - margin.right;
    const monthLabel = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" });
    const monthTooltip = series.map((lineSeries) => {
      const row = lineSeries.monthly[monthIdx];
      if (!row || row.count <= 0) return "";
      return `${lineSeries.label} ${monthLabel}: ${row.avg.toFixed(1)}%`;
    }).filter(Boolean).join("\n");
    if (!monthTooltip) return "";
    return `<rect x="${left.toFixed(2)}" y="${margin.top}" width="${Math.max(1, right - left).toFixed(2)}" height="${plotH.toFixed(2)}" fill="transparent" pointer-events="all"><title>${escapeHtml(monthTooltip)}</title></rect>`;
  }).join("");

  const selectedStudentIdSet = new Set(selectedStudentIds);
  const summaryMonthly = months.map((monthEntry) => {
    const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
    const monthEnd = new Date(monthEntry.year, monthEntry.month + 1, 0, 12, 0, 0);
    const monthStartIso = toISO(monthStart);
    const monthEndIso = toISO(monthEnd);
    const monthTests = filteredTests.filter((t) => {
      if (selectedStudentIdSet.size && !selectedStudentIdSet.has(t.studentId)) return false;
      return inRange(t.date, monthStartIso, monthEndIso);
    });
    return {
      label: monthStart.toLocaleDateString(undefined, { month: "short" }),
      avg: weightedAverageForTests(monthTests),
      count: monthTests.length
    };
  });
  const summaryDataRows = summaryMonthly.filter((row) => row.count > 0);
  const lastRow = summaryDataRows[summaryDataRows.length - 1];
  const previousRow = summaryDataRows[summaryDataRows.length - 2];
  const trendDelta = lastRow && previousRow ? lastRow.avg - previousRow.avg : null;
  const highestPoint = series.flatMap((lineSeries) => lineSeries.monthly
    .filter((row) => row.count > 0)
    .map((row) => ({ label: lineSeries.label, month: row.label, value: row.avg })))
    .sort((a, b) => b.value - a.value)[0];
  const lowestPoint = series.flatMap((lineSeries) => lineSeries.monthly
    .filter((row) => row.count > 0)
    .map((row) => ({ label: lineSeries.label, month: row.label, value: row.avg })))
    .sort((a, b) => a.value - b.value)[0];
  const averageValue = summaryDataRows.length ? avg(summaryDataRows.map((row) => row.avg)) : null;
  const deltaLabel = trendDelta === null ? "No prior month" : `${trendDelta >= 0 ? "+" : ""}${trendDelta.toFixed(1)}%`;
  const deltaClass = trendDelta === null ? "neutral" : (trendDelta >= 0 ? "positive" : "negative");
  const trendIconSvg = trendDelta === null
    ? `<svg viewBox="0 0 24 24"><path d="M5 12h14"/><path d="M15 8l4 4-4 4"/></svg>`
    : (trendDelta >= 0
      ? `<svg viewBox="0 0 24 24"><path d="M4 17l5-5 4 4 7-8"/><path d="M16 8h4v4"/></svg>`
      : `<svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg>`);
  const summaryHtml = `
    <div class="trend-summary-strip">
      <div class="trend-summary-card ${deltaClass}">
        <span class="trend-summary-icon" aria-hidden="true">${trendIconSvg}</span>
        <div><span>Overall Trend ${lastRow ? `(${escapeHtml(lastRow.label)})` : ""}</span><strong>${deltaLabel}</strong><small>${previousRow ? `vs. ${escapeHtml(previousRow.label)}` : "Need another month"}</small></div>
      </div>
      <div class="trend-summary-card positive">
        <span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v4a5 5 0 0 1-10 0V4z"/><path d="M5 5H3v2a4 4 0 0 0 4 4"/><path d="M19 5h2v2a4 4 0 0 1-4 4"/></svg></span>
        <div><span>Highest Average</span><strong>${highestPoint ? `${highestPoint.value.toFixed(1)}%` : "-"}</strong><small>${highestPoint ? `${escapeHtml(highestPoint.label)} (${escapeHtml(highestPoint.month)})` : "No grades"}</small></div>
      </div>
      <div class="trend-summary-card negative">
        <span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg></span>
        <div><span>Lowest Average</span><strong>${lowestPoint ? `${lowestPoint.value.toFixed(1)}%` : "-"}</strong><small>${lowestPoint ? `${escapeHtml(lowestPoint.label)} (${escapeHtml(lowestPoint.month)})` : "No grades"}</small></div>
      </div>
      <div class="trend-summary-card neutral">
        <span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 20V10"/><path d="M12 20V4"/><path d="M19 20v-7"/></svg></span>
        <div><span>${months.length}-Month Average</span><strong>${averageValue === null ? "-" : `${averageValue.toFixed(1)}%`}</strong><small>${selectedStudentIds.length ? `${selectedStudentIds.length} selected students` : "All Students"}</small></div>
      </div>
    </div>`;

  const legendHtml = `
    <div class="trend-legend">
      ${series.map((lineSeries) => `
        <span class="trend-legend-item">
          <span class="trend-legend-line" style="background:${lineSeries.color}"></span>
          <span>${lineSeries.label}</span>
        </span>`).join("")}
    </div>`;

  const hasData = series.some((lineSeries) => lineSeries.monthly.some((row) => row.count > 0));
  const noData = hasData ? "" : `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No grade data for selected filters</text>`;

  chartHost.innerHTML = `
    <div class="trend-chart-panel">
    <div class="trend-chart-toolbar">
      <div class="trend-view-toggle" aria-label="Grade trend chart view">
        <button type="button" data-grade-trend-view="line" class="${gradeTrendViewMode === "line" ? "active" : ""}">Line View</button>
        <button type="button" data-grade-trend-view="area" class="${gradeTrendViewMode === "area" ? "active" : ""}">Area View</button>
      </div>
      <label class="trend-data-toggle"><span>Show Data Points</span><input id="grade-trend-data-points-toggle" type="checkbox"${gradeTrendShowDataPoints ? " checked" : ""}><span aria-hidden="true"></span></label>
    </div>
    <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly grade trend line chart">
      <defs>
        <filter id="gradeTrendGlow" x="-15%" y="-40%" width="130%" height="180%"><feGaussianBlur stdDeviation="2.5" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
      </defs>
      <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      ${yTickSvg}
      ${xTickSvg}
      ${areaSvg}
      ${lineSvg}
      ${pointSvg}
      ${valueLabelSvg}
      ${monthHoverZoneSvg}
      ${noData}
      <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
      <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Average Grade (%)</text>
    </svg>
    ${legendHtml}
    </div>
    ${summaryHtml}`;
}

function renderInstructorGradeTrending() {
  const chartHost = document.getElementById("instructor-grade-trending-chart");
  if (!chartHost) return;
  const allowedStudentIds = visibleStudentIds();
  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const syEnd = toDate(sy.endDate);
  const today = toDate(todayISO());
  const effectiveEnd = syEnd < today ? syEnd : today;
  const quarterFilter = document.getElementById("instructor-grade-trend-filter-quarter")?.value || "all";
  const subjectFilter = document.getElementById("instructor-grade-trend-filter-subject")?.value || "all";
  const gradeTypeFilter = document.getElementById("instructor-grade-trend-filter-grade-type")?.value || "all";
  const selectedInstructorIds = getInstructorGradeTrendSelectedInstructorIds();
  const selectedStudentIds = getInstructorGradeTrendSelectedStudentIds();
  const selectedStudentIdSet = new Set(selectedStudentIds);
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);
  const effectiveEndIso = toISO(effectiveEnd);
  let monthStartIso = sy.startDate;
  let monthEndIso = effectiveEndIso;
  if (quarterRange && quarterFilter !== "all") {
    if (toDate(quarterRange.startDate) > toDate(monthStartIso)) monthStartIso = quarterRange.startDate;
    if (toDate(quarterRange.endDate) < toDate(monthEndIso)) monthEndIso = quarterRange.endDate;
  }
  const months = schoolYearMonths(monthStartIso, monthEndIso);
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : (quarterFilter !== "all" ? "<p class='muted'>No elapsed months in the selected quarter yet.</p>" : "<p class='muted'>No school year range set.</p>");
    return;
  }

  const filteredTests = state.tests.filter((test) => {
    if (!allowedStudentIds.has(test.studentId)) return false;
    if (selectedStudentIdSet.size && !selectedStudentIdSet.has(test.studentId)) return false;
    if (!inRange(test.date, sy.startDate, sy.endDate)) return false;
    if (quarterRange && quarterFilter !== "all" && !inRange(test.date, quarterRange.startDate, quarterRange.endDate)) return false;
    if (subjectFilter !== "all" && test.subjectId !== subjectFilter) return false;
    const gradeType = gradeTypeName(test);
    if (gradeTypeFilter !== "all" && gradeType !== gradeTypeFilter) return false;
    return !!testInstructorId(test);
  });
  const testsByInstructor = new Map();
  filteredTests.forEach((test) => {
    const instructorId = testInstructorId(test);
    if (!instructorId) return;
    if (selectedInstructorIds.length && !selectedInstructorIds.includes(instructorId)) return;
    if (!testsByInstructor.has(instructorId)) testsByInstructor.set(instructorId, []);
    testsByInstructor.get(instructorId).push(test);
  });
  const instructorIds = selectedInstructorIds.length
    ? selectedInstructorIds
    : Array.from(testsByInstructor.keys()).sort((a, b) => getInstructorName(a).localeCompare(getInstructorName(b)));
  const palette = ["#f97316", "#20a65a", "#2563eb", "#8b5cf6", "#ef4444", "#0f766e", "#a16207", "#db2777"];
  const series = instructorIds.map((instructorId, idx) => {
    const tests = testsByInstructor.get(instructorId) || [];
    const monthly = months.map((monthEntry) => {
      const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
      const monthEnd = new Date(monthEntry.year, monthEntry.month + 1, 0, 12, 0, 0);
      const monthTests = tests.filter((test) => inRange(test.date, toISO(monthStart), toISO(monthEnd)));
      return {
        label: monthStart.toLocaleDateString(undefined, { month: "short" }),
        avg: weightedAverageForTests(monthTests),
        count: monthTests.length
      };
    });
    return { id: instructorId, label: getInstructorName(instructorId), color: palette[idx % palette.length], monthly };
  });

  const plottedValues = series.flatMap((lineSeries) => lineSeries.monthly.filter((row) => row.count > 0).map((row) => row.avg));
  let yMin = 50;
  let yMax = 100;
  if (plottedValues.length) {
    const rawMin = Math.min(...plottedValues);
    const rawMax = Math.max(...plottedValues);
    yMin = Math.max(50, Math.floor((rawMin - 2) / 5) * 5);
    yMax = Math.min(100, Math.ceil((rawMax + 2) / 5) * 5);
    if (yMax - yMin < 10) {
      yMax = Math.min(100, yMin + 10);
      yMin = Math.max(50, yMax - 10);
    }
  }
  const yTickStep = (yMax - yMin) <= 30 ? 5 : 10;
  const yTicks = [];
  for (let tick = yMin; tick <= yMax; tick += yTickStep) yTicks.push(tick);
  if (yTicks[yTicks.length - 1] !== yMax) yTicks.push(yMax);
  const width = 1120;
  const height = 330;
  const margin = { top: 40, right: 34, bottom: 58, left: 74 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = months.length > 1 ? xSpan / (months.length - 1) : 0;
  const xFor = (idx) => margin.left + xPad + (xStep * idx);
  const yFor = (value) => {
    const clamped = clamp(value, yMin, yMax);
    return margin.top + ((yMax - clamped) / (yMax - yMin)) * plotH;
  };
  const baselineY = yFor(yMin);
  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick}</text></g>`;
  }).join("");
  const xTickSvg = months.map((row, idx) => {
    const monthStart = new Date(row.year, row.month, 1, 12, 0, 0);
    const x = xFor(idx);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${monthStart.toLocaleDateString(undefined, { month: "short" })}</text>`;
  }).join("");
  const lineSvg = series.map((lineSeries) => {
    let path = "";
    lineSeries.monthly.forEach((row, idx) => {
      if (row.count <= 0) return;
      const x = xFor(idx);
      const y = yFor(row.avg || 0);
      path += `${path ? "L" : "M"} ${x.toFixed(2)} ${y.toFixed(2)} `;
    });
    return path ? `<path d="${path.trim()}" class="trend-line" style="stroke:${lineSeries.color}" fill="none"></path>` : "";
  }).join("");
  const areaSvg = instructorGradeTrendViewMode === "area" ? series.map((lineSeries) => {
    const points = lineSeries.monthly.map((row, idx) => row.count > 0 ? { x: xFor(idx), y: yFor(row.avg || 0) } : null).filter(Boolean);
    if (points.length < 2) return "";
    const linePath = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    const first = points[0];
    const last = points[points.length - 1];
    return `<path d="${linePath} L ${last.x.toFixed(2)} ${baselineY.toFixed(2)} L ${first.x.toFixed(2)} ${baselineY.toFixed(2)} Z" class="trend-area" style="fill:${lineSeries.color}"></path>`;
  }).join("") : "";
  const pointSvg = instructorGradeTrendShowDataPoints ? series.flatMap((lineSeries) => lineSeries.monthly.map((row, idx) => {
    if (row.count <= 0) return "";
    const x = xFor(idx);
    const y = yFor(row.avg || 0);
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${lineSeries.color};stroke:${lineSeries.color}"><title>${lineSeries.label} ${row.label}: ${row.avg.toFixed(1)}%</title></circle>`;
  })).join("") : "";
  const valueLabelSvg = instructorGradeTrendShowDataPoints ? series.flatMap((lineSeries) => lineSeries.monthly.map((row, idx) => {
    if (row.count <= 0) return "";
    const x = xFor(idx);
    const y = clamp(yFor(row.avg || 0) - 10, margin.top + 10, height - margin.bottom - 6);
    const labelWidth = 37;
    return `<g class="trend-value-pill"><rect x="${(x - labelWidth / 2).toFixed(2)}" y="${(y - 12).toFixed(2)}" width="${labelWidth}" height="18" rx="6" style="fill:${lineSeries.color};stroke:${lineSeries.color}"></rect><text x="${x.toFixed(2)}" y="${y.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${lineSeries.color}">${(row.avg || 0).toFixed(1)}%</text></g>`;
  })).join("") : "";
  const monthHoverZoneSvg = months.map((monthEntry, monthIdx) => {
    const x = xFor(monthIdx);
    const previousX = monthIdx > 0 ? xFor(monthIdx - 1) : margin.left;
    const nextX = monthIdx < months.length - 1 ? xFor(monthIdx + 1) : width - margin.right;
    const left = monthIdx > 0 ? (previousX + x) / 2 : margin.left;
    const right = monthIdx < months.length - 1 ? (x + nextX) / 2 : width - margin.right;
    const monthLabel = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" });
    const monthTooltip = series.map((lineSeries) => {
      const row = lineSeries.monthly[monthIdx];
      if (!row || row.count <= 0) return "";
      return `${lineSeries.label} ${monthLabel}: ${row.avg.toFixed(1)}%`;
    }).filter(Boolean).join("\n");
    if (!monthTooltip) return "";
    return `<rect x="${left.toFixed(2)}" y="${margin.top}" width="${Math.max(1, right - left).toFixed(2)}" height="${plotH.toFixed(2)}" fill="transparent" pointer-events="all"><title>${escapeHtml(monthTooltip)}</title></rect>`;
  }).join("");
  const summaryRows = months.map((monthEntry) => {
    const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
    const monthEnd = new Date(monthEntry.year, monthEntry.month + 1, 0, 12, 0, 0);
    const monthTests = Array.from(testsByInstructor.values()).flat().filter((test) => inRange(test.date, toISO(monthStart), toISO(monthEnd)));
    return { label: monthStart.toLocaleDateString(undefined, { month: "short" }), avg: weightedAverageForTests(monthTests), count: monthTests.length };
  }).filter((row) => row.count > 0);
  const lastRow = summaryRows[summaryRows.length - 1];
  const previousRow = summaryRows[summaryRows.length - 2];
  const trendDelta = lastRow && previousRow ? lastRow.avg - previousRow.avg : null;
  const deltaLabel = trendDelta === null ? "No prior month" : `${trendDelta >= 0 ? "+" : ""}${trendDelta.toFixed(1)}%`;
  const deltaClass = trendDelta === null ? "neutral" : (trendDelta >= 0 ? "positive" : "negative");
  const trendIconSvg = trendDelta === null ? `<svg viewBox="0 0 24 24"><path d="M5 12h14"/><path d="M15 8l4 4-4 4"/></svg>` : (trendDelta >= 0 ? `<svg viewBox="0 0 24 24"><path d="M4 17l5-5 4 4 7-8"/><path d="M16 8h4v4"/></svg>` : `<svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg>`);
  const allPoints = series.flatMap((lineSeries) => lineSeries.monthly.filter((row) => row.count > 0).map((row) => ({ label: lineSeries.label, month: row.label, value: row.avg })));
  const highestPoint = allPoints.slice().sort((a, b) => b.value - a.value)[0];
  const lowestPoint = allPoints.slice().sort((a, b) => a.value - b.value)[0];
  const averageValue = summaryRows.length ? avg(summaryRows.map((row) => row.avg)) : null;
  const legendHtml = `<div class="trend-legend">${series.map((lineSeries) => `<span class="trend-legend-item"><span class="trend-legend-line" style="background:${lineSeries.color}"></span><span>${escapeHtml(lineSeries.label)}</span></span>`).join("")}</div>`;
  const noData = plottedValues.length ? "" : `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No grade data for selected filters</text>`;
  chartHost.innerHTML = `
    <div class="trend-chart-panel">
      <div class="trend-chart-toolbar">
        <div class="trend-view-toggle" aria-label="Instructor grade trend chart view">
          <button type="button" data-instructor-grade-trend-view="line" class="${instructorGradeTrendViewMode === "line" ? "active" : ""}">Line View</button>
          <button type="button" data-instructor-grade-trend-view="area" class="${instructorGradeTrendViewMode === "area" ? "active" : ""}">Area View</button>
        </div>
        <label class="trend-data-toggle"><span>Show Data Points</span><input id="instructor-grade-trend-data-points-toggle" type="checkbox"${instructorGradeTrendShowDataPoints ? " checked" : ""}><span aria-hidden="true"></span></label>
      </div>
      <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly instructor grade trend line chart">
        <defs><filter id="instructorGradeTrendGlow" x="-15%" y="-40%" width="130%" height="180%"><feGaussianBlur stdDeviation="2.5" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>
        <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
        <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
        ${yTickSvg}${xTickSvg}${areaSvg}${lineSvg}${pointSvg}${valueLabelSvg}${monthHoverZoneSvg}${noData}
        <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
        <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Average Grade (%)</text>
      </svg>
      ${legendHtml}
    </div>
    <div class="trend-summary-strip">
      <div class="trend-summary-card ${deltaClass}"><span class="trend-summary-icon" aria-hidden="true">${trendIconSvg}</span><div><span>Overall Trend ${lastRow ? `(${escapeHtml(lastRow.label)})` : ""}</span><strong>${deltaLabel}</strong><small>${previousRow ? `vs. ${escapeHtml(previousRow.label)}` : "Need another month"}</small></div></div>
      <div class="trend-summary-card positive"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v4a5 5 0 0 1-10 0V4z"/><path d="M5 5H3v2a4 4 0 0 0 4 4"/><path d="M19 5h2v2a4 4 0 0 1-4 4"/></svg></span><div><span>Highest Average</span><strong>${highestPoint ? `${highestPoint.value.toFixed(1)}%` : "-"}</strong><small>${highestPoint ? `${escapeHtml(highestPoint.label)} (${escapeHtml(highestPoint.month)})` : "No grades"}</small></div></div>
      <div class="trend-summary-card negative"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg></span><div><span>Lowest Average</span><strong>${lowestPoint ? `${lowestPoint.value.toFixed(1)}%` : "-"}</strong><small>${lowestPoint ? `${escapeHtml(lowestPoint.label)} (${escapeHtml(lowestPoint.month)})` : "No grades"}</small></div></div>
      <div class="trend-summary-card neutral"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 20V10"/><path d="M12 20V4"/><path d="M19 20v-7"/></svg></span><div><span>${months.length}-Month Average</span><strong>${averageValue === null ? "-" : `${averageValue.toFixed(1)}%`}</strong><small>${selectedInstructorIds.length ? `${selectedInstructorIds.length} selected instructors` : "All Instructors"}</small></div></div>
    </div>`;
}

function renderGpaTrending() {
  const chartHost = document.getElementById("gpa-trending-chart");
  if (!chartHost) return;
  const allowedStudentIds = visibleStudentIds();
  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const syEnd = toDate(sy.endDate);
  const today = toDate(todayISO());
  const effectiveEnd = syEnd < today ? syEnd : today;
  const quarterFilter = document.getElementById("gpa-trend-filter-quarter")?.value || "all";
  const subjectFilter = document.getElementById("gpa-trend-filter-subject")?.value || "all";
  const instructorFilter = document.getElementById("gpa-trend-filter-instructor")?.value || "all";
  const gradeTypeFilter = document.getElementById("gpa-trend-filter-grade-type")?.value || "all";
  const selectedStudentIds = getGpaTrendSelectedStudentIds();
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);
  const effectiveEndIso = toISO(effectiveEnd);
  let monthStartIso = sy.startDate;
  let monthEndIso = effectiveEndIso;
  if (quarterRange && quarterFilter !== "all") {
    if (toDate(quarterRange.startDate) > toDate(monthStartIso)) monthStartIso = quarterRange.startDate;
    if (toDate(quarterRange.endDate) < toDate(monthEndIso)) monthEndIso = quarterRange.endDate;
  }

  const months = schoolYearMonths(monthStartIso, monthEndIso);
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : (quarterFilter !== "all"
        ? "<p class='muted'>No elapsed months in the selected quarter yet.</p>"
        : "<p class='muted'>No school year range set.</p>");
    return;
  }

  const filteredTests = state.tests.filter((t) => {
    if (!allowedStudentIds.has(t.studentId)) return false;
    if (!inRange(t.date, sy.startDate, sy.endDate)) return false;
    if (quarterRange && quarterFilter !== "all" && !inRange(t.date, quarterRange.startDate, quarterRange.endDate)) return false;
    if (subjectFilter !== "all" && t.subjectId !== subjectFilter) return false;
    if (!testMatchesInstructorFilter(t, instructorFilter)) return false;
    const gradeType = gradeTypeName(t);
    if (gradeTypeFilter !== "all" && gradeType !== gradeTypeFilter) return false;
    return true;
  });

  const seriesBase = selectedStudentIds.length
    ? selectedStudentIds.map((studentId) => ({ id: studentId, label: getStudentName(studentId), tests: filteredTests.filter((t) => t.studentId === studentId) }))
    : (isStudentUser()
      ? visibleStudents().map((student) => ({ id: student.id, label: getStudentName(student.id), tests: filteredTests.filter((t) => t.studentId === student.id) }))
      : [{ id: "all", label: "All Students", tests: filteredTests }]);
  const palette = ["#f97316", "#20a65a", "#2563eb", "#8b5cf6", "#ef4444", "#0f766e", "#a16207", "#db2777"];

  const series = seriesBase.map((entry, idx) => {
    const monthly = months.map((monthEntry) => {
      const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
      const monthEnd = new Date(monthEntry.year, monthEntry.month + 1, 0, 12, 0, 0);
      const monthStartIso = toISO(monthStart);
      const monthEndIso = toISO(monthEnd);
      const monthTests = entry.tests.filter((t) => inRange(t.date, monthStartIso, monthEndIso));
      const averageGrade = weightedAverageForTests(monthTests);
      return {
        label: monthStart.toLocaleDateString(undefined, { month: "short" }),
        gpa: monthTests.length ? averageToGpa(averageGrade) : 0,
        count: monthTests.length
      };
    });
    return { ...entry, color: palette[idx % palette.length], monthly };
  });

  const width = 1120;
  const height = 330;
  const margin = { top: 40, right: 34, bottom: 58, left: 74 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = months.length > 1 ? xSpan / (months.length - 1) : 0;
  const xFor = (idx) => margin.left + xPad + (xStep * idx);
  const yMin = 0;
  const yMax = currentGpaMax();
  const tickCount = 4;
  const yTicks = Array.from({ length: tickCount + 1 }, (_, idx) => (yMax / tickCount) * idx);
  const yFor = (value) => {
    const clamped = clamp(value, yMin, yMax);
    return margin.top + ((yMax - clamped) / (yMax - yMin)) * plotH;
  };
  const baselineY = yFor(yMin);

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick.toFixed(1)}</text></g>`;
  }).join("");

  const xTickSvg = months.map((row, idx) => {
    const monthStart = new Date(row.year, row.month, 1, 12, 0, 0);
    const x = xFor(idx);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${monthStart.toLocaleDateString(undefined, { month: "short" })}</text>`;
  }).join("");

  const lineSvg = series.map((lineSeries) => {
    let path = "";
    lineSeries.monthly.forEach((row, idx) => {
      if (row.count <= 0) return;
      const x = xFor(idx);
      const y = yFor(row.gpa || 0);
      if (!path) path += `M ${x.toFixed(2)} ${y.toFixed(2)} `;
      else path += `L ${x.toFixed(2)} ${y.toFixed(2)} `;
    });
    return path ? `<path d="${path.trim()}" class="trend-line" style="stroke:${lineSeries.color}" fill="none"></path>` : "";
  }).join("");

  const areaSvg = gpaTrendViewMode === "area" ? series.map((lineSeries) => {
    const points = lineSeries.monthly
      .map((row, idx) => row.count > 0 ? { x: xFor(idx), y: yFor(row.gpa || 0) } : null)
      .filter(Boolean);
    if (points.length < 2) return "";
    const linePath = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    const first = points[0];
    const last = points[points.length - 1];
    return `<path d="${linePath} L ${last.x.toFixed(2)} ${baselineY.toFixed(2)} L ${first.x.toFixed(2)} ${baselineY.toFixed(2)} Z" class="trend-area" style="fill:${lineSeries.color}"></path>`;
  }).join("") : "";

  const pointSvg = gpaTrendShowDataPoints ? series.flatMap((lineSeries) => lineSeries.monthly.map((row, idx) => {
    if (row.count <= 0) return "";
    const x = xFor(idx);
    const y = yFor(row.gpa || 0);
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${lineSeries.color};stroke:${lineSeries.color}"><title>${lineSeries.label} ${row.label}: ${row.gpa.toFixed(2)} GPA</title></circle>`;
  })).join("") : "";

  const labelTop = margin.top + 10;
  const labelBottom = height - margin.bottom - 6;
  const minLabelGap = 12;
  const valueLabelParts = [];
  months.forEach((_, monthIdx) => {
    const monthLabels = series.map((lineSeries, lineIdx) => {
      const row = lineSeries.monthly[monthIdx];
      if (row.count <= 0) return null;
      const x = xFor(monthIdx);
      const y = yFor(row.gpa || 0);
      const nearTop = y <= margin.top + 16;
      const nearBottom = y >= (height - margin.bottom - 10);
      const offsetBase = ((monthIdx + lineIdx) % 2 === 0) ? -10 : 14;
      const offset = nearTop ? 22 : (nearBottom ? -10 : offsetBase);
      const preferredY = clamp(y + offset, labelTop, labelBottom);
      return {
        color: lineSeries.color,
        text: `${(row.gpa || 0).toFixed(2)}`,
        x,
        preferredY
      };
    }).filter(Boolean).sort((a, b) => a.preferredY - b.preferredY);

    for (let i = 1; i < monthLabels.length; i += 1) {
      if (monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
        monthLabels[i].preferredY = monthLabels[i - 1].preferredY + minLabelGap;
      }
    }
    const overflow = monthLabels.length ? monthLabels[monthLabels.length - 1].preferredY - labelBottom : 0;
    if (overflow > 0) {
      for (let i = monthLabels.length - 1; i >= 0; i -= 1) {
        monthLabels[i].preferredY -= overflow;
        if (i > 0 && monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
          monthLabels[i - 1].preferredY = monthLabels[i].preferredY - minLabelGap;
        }
      }
    }
    monthLabels.forEach((label) => {
      label.preferredY = clamp(label.preferredY, labelTop, labelBottom);
      const labelWidth = 34;
      valueLabelParts.push(`<g class="trend-value-pill"><rect x="${(label.x - labelWidth / 2).toFixed(2)}" y="${(label.preferredY - 12).toFixed(2)}" width="${labelWidth}" height="18" rx="6" style="fill:${label.color};stroke:${label.color}"></rect><text x="${label.x.toFixed(2)}" y="${label.preferredY.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${label.color}">${label.text}</text></g>`);
    });
  });
  const valueLabelSvg = gpaTrendShowDataPoints ? valueLabelParts.join("") : "";

  const monthHoverZoneSvg = months.map((monthEntry, monthIdx) => {
    const x = xFor(monthIdx);
    const previousX = monthIdx > 0 ? xFor(monthIdx - 1) : margin.left;
    const nextX = monthIdx < months.length - 1 ? xFor(monthIdx + 1) : width - margin.right;
    const left = monthIdx > 0 ? (previousX + x) / 2 : margin.left;
    const right = monthIdx < months.length - 1 ? (x + nextX) / 2 : width - margin.right;
    const monthLabel = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" });
    const monthTooltip = series.map((lineSeries) => {
      const row = lineSeries.monthly[monthIdx];
      if (!row || row.count <= 0) return "";
      return `${lineSeries.label} ${monthLabel}: ${row.gpa.toFixed(2)} GPA`;
    }).filter(Boolean).join("\n");
    if (!monthTooltip) return "";
    return `<rect x="${left.toFixed(2)}" y="${margin.top}" width="${Math.max(1, right - left).toFixed(2)}" height="${plotH.toFixed(2)}" fill="transparent" pointer-events="all"><title>${escapeHtml(monthTooltip)}</title></rect>`;
  }).join("");

  const legendHtml = `
    <div class="trend-legend">
      ${series.map((lineSeries) => `
        <span class="trend-legend-item">
          <span class="trend-legend-line" style="background:${lineSeries.color}"></span>
          <span>${escapeHtml(lineSeries.label)}</span>
        </span>`).join("")}
    </div>`;

  const hasData = series.some((lineSeries) => lineSeries.monthly.some((row) => row.count > 0));
  const noData = hasData ? "" : `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No grade data for selected filters</text>`;

  const selectedStudentIdSet = new Set(selectedStudentIds);
  const summaryMonthly = months.map((monthEntry) => {
    const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
    const monthEnd = new Date(monthEntry.year, monthEntry.month + 1, 0, 12, 0, 0);
    const monthStartIso = toISO(monthStart);
    const monthEndIso = toISO(monthEnd);
    const monthTests = filteredTests.filter((t) => {
      if (selectedStudentIdSet.size && !selectedStudentIdSet.has(t.studentId)) return false;
      return inRange(t.date, monthStartIso, monthEndIso);
    });
    const averageGrade = weightedAverageForTests(monthTests);
    return {
      label: monthStart.toLocaleDateString(undefined, { month: "short" }),
      gpa: monthTests.length ? averageToGpa(averageGrade) : 0,
      count: monthTests.length
    };
  });
  const summaryDataRows = summaryMonthly.filter((row) => row.count > 0);
  const lastRow = summaryDataRows[summaryDataRows.length - 1];
  const previousRow = summaryDataRows[summaryDataRows.length - 2];
  const trendDelta = lastRow && previousRow ? lastRow.gpa - previousRow.gpa : null;
  const highestPoint = series.flatMap((lineSeries) => lineSeries.monthly
    .filter((row) => row.count > 0)
    .map((row) => ({ label: lineSeries.label, month: row.label, value: row.gpa })))
    .sort((a, b) => b.value - a.value)[0];
  const lowestPoint = series.flatMap((lineSeries) => lineSeries.monthly
    .filter((row) => row.count > 0)
    .map((row) => ({ label: lineSeries.label, month: row.label, value: row.gpa })))
    .sort((a, b) => a.value - b.value)[0];
  const averageValue = summaryDataRows.length ? avg(summaryDataRows.map((row) => row.gpa)) : null;
  const deltaLabel = trendDelta === null ? "No prior month" : `${trendDelta >= 0 ? "+" : ""}${trendDelta.toFixed(2)}`;
  const deltaClass = trendDelta === null ? "neutral" : (trendDelta >= 0 ? "positive" : "negative");
  const trendIconSvg = trendDelta === null
    ? `<svg viewBox="0 0 24 24"><path d="M5 12h14"/><path d="M15 8l4 4-4 4"/></svg>`
    : (trendDelta >= 0
      ? `<svg viewBox="0 0 24 24"><path d="M4 17l5-5 4 4 7-8"/><path d="M16 8h4v4"/></svg>`
      : `<svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg>`);
  const summaryHtml = `
    <div class="trend-summary-strip">
      <div class="trend-summary-card ${deltaClass}">
        <span class="trend-summary-icon" aria-hidden="true">${trendIconSvg}</span>
        <div><span>Overall Trend ${lastRow ? `(${escapeHtml(lastRow.label)})` : ""}</span><strong>${deltaLabel}</strong><small>${previousRow ? `vs. ${escapeHtml(previousRow.label)}` : "Need another month"}</small></div>
      </div>
      <div class="trend-summary-card positive">
        <span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v4a5 5 0 0 1-10 0V4z"/><path d="M5 5H3v2a4 4 0 0 0 4 4"/><path d="M19 5h2v2a4 4 0 0 1-4 4"/></svg></span>
        <div><span>Highest GPA</span><strong>${highestPoint ? highestPoint.value.toFixed(2) : "-"}</strong><small>${highestPoint ? `${escapeHtml(highestPoint.label)} (${escapeHtml(highestPoint.month)})` : "No grades"}</small></div>
      </div>
      <div class="trend-summary-card negative">
        <span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg></span>
        <div><span>Lowest GPA</span><strong>${lowestPoint ? lowestPoint.value.toFixed(2) : "-"}</strong><small>${lowestPoint ? `${escapeHtml(lowestPoint.label)} (${escapeHtml(lowestPoint.month)})` : "No grades"}</small></div>
      </div>
      <div class="trend-summary-card neutral">
        <span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 20V10"/><path d="M12 20V4"/><path d="M19 20v-7"/></svg></span>
        <div><span>${months.length}-Month Average</span><strong>${averageValue === null ? "-" : averageValue.toFixed(2)}</strong><small>${selectedStudentIds.length ? `${selectedStudentIds.length} selected students` : "All Students"}</small></div>
      </div>
    </div>`;

  chartHost.innerHTML = `
    <div class="trend-chart-panel">
      <div class="trend-chart-toolbar">
        <div class="trend-view-toggle" aria-label="GPA trend chart view">
          <button type="button" data-gpa-trend-view="line" class="${gpaTrendViewMode === "line" ? "active" : ""}">Line View</button>
          <button type="button" data-gpa-trend-view="area" class="${gpaTrendViewMode === "area" ? "active" : ""}">Area View</button>
        </div>
        <label class="trend-data-toggle"><span>Show Data Points</span><input id="gpa-trend-data-points-toggle" type="checkbox"${gpaTrendShowDataPoints ? " checked" : ""}><span aria-hidden="true"></span></label>
      </div>
    <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly GPA trend line chart">
      <defs>
        <filter id="gradeTrendGlow" x="-15%" y="-40%" width="130%" height="180%"><feGaussianBlur stdDeviation="2.5" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
      </defs>
      <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      ${yTickSvg}
      ${xTickSvg}
      ${areaSvg}
      ${lineSvg}
      ${pointSvg}
      ${valueLabelSvg}
      ${monthHoverZoneSvg}
      ${noData}
      <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
      <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">GPA (${currentGpaMax().toFixed(1)} scale)</text>
    </svg>
    ${legendHtml}
    </div>
    ${summaryHtml}`;
}

function renderInstructionHoursTrending() {
  const renderStartedAt = performanceDiagnosticsEnabled() ? performanceNow() : 0;
  const chartHost = document.getElementById("instruction-hours-trending-chart");
  if (!chartHost) return;

  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const syEnd = toDate(sy.endDate);
  const today = toDate(todayISO());
  const effectiveEnd = syEnd < today ? syEnd : today;

  const quarterFilter = document.getElementById("instruction-hours-trend-filter-quarter")?.value || "all";
  const subjectFilter = document.getElementById("instruction-hours-trend-filter-subject")?.value || "all";
  const instructorFilter = document.getElementById("instruction-hours-trend-filter-instructor")?.value || "all";
  const selectedStudentIds = getInstructionHoursTrendSelectedStudentIds();
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);
  const effectiveEndIso = toISO(effectiveEnd);
  let monthStartIso = sy.startDate;
  let monthEndIso = effectiveEndIso;
  if (quarterRange && quarterFilter !== "all") {
    if (toDate(quarterRange.startDate) > toDate(monthStartIso)) monthStartIso = quarterRange.startDate;
    if (toDate(quarterRange.endDate) < toDate(monthEndIso)) monthEndIso = quarterRange.endDate;
  }

  const months = schoolYearMonths(monthStartIso, monthEndIso);
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : (quarterFilter !== "all"
        ? "<p class='muted'>No elapsed months in the selected quarter yet.</p>"
        : "<p class='muted'>No school year range set.</p>");
    if (renderStartedAt) {
      recordPerformanceMetric("dashboard.renderInstructionHoursTrending", performanceNow() - renderStartedAt, {
        months: 0,
        series: 0
      });
    }
    return;
  }

  const palette = ["#875422", "#2f6f3e", "#1f4d7a", "#8a3434", "#7c5f1f", "#5a3a88", "#35736f", "#9b4d2f"];
  const monthlySeries = buildComplianceMonthlySeries(selectedStudentIds, {
    quarterFilter,
    subjectFilter,
    instructorFilter
  });
  if (!monthlySeries.series.length) {
    chartHost.innerHTML = "<p class='muted'>No visible students for the current filter.</p>";
    if (renderStartedAt) {
      recordPerformanceMetric("dashboard.renderInstructionHoursTrending", performanceNow() - renderStartedAt, {
        months: monthlySeries.months.length,
        series: 0
      });
    }
    return;
  }
  const series = (!selectedStudentIds.length && !isStudentUser())
    ? [{
      id: "all",
      label: "All Students",
      color: palette[0],
      monthly: monthlySeries.months.map((monthEntry, monthIdx) => {
        const monthStart = new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0);
        return {
          label: monthStart.toLocaleDateString(undefined, { month: "short" }),
          hours: monthlySeries.series.reduce((sum, entry) => sum + Number(entry.monthly[monthIdx]?.hours || 0), 0)
        };
      })
    }]
    : monthlySeries.series.map((entry, idx) => ({
      ...entry,
      color: entry.color || palette[idx % palette.length],
      monthly: entry.monthly.map((row) => ({
        label: row.label,
        hours: Number(row.hours || 0)
      }))
    }));

  const plottedValues = series.flatMap((lineSeries) => lineSeries.monthly.map((row) => row.hours));
  const rawMax = plottedValues.length ? Math.max(...plottedValues) : 0;
  const yMax = rawMax > 0 ? Math.ceil((rawMax + Math.max(2, rawMax * 0.08)) / 5) * 5 : 10;
  const yTickStep = niceTickStep(yMax, 6);
  const yTicks = [];
  for (let tick = 0; tick <= yMax; tick += yTickStep) yTicks.push(tick);
  if (yTicks[yTicks.length - 1] !== yMax) yTicks.push(yMax);

  const width = 960;
  const height = 260;
  const margin = { top: 62, right: 20, bottom: 48, left: 52 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = months.length > 1 ? xSpan / (months.length - 1) : 0;
  const xFor = (idx) => margin.left + xPad + (xStep * idx);
  const yFor = (value) => {
    const clamped = clamp(value, 0, yMax);
    return margin.top + ((yMax - clamped) / Math.max(yMax, 1)) * plotH;
  };

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick.toFixed(1)}</text></g>`;
  }).join("");

  const xTickSvg = months.map((row, idx) => {
    const monthStart = new Date(row.year, row.month, 1, 12, 0, 0);
    const x = xFor(idx);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${monthStart.toLocaleDateString(undefined, { month: "short" })}</text>`;
  }).join("");

  const lineSvg = series.map((lineSeries) => {
    let path = "";
    lineSeries.monthly.forEach((row, idx) => {
      const x = xFor(idx);
      const y = yFor(row.hours || 0);
      if (!path) path += `M ${x.toFixed(2)} ${y.toFixed(2)} `;
      else path += `L ${x.toFixed(2)} ${y.toFixed(2)} `;
    });
    return `<path d="${path.trim()}" class="trend-line" style="stroke:${lineSeries.color}" fill="none"></path>`;
  }).join("");

  const pointSvg = series.flatMap((lineSeries) => lineSeries.monthly.map((row, idx) => {
    const x = xFor(idx);
    const y = yFor(row.hours || 0);
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${lineSeries.color};stroke:${lineSeries.color}"><title>${lineSeries.label} ${row.label}: ${row.hours.toFixed(1)} hours</title></circle>`;
  })).join("");

  const labelTop = margin.top + 10;
  const labelBottom = height - margin.bottom - 6;
  const minLabelGap = 12;
  const valueLabelParts = [];
  months.forEach((_, monthIdx) => {
    const monthLabels = series.map((lineSeries, lineIdx) => {
      const row = lineSeries.monthly[monthIdx];
      const x = xFor(monthIdx);
      const y = yFor(row.hours || 0);
      const nearTop = y <= margin.top + 16;
      const nearBottom = y >= (height - margin.bottom - 10);
      const offsetBase = ((monthIdx + lineIdx) % 2 === 0) ? -10 : 14;
      const offset = nearTop ? 22 : (nearBottom ? -10 : offsetBase);
      const preferredY = clamp(y + offset, labelTop, labelBottom);
      return {
        color: lineSeries.color,
        text: `${(row.hours || 0).toFixed(1)}`,
        x,
        preferredY
      };
    }).sort((a, b) => a.preferredY - b.preferredY);

    for (let i = 1; i < monthLabels.length; i += 1) {
      if (monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
        monthLabels[i].preferredY = monthLabels[i - 1].preferredY + minLabelGap;
      }
    }
    const overflow = monthLabels.length ? monthLabels[monthLabels.length - 1].preferredY - labelBottom : 0;
    if (overflow > 0) {
      for (let i = monthLabels.length - 1; i >= 0; i -= 1) {
        monthLabels[i].preferredY -= overflow;
        if (i > 0 && monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
          monthLabels[i - 1].preferredY = monthLabels[i].preferredY - minLabelGap;
        }
      }
    }
    monthLabels.forEach((label) => {
      label.preferredY = clamp(label.preferredY, labelTop, labelBottom);
      valueLabelParts.push(`<text x="${label.x.toFixed(2)}" y="${label.preferredY.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${label.color}">${label.text}</text>`);
    });
  });
  const valueLabelSvg = valueLabelParts.join("");

  const legendHtml = `
    <div class="trend-legend">
      ${series.map((lineSeries) => `
        <span class="trend-legend-item">
          <span class="trend-legend-line" style="background:${lineSeries.color}"></span>
          <span>${lineSeries.label}</span>
        </span>`).join("")}
    </div>`;

  const hasData = series.some((lineSeries) => lineSeries.monthly.some((row) => row.hours > 0));
  const noData = hasData ? "" : `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No instructional hours for selected filters</text>`;

  chartHost.innerHTML = `
    <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly instructional hours trend line chart">
      <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      ${yTickSvg}
      ${xTickSvg}
      ${lineSvg}
      ${pointSvg}
      ${valueLabelSvg}
      ${noData}
      <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
      <text x="12" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 12 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Instruction Hours</text>
    </svg>
    ${legendHtml}`;
  if (renderStartedAt) {
    recordPerformanceMetric("dashboard.renderInstructionHoursTrending", performanceNow() - renderStartedAt, {
      months: months.length,
      series: series.length
    });
  }
}

function renderInstructionDaysTrending() {
  const chartHost = document.getElementById("instruction-days-trending-chart");
  if (!chartHost) return;
  const selectedStudentIds = getInstructionDaysTrendSelectedStudentIds();
  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const today = toDate(todayISO());
  const { months, series } = buildComplianceMonthlySeries(selectedStudentIds, {
    quarterFilter: document.getElementById("instruction-days-trend-filter-quarter")?.value || "all",
    subjectFilter: document.getElementById("instruction-days-trend-filter-subject")?.value || "all",
    instructorFilter: document.getElementById("instruction-days-trend-filter-instructor")?.value || "all"
  });
  if (!months.length) {
    chartHost.innerHTML = syStart > today ? "<p class='muted'>School year has not started yet.</p>" : "<p class='muted'>No school year range set.</p>";
    return;
  }
  if (!series.length) {
    chartHost.innerHTML = "<p class='muted'>No visible students for the current filter.</p>";
    return;
  }
  const monthlyRows = months.map((monthEntry, monthIdx) => ({
    label: new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" }),
    values: series.map((studentSeries) => Number(studentSeries.monthly[monthIdx]?.days || 0))
  }));
  const plottedValues = monthlyRows.flatMap((row) => row.values);
  const rawMax = plottedValues.length ? Math.max(...plottedValues) : 0;
  const yTickStep = rawMax <= 10 ? 1 : (rawMax <= 30 ? 5 : 10);
  const yMax = rawMax > 0 ? Math.ceil((rawMax + yTickStep) / yTickStep) * yTickStep : 10;
  const yTicks = [];
  for (let tick = 0; tick <= yMax; tick += yTickStep) yTicks.push(tick);
  const width = 960;
  const height = 260;
  const margin = { top: 62, right: 20, bottom: 48, left: 52 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = monthlyRows.length > 1 ? xSpan / (monthlyRows.length - 1) : 0;
  const xFor = (idx) => margin.left + xPad + (xStep * idx);
  const yFor = (value) => margin.top + ((yMax - clamp(Number(value || 0), 0, yMax)) / Math.max(yMax, 1)) * plotH;
  const palette = ["#875422", "#2f6f3e", "#1f4d7a", "#8a3434", "#7c5f1f", "#5a3a88", "#35736f", "#9b4d2f"];
  const colors = series.map((studentSeries, idx) => studentSeries.color || palette[idx % palette.length]);
  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick.toFixed(0)}</text></g>`;
  }).join("");
  const xTickSvg = monthlyRows.map((row, idx) => `<text x="${xFor(idx).toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${escapeHtml(row.label)}</text>`).join("");
  const lineSvg = series.map((studentSeries, studentIdx) => {
    let path = "";
    monthlyRows.forEach((row, idx) => {
      const value = Number(row.values[studentIdx] || 0);
      const x = xFor(idx);
      const y = yFor(value);
      if (!path) path += `M ${x.toFixed(2)} ${y.toFixed(2)} `;
      else path += `L ${x.toFixed(2)} ${y.toFixed(2)} `;
    });
    return `<path d="${path.trim()}" class="trend-line" style="stroke:${colors[studentIdx]}" fill="none"></path>`;
  }).join("");
  const formatDays = (value) => Number(value || 0).toFixed(Number(value || 0) % 1 === 0 ? 0 : 1);
  const pointSvg = series.flatMap((studentSeries, studentIdx) => monthlyRows.map((row, idx) => {
    const value = Number(row.values[studentIdx] || 0);
    const x = xFor(idx);
    const y = yFor(value);
    const monthTooltip = series.map((entry, entryIdx) => {
      const monthValue = Number(row.values[entryIdx] || 0);
      return `${entry.label} ${row.label}: ${formatDays(monthValue)} days`;
    }).join("\n");
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${colors[studentIdx]};stroke:${colors[studentIdx]}"><title>${escapeHtml(monthTooltip)}</title></circle>`;
  })).join("");
  const monthHoverZoneSvg = monthlyRows.map((row, idx) => {
    const x = xFor(idx);
    const previousX = idx > 0 ? xFor(idx - 1) : margin.left;
    const nextX = idx < monthlyRows.length - 1 ? xFor(idx + 1) : width - margin.right;
    const left = idx > 0 ? (previousX + x) / 2 : margin.left;
    const right = idx < monthlyRows.length - 1 ? (x + nextX) / 2 : width - margin.right;
    const monthTooltip = series.map((entry, entryIdx) => {
      const monthValue = Number(row.values[entryIdx] || 0);
      return `${entry.label} ${row.label}: ${formatDays(monthValue)} days`;
    }).join("\n");
    return `<rect x="${left.toFixed(2)}" y="${margin.top}" width="${Math.max(1, right - left).toFixed(2)}" height="${plotH.toFixed(2)}" fill="transparent" pointer-events="all"><title>${escapeHtml(monthTooltip)}</title></rect>`;
  }).join("");
  const labelTop = margin.top + 10;
  const labelBottom = height - margin.bottom - 6;
  const minLabelGap = 12;
  const valueLabelParts = [];
  monthlyRows.forEach((_, monthIdx) => {
    const monthLabels = series.map((studentSeries, studentIdx) => {
      const value = Number(studentSeries.monthly[monthIdx]?.days || 0);
      if (value <= 0) return null;
      const x = xFor(monthIdx);
      const y = yFor(value);
      const nearTop = y <= margin.top + 16;
      const nearBottom = y >= (height - margin.bottom - 10);
      const offsetBase = ((monthIdx + studentIdx) % 2 === 0) ? -10 : 14;
      const offset = nearTop ? 22 : (nearBottom ? -10 : offsetBase);
      return {
        color: colors[studentIdx],
        text: formatDays(value),
        x,
        preferredY: clamp(y + offset, labelTop, labelBottom)
      };
    }).filter(Boolean).sort((a, b) => a.preferredY - b.preferredY);

    for (let i = 1; i < monthLabels.length; i += 1) {
      if (monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
        monthLabels[i].preferredY = monthLabels[i - 1].preferredY + minLabelGap;
      }
    }
    const overflow = monthLabels.length ? monthLabels[monthLabels.length - 1].preferredY - labelBottom : 0;
    if (overflow > 0) {
      for (let i = monthLabels.length - 1; i >= 0; i -= 1) {
        monthLabels[i].preferredY -= overflow;
        if (i > 0 && monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
          monthLabels[i - 1].preferredY = monthLabels[i].preferredY - minLabelGap;
        }
      }
    }
    monthLabels.forEach((label) => {
      label.preferredY = clamp(label.preferredY, labelTop, labelBottom);
      const labelWidth = 37;
      valueLabelParts.push(`<g class="trend-value-pill"><rect x="${(label.x - labelWidth / 2).toFixed(2)}" y="${(label.preferredY - 12).toFixed(2)}" width="${labelWidth}" height="18" rx="6" style="fill:${label.color};stroke:${label.color}"></rect><text x="${label.x.toFixed(2)}" y="${label.preferredY.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${label.color}">${label.text}</text></g>`);
    });
  });
  const valueLabelSvg = valueLabelParts.join("");
  const legendHtml = `<div class="trend-legend">${series.map((studentSeries, idx) => `<span class="trend-legend-item"><span class="trend-legend-line" style="background:${colors[idx]}"></span><span>${escapeHtml(studentSeries.label)}</span></span>`).join("")}</div>`;
  const hasData = monthlyRows.some((row) => row.values.some((value) => value > 0));
  const noData = hasData ? "" : `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No instructional days for selected filters</text>`;
  chartHost.innerHTML = `
    <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly instructional days trend line chart">
      <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      ${yTickSvg}
      ${xTickSvg}
      ${lineSvg}
      ${pointSvg}
      ${valueLabelSvg}
      ${monthHoverZoneSvg}
      ${noData}
      <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
      <text x="12" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 12 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Instruction Days</text>
    </svg>
    ${legendHtml}`;
}

function complianceMonthlySeriesCacheKey(selectedStudentIds = [], options = {}) {
  const selectedIds = Array.isArray(selectedStudentIds)
    ? selectedStudentIds.map((studentId) => String(studentId || "").trim()).filter(Boolean).sort()
    : [];
  const visibleIds = Array.from(visibleStudentIds()).sort();
  const quarterSignature = state.settings.quarters
    .map((quarter) => `${quarter.name}:${quarter.startDate}:${quarter.endDate}`)
    .join(",");
  const schoolYear = currentSchoolYear();
  return [
    schoolYear?.id || state.settings.currentSchoolYearId || "",
    state.settings.schoolYear?.startDate || "",
    state.settings.schoolYear?.endDate || "",
    todayISO(),
    selectedIds.join(","),
    visibleIds.join(","),
    options.quarterFilter || "all",
    options.subjectFilter || "all",
    options.instructorFilter || "all",
    quarterSignature,
    attendanceDataVersion,
    instructionActualsDataVersion,
    flexBlocksDataVersion
  ].join("||");
}

function buildComplianceMonthlySeries(selectedStudentIds = [], options = {}) {
  const cacheKey = complianceMonthlySeriesCacheKey(selectedStudentIds, options);
  const cached = complianceMonthlySeriesCache.get(cacheKey);
  if (cached) {
    if (performanceDiagnosticsEnabled()) {
      recordPerformanceMetric("dashboard.buildComplianceMonthlySeries", 0, {
        months: cached.months.length,
        students: cached.series.length,
        rows: cached.series.reduce((sum, entry) => sum + entry.monthly.length, 0),
        cached: true
      });
    }
    return cached;
  }
  const seriesStartedAt = performanceDiagnosticsEnabled() ? performanceNow() : 0;
  const allowedStudentIds = visibleStudentIds();
  const sy = state.settings.schoolYear;
  const syEnd = toDate(sy.endDate);
  const today = toDate(todayISO());
  const effectiveEnd = syEnd < today ? syEnd : today;
  const quarterFilter = options.quarterFilter || "all";
  const subjectFilter = options.subjectFilter || "all";
  const instructorFilter = options.instructorFilter || "all";
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter) || null;
  let monthStartIso = sy.startDate;
  let monthEndIso = toISO(effectiveEnd);
  if (quarterRange && quarterFilter !== "all") {
    if (toDate(quarterRange.startDate) > toDate(monthStartIso)) monthStartIso = quarterRange.startDate;
    if (toDate(quarterRange.endDate) < toDate(monthEndIso)) monthEndIso = quarterRange.endDate;
  }
  const filteredMonths = schoolYearMonths(monthStartIso, monthEndIso);
  const targetStudentIds = selectedStudentIds.length
    ? selectedStudentIds.filter((studentId) => allowedStudentIds.has(studentId))
    : Array.from(allowedStudentIds);
  if (!filteredMonths.length || !targetStudentIds.length) {
    const emptySeries = { months: filteredMonths, series: [] };
    complianceMonthlySeriesCache.set(cacheKey, emptySeries);
    if (seriesStartedAt) {
      recordPerformanceMetric("dashboard.buildComplianceMonthlySeries", performanceNow() - seriesStartedAt, {
        months: filteredMonths.length,
        students: targetStudentIds.length,
        rows: 0,
        cached: false
      });
    }
    return emptySeries;
  }

  const targetStudentIdSet = new Set(targetStudentIds);
  const attendanceByStudentDate = new Map();
  state.attendance.forEach((record) => {
    if (!allowedStudentIds.has(record.studentId)) return;
    const key = `${record.studentId}||${record.date}`;
    if (!attendanceByStudentDate.has(key)) {
      attendanceByStudentDate.set(key, !!record.present);
      return;
    }
    if (attendanceByStudentDate.get(key) && !record.present) attendanceByStudentDate.set(key, false);
  });

  const monthlyHours = new Map(targetStudentIds.map((studentId) => [studentId, new Map(filteredMonths.map((month) => [`${month.year}-${month.month}`, 0]))]));
  const monthlyDays = new Map(targetStudentIds.map((studentId) => [studentId, new Map(filteredMonths.map((month) => [`${month.year}-${month.month}`, new Set()]))]));
  const cursor = new Date(toDate(monthStartIso));
  while (cursor <= effectiveEnd && toISO(cursor) <= monthEndIso) {
    const dateKey = toISO(cursor);
    const blocksByStudent = dashboardDailyScheduledBlocks(dateKey, targetStudentIds);
    Array.from(blocksByStudent.values()).flat().forEach((block) => {
      if (block.type !== "instruction" || !targetStudentIdSet.has(block.studentId)) return;
      if (quarterRange && quarterFilter !== "all" && !inRange(dateKey, quarterRange.startDate, quarterRange.endDate)) return;
      if (subjectFilter !== "all" && (block.subjectId || getCourse(block.courseId)?.subjectId) !== subjectFilter) return;
      if (attendanceByStudentDate.get(`${block.studentId}||${dateKey}`) !== true) return;
      if (!instructionMatchesInstructorFilter(block.studentId, block.courseId, dateKey, instructorFilter)) return;
      if (!instructionCountsTowardCompletedHours(block.studentId, block.courseId, dateKey)) return;
      const hours = Number(block.actualMinutes || 0) / 60;
      if (!(hours > 0)) return;
      const monthKey = `${cursor.getFullYear()}-${cursor.getMonth()}`;
      monthlyHours.get(block.studentId)?.set(monthKey, (monthlyHours.get(block.studentId)?.get(monthKey) || 0) + hours);
      monthlyDays.get(block.studentId)?.get(monthKey)?.add(dateKey);
    });
    cursor.setDate(cursor.getDate() + 1);
  }

  const palette = ["#875422", "#2f6f3e", "#1f4d7a", "#8a3434", "#7c5f1f", "#5a3a88", "#35736f", "#9b4d2f"];
  const series = targetStudentIds.map((studentId, idx) => ({
    id: studentId,
    label: getStudentName(studentId),
    color: palette[idx % palette.length],
    monthly: filteredMonths.map((monthEntry) => ({
      label: new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" }),
      hours: Number(monthlyHours.get(studentId)?.get(`${monthEntry.year}-${monthEntry.month}`) || 0),
      days: Number(monthlyDays.get(studentId)?.get(`${monthEntry.year}-${monthEntry.month}`)?.size || 0)
    }))
  }));
  const result = { months: filteredMonths, series };
  complianceMonthlySeriesCache.set(cacheKey, result);
  if (seriesStartedAt) {
    recordPerformanceMetric("dashboard.buildComplianceMonthlySeries", performanceNow() - seriesStartedAt, {
      months: filteredMonths.length,
      students: targetStudentIds.length,
      rows: series.reduce((sum, entry) => sum + entry.monthly.length, 0),
      cached: false
    });
  }
  return result;
}

function renderComplianceMonthlyBarChart(chartHostId, valueKey, emptyMessage, ariaLabel, yAxisTitle, selectedStudentIds = [], options = {}) {
  const chartHost = document.getElementById(chartHostId);
  if (!chartHost) return;
  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const today = toDate(todayISO());
  const { months, series } = buildComplianceMonthlySeries(selectedStudentIds, options);
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : "<p class='muted'>No school year range set.</p>";
    return;
  }
  if (!series.length) {
    chartHost.innerHTML = "<p class='muted'>No visible students for the current filter.</p>";
    return;
  }

  const plottedValues = series.flatMap((entry) => entry.monthly.map((row) => Number(row[valueKey] || 0)));
  const rawMax = plottedValues.length ? Math.max(...plottedValues) : 0;
  const yMax = rawMax > 0 ? Math.ceil((rawMax + Math.max(2, rawMax * 0.08)) / 5) * 5 : 10;
  const yTickStep = yMax <= 20 ? 2 : (yMax <= 60 ? 5 : (yMax <= 120 ? 10 : 20));
  const yTicks = [];
  for (let tick = 0; tick <= yMax; tick += yTickStep) yTicks.push(tick);
  if (yTicks[yTicks.length - 1] !== yMax) yTicks.push(yMax);

  const width = 960;
  const height = 320;
  const margin = { top: 42, right: 20, bottom: 52, left: 52 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const groupGap = 18;
  const monthSlot = plotW / Math.max(months.length, 1);
  const groupWidth = Math.max(24, monthSlot - groupGap);
  const barGap = 6;
  const barWidth = Math.max(10, (groupWidth - (Math.max(series.length - 1, 0) * barGap)) / Math.max(series.length, 1));
  const totalGroupWidth = (series.length * barWidth) + (Math.max(series.length - 1, 0) * barGap);
  const xForGroup = (idx) => margin.left + (monthSlot * idx) + ((monthSlot - totalGroupWidth) / 2);
  const yFor = (value) => {
    const clamped = clamp(value, 0, yMax);
    return margin.top + ((yMax - clamped) / Math.max(yMax, 1)) * plotH;
  };

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick.toFixed(1)}</text></g>`;
  }).join("");

  const xTickSvg = months.map((row, idx) => {
    const monthStart = new Date(row.year, row.month, 1, 12, 0, 0);
    const x = xForGroup(idx) + (totalGroupWidth / 2);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${monthStart.toLocaleDateString(undefined, { month: "short" })}</text>`;
  }).join("");

  const barSvg = series.flatMap((studentSeries, seriesIdx) => studentSeries.monthly.map((row, monthIdx) => {
    const x = xForGroup(monthIdx) + (seriesIdx * (barWidth + barGap));
    const value = Number(row[valueKey] || 0);
    const y = yFor(value);
    const barHeight = Math.max(0, height - margin.bottom - y);
    const unitLabel = valueKey === "days" ? `${value.toFixed(1)} days` : `${value.toFixed(1)} hours`;
    return `<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${barWidth.toFixed(2)}" height="${barHeight.toFixed(2)}" rx="3" ry="3" style="fill:${studentSeries.color}"><title>${studentSeries.label} ${row.label}: ${unitLabel}</title></rect>`;
  })).join("");

  const legendHtml = `
    <div class="trend-legend">
      ${series.map((studentSeries) => `
        <span class="trend-legend-item">
          <span class="volume-legend-box" style="background:${studentSeries.color}"></span>
          <span>${studentSeries.label}</span>
        </span>`).join("")}
    </div>`;

  const hasData = series.some((studentSeries) => studentSeries.monthly.some((row) => Number(row[valueKey] || 0) > 0));
  const noData = hasData ? "" : `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">${escapeHtml(emptyMessage)}</text>`;

  chartHost.innerHTML = `
    <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="${escapeHtml(ariaLabel)}">
      <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
      ${yTickSvg}
      ${xTickSvg}
      ${barSvg}
      ${noData}
      <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
      <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">${escapeHtml(yAxisTitle)}</text>
    </svg>
    ${legendHtml}`;
}

function renderComplianceHoursMonthlyChart() {
  renderComplianceHoursMonthlyModernChart();
}

function renderComplianceHoursMonthlyModernChart() {
  const renderStartedAt = performanceDiagnosticsEnabled() ? performanceNow() : 0;
  const chartHost = document.getElementById("compliance-hours-monthly-chart");
  if (!chartHost) return;
  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const today = toDate(todayISO());
  const selectedStudentIds = getComplianceHoursSelectedStudentIds();
  const { months, series } = buildComplianceMonthlySeries(selectedStudentIds, {
    quarterFilter: document.getElementById("compliance-hours-filter-quarter")?.value || "all",
    subjectFilter: document.getElementById("compliance-hours-filter-subject")?.value || "all",
    instructorFilter: document.getElementById("compliance-hours-filter-instructor")?.value || "all"
  });
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : "<p class='muted'>No school year range set.</p>";
    if (renderStartedAt) {
      recordPerformanceMetric("dashboard.renderComplianceHoursMonthlyChart", performanceNow() - renderStartedAt, {
        months: 0,
        series: 0
      });
    }
    return;
  }
  if (!series.length) {
    chartHost.innerHTML = "<p class='muted'>No visible students for the current filter.</p>";
    if (renderStartedAt) {
      recordPerformanceMetric("dashboard.renderComplianceHoursMonthlyChart", performanceNow() - renderStartedAt, {
        months: months.length,
        series: 0
      });
    }
    return;
  }

  const monthlyRows = months.map((monthEntry, monthIdx) => ({
    label: new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" }),
    values: series.map((studentSeries) => Number(studentSeries.monthly[monthIdx]?.hours || 0))
  }));
  const plottedValues = monthlyRows.flatMap((row) => row.values);
  const rawMax = plottedValues.length ? Math.max(...plottedValues) : 0;
  const yTickStep = rawMax <= 10 ? 1 : (rawMax <= 30 ? 5 : (rawMax <= 80 ? 10 : 20));
  const yAxisMax = rawMax > 0 ? Math.ceil((rawMax + yTickStep) / yTickStep) * yTickStep : 10;
  const yTicks = [];
  for (let tick = 0; tick <= yAxisMax; tick += yTickStep) yTicks.push(tick);

  const width = 1120;
  const height = 330;
  const margin = { top: 40, right: 34, bottom: 58, left: 74 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = monthlyRows.length > 1 ? xSpan / (monthlyRows.length - 1) : 0;
  const xForMonth = (idx) => monthlyRows.length > 1 ? margin.left + xPad + (idx * xStep) : margin.left + (plotW / 2);
  const yFor = (value) => margin.top + ((yAxisMax - value) / yAxisMax) * plotH;
  const baselineY = yFor(0);
  const formatHours = (value) => Number(value || 0).toFixed(Number(value || 0) % 1 === 0 ? 0 : 1);
  const palette = ["#f97316", "#20a65a", "#2563eb", "#8b5cf6", "#ef4444", "#0f766e", "#a16207", "#db2777"];
  const studentColors = series.map((studentSeries, idx) => studentSeries.color || palette[idx % palette.length]);

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${formatHours(tick)}</text></g>`;
  }).join("");

  const xTickSvg = monthlyRows.map((row, idx) => {
    const x = xForMonth(idx);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${row.label}</text>`;
  }).join("");

  const lineSvg = series.map((studentSeries, studentIdx) => {
    const color = studentColors[studentIdx];
    const points = monthlyRows.map((row, monthIdx) => ({
      label: row.label,
      value: Number(row.values[studentIdx] || 0),
      x: xForMonth(monthIdx),
      y: yFor(Number(row.values[studentIdx] || 0))
    })).filter((point) => point.value > 0);
    if (!points.length) return "";
    const path = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    return `<path d="${path}" class="trend-line" style="stroke:${color}" fill="none"><title>${escapeHtml(studentSeries.label)}</title></path>`;
  }).join("");

  const areaSvg = complianceHoursTrendViewMode === "area" ? series.map((studentSeries, studentIdx) => {
    const color = studentColors[studentIdx];
    const points = monthlyRows.map((row, monthIdx) => ({
      value: Number(row.values[studentIdx] || 0),
      x: xForMonth(monthIdx),
      y: yFor(Number(row.values[studentIdx] || 0))
    })).filter((point) => point.value > 0);
    if (points.length < 2) return "";
    const linePath = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    const first = points[0];
    const last = points[points.length - 1];
    return `<path d="${linePath} L ${last.x.toFixed(2)} ${baselineY.toFixed(2)} L ${first.x.toFixed(2)} ${baselineY.toFixed(2)} Z" class="trend-area" style="fill:${color}"></path>`;
  }).join("") : "";

  const pointSvg = complianceHoursTrendShowDataPoints ? series.flatMap((studentSeries, studentIdx) => monthlyRows.map((row, monthIdx) => {
    const value = Number(row.values[studentIdx] || 0);
    if (value <= 0) return "";
    const x = xForMonth(monthIdx);
    const y = yFor(value);
    const color = studentColors[studentIdx];
    const monthTooltip = series.map((entry, idx) => {
      const monthValue = Number(monthlyRows[monthIdx]?.values[idx] || 0);
      return `${entry.label} ${row.label}: ${formatHours(monthValue)} hours`;
    }).join("\n");
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${color};stroke:${color}"><title>${escapeHtml(monthTooltip)}</title></circle>`;
  })).join("") : "";

  const monthHoverZoneSvg = monthlyRows.map((row, monthIdx) => {
    const x = xForMonth(monthIdx);
    const previousX = monthIdx > 0 ? xForMonth(monthIdx - 1) : margin.left;
    const nextX = monthIdx < monthlyRows.length - 1 ? xForMonth(monthIdx + 1) : width - margin.right;
    const left = monthIdx > 0 ? (previousX + x) / 2 : margin.left;
    const right = monthIdx < monthlyRows.length - 1 ? (x + nextX) / 2 : width - margin.right;
    const monthTooltip = series.map((entry, idx) => {
      const monthValue = Number(row.values[idx] || 0);
      return `${entry.label} ${row.label}: ${formatHours(monthValue)} hours`;
    }).join("\n");
    return `<rect x="${left.toFixed(2)}" y="${margin.top}" width="${Math.max(1, right - left).toFixed(2)}" height="${plotH.toFixed(2)}" fill="transparent" pointer-events="all"><title>${escapeHtml(monthTooltip)}</title></rect>`;
  }).join("");

  const labelTop = margin.top + 10;
  const labelBottom = height - margin.bottom - 6;
  const minLabelGap = 12;
  const valueLabelParts = [];
  monthlyRows.forEach((_, monthIdx) => {
    const monthLabels = series.map((studentSeries, studentIdx) => {
      const value = Number(studentSeries.monthly[monthIdx]?.hours || 0);
      if (value <= 0) return null;
      const x = xForMonth(monthIdx);
      const y = yFor(value);
      const nearTop = y <= margin.top + 16;
      const nearBottom = y >= (height - margin.bottom - 10);
      const offsetBase = ((monthIdx + studentIdx) % 2 === 0) ? -10 : 14;
      const offset = nearTop ? 22 : (nearBottom ? -10 : offsetBase);
      return {
        color: studentColors[studentIdx],
        text: formatHours(value),
        x,
        preferredY: clamp(y + offset, labelTop, labelBottom)
      };
    }).filter(Boolean).sort((a, b) => a.preferredY - b.preferredY);

    for (let i = 1; i < monthLabels.length; i += 1) {
      if (monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
        monthLabels[i].preferredY = monthLabels[i - 1].preferredY + minLabelGap;
      }
    }
    const overflow = monthLabels.length ? monthLabels[monthLabels.length - 1].preferredY - labelBottom : 0;
    if (overflow > 0) {
      for (let i = monthLabels.length - 1; i >= 0; i -= 1) {
        monthLabels[i].preferredY -= overflow;
        if (i > 0 && monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
          monthLabels[i - 1].preferredY = monthLabels[i].preferredY - minLabelGap;
        }
      }
    }
    monthLabels.forEach((label) => {
      label.preferredY = clamp(label.preferredY, labelTop, labelBottom);
      const labelWidth = 37;
      valueLabelParts.push(`<g class="trend-value-pill"><rect x="${(label.x - labelWidth / 2).toFixed(2)}" y="${(label.preferredY - 12).toFixed(2)}" width="${labelWidth}" height="18" rx="6" style="fill:${label.color};stroke:${label.color}"></rect><text x="${label.x.toFixed(2)}" y="${label.preferredY.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${label.color}">${label.text}</text></g>`);
    });
  });
  const valueLabelSvg = complianceHoursTrendShowDataPoints ? valueLabelParts.join("") : "";

  const totalHours = series.reduce((sum, studentSeries) => sum + studentSeries.monthly.reduce((inner, row) => inner + Number(row.hours || 0), 0), 0);
  const noData = totalHours === 0
    ? `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No completed instructional hours for the selected filters</text>`
    : "";

  const summaryRows = monthlyRows.map((row) => ({
    label: row.label,
    total: row.values.reduce((sum, value) => sum + Number(value || 0), 0)
  })).filter((row) => row.total > 0);
  const lastRow = summaryRows[summaryRows.length - 1];
  const previousRow = summaryRows[summaryRows.length - 2];
  const trendDelta = lastRow && previousRow ? lastRow.total - previousRow.total : null;
  const highestPoint = series.flatMap((studentSeries, studentIdx) => studentSeries.monthly
    .filter((row) => Number(row.hours || 0) > 0)
    .map((row) => ({ label: studentSeries.label, month: row.label, value: Number(row.hours || 0), color: studentColors[studentIdx] })))
    .sort((a, b) => b.value - a.value)[0];
  const lowestPoint = series.flatMap((studentSeries, studentIdx) => studentSeries.monthly
    .filter((row) => Number(row.hours || 0) > 0)
    .map((row) => ({ label: studentSeries.label, month: row.label, value: Number(row.hours || 0), color: studentColors[studentIdx] })))
    .sort((a, b) => a.value - b.value)[0];
  const averageValue = summaryRows.length ? totalHours / summaryRows.length : null;
  const deltaLabel = trendDelta === null ? "No prior month" : `${trendDelta >= 0 ? "+" : ""}${formatHours(trendDelta)}`;
  const deltaClass = trendDelta === null ? "neutral" : (trendDelta >= 0 ? "positive" : "negative");
  const trendIconSvg = trendDelta === null
    ? `<svg viewBox="0 0 24 24"><path d="M5 12h14"/><path d="M15 8l4 4-4 4"/></svg>`
    : (trendDelta >= 0
      ? `<svg viewBox="0 0 24 24"><path d="M4 17l5-5 4 4 7-8"/><path d="M16 8h4v4"/></svg>`
      : `<svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg>`);
  const summaryHtml = `
    <div class="trend-summary-strip">
      <div class="trend-summary-card ${deltaClass}"><span class="trend-summary-icon" aria-hidden="true">${trendIconSvg}</span><div><span>Overall Trend ${lastRow ? `(${escapeHtml(lastRow.label)})` : ""}</span><strong>${deltaLabel}</strong><small>${previousRow ? `vs. ${escapeHtml(previousRow.label)}` : "Need another month"}</small></div></div>
      <div class="trend-summary-card positive"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v4a5 5 0 0 1-10 0V4z"/><path d="M5 5H3v2a4 4 0 0 0 4 4"/><path d="M19 5h2v2a4 4 0 0 1-4 4"/></svg></span><div><span>Highest Hours</span><strong>${highestPoint ? formatHours(highestPoint.value) : "-"}</strong><small>${highestPoint ? `${escapeHtml(highestPoint.label)} (${escapeHtml(highestPoint.month)})` : "No hours"}</small></div></div>
      <div class="trend-summary-card negative"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg></span><div><span>Lowest Hours</span><strong>${lowestPoint ? formatHours(lowestPoint.value) : "-"}</strong><small>${lowestPoint ? `${escapeHtml(lowestPoint.label)} (${escapeHtml(lowestPoint.month)})` : "No hours"}</small></div></div>
      <div class="trend-summary-card neutral"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 20V10"/><path d="M12 20V4"/><path d="M19 20v-7"/></svg></span><div><span>${months.length}-Month Average</span><strong>${averageValue === null ? "-" : formatHours(averageValue)}</strong><small>${selectedStudentIds.length ? `${selectedStudentIds.length} selected students` : "All Students"}</small></div></div>
    </div>`;

  const legendHtml = `
    <div class="trend-legend">
      ${series.map((studentSeries, idx) => `
        <span class="trend-legend-item">
          <span class="trend-legend-line" style="background:${studentColors[idx]}"></span>
          <span>${escapeHtml(studentSeries.label)}</span>
        </span>`).join("")}
    </div>`;
  chartHost.innerHTML = `
    <div class="trend-chart-panel">
      <div class="trend-chart-toolbar">
        <div class="trend-view-toggle" aria-label="Instruction hours chart view">
          <button type="button" data-compliance-hours-trend-view="line" class="${complianceHoursTrendViewMode === "line" ? "active" : ""}">Line View</button>
          <button type="button" data-compliance-hours-trend-view="area" class="${complianceHoursTrendViewMode === "area" ? "active" : ""}">Area View</button>
        </div>
        <label class="trend-data-toggle"><span>Show Data Points</span><input id="compliance-hours-trend-data-points-toggle" type="checkbox"${complianceHoursTrendShowDataPoints ? " checked" : ""}><span aria-hidden="true"></span></label>
      </div>
      <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly instruction hours line chart">
        <defs>
          <filter id="gradeTrendGlow" x="-15%" y="-40%" width="130%" height="180%"><feGaussianBlur stdDeviation="2.5" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
        </defs>
        <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
        <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
        ${yTickSvg}
        ${xTickSvg}
        ${areaSvg}
        ${lineSvg}
        ${pointSvg}
        ${valueLabelSvg}
        ${monthHoverZoneSvg}
        ${noData}
        <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
        <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Instruction Hours</text>
      </svg>
      ${legendHtml}
    </div>
    ${summaryHtml}`;
  if (renderStartedAt) {
    recordPerformanceMetric("dashboard.renderComplianceHoursMonthlyChart", performanceNow() - renderStartedAt, {
      months: months.length,
      series: series.length
    });
  }
}

function renderComplianceDaysMonthlyChart() {
  renderComplianceDaysMonthlyModernChart();
}

function renderComplianceDaysMonthlyModernChart() {
  const chartHost = document.getElementById("compliance-days-monthly-chart");
  if (!chartHost) return;
  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const today = toDate(todayISO());
  const selectedStudentIds = getComplianceDaysSelectedStudentIds();
  const { months, series } = buildComplianceMonthlySeries(selectedStudentIds, {
    quarterFilter: document.getElementById("compliance-days-filter-quarter")?.value || "all",
    subjectFilter: document.getElementById("compliance-days-filter-subject")?.value || "all",
    instructorFilter: document.getElementById("compliance-days-filter-instructor")?.value || "all"
  });
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : "<p class='muted'>No school year range set.</p>";
    return;
  }
  if (!series.length) {
    chartHost.innerHTML = "<p class='muted'>No visible students for the current filter.</p>";
    return;
  }

  const monthlyRows = months.map((monthEntry, monthIdx) => ({
    label: new Date(monthEntry.year, monthEntry.month, 1, 12, 0, 0).toLocaleDateString(undefined, { month: "short" }),
    values: series.map((studentSeries) => Number(studentSeries.monthly[monthIdx]?.days || 0))
  }));
  const plottedValues = monthlyRows.flatMap((row) => row.values);
  const rawMax = plottedValues.length ? Math.max(...plottedValues) : 0;
  const yTickStep = rawMax <= 10 ? 1 : (rawMax <= 30 ? 5 : 10);
  const yAxisMax = rawMax > 0 ? Math.ceil((rawMax + yTickStep) / yTickStep) * yTickStep : 10;
  const yTicks = [];
  for (let tick = 0; tick <= yAxisMax; tick += yTickStep) yTicks.push(tick);

  const width = 1120;
  const height = 330;
  const margin = { top: 40, right: 34, bottom: 58, left: 74 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;
  const xPad = 16;
  const xSpan = Math.max(1, plotW - (xPad * 2));
  const xStep = monthlyRows.length > 1 ? xSpan / (monthlyRows.length - 1) : 0;
  const xForMonth = (idx) => monthlyRows.length > 1 ? margin.left + xPad + (idx * xStep) : margin.left + (plotW / 2);
  const yFor = (value) => margin.top + ((yAxisMax - value) / yAxisMax) * plotH;
  const baselineY = yFor(0);
  const formatDays = (value) => Number(value || 0).toFixed(Number(value || 0) % 1 === 0 ? 0 : 1);
  const palette = ["#f97316", "#20a65a", "#2563eb", "#8b5cf6", "#ef4444", "#0f766e", "#a16207", "#db2777"];
  const studentColors = series.map((studentSeries, idx) => studentSeries.color || palette[idx % palette.length]);

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${formatDays(tick)}</text></g>`;
  }).join("");

  const xTickSvg = monthlyRows.map((row, idx) => {
    const x = xForMonth(idx);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${row.label}</text>`;
  }).join("");

  const lineSvg = series.map((studentSeries, studentIdx) => {
    const color = studentColors[studentIdx];
    const points = monthlyRows.map((row, monthIdx) => ({
      value: Number(row.values[studentIdx] || 0),
      x: xForMonth(monthIdx),
      y: yFor(Number(row.values[studentIdx] || 0))
    })).filter((point) => point.value > 0);
    if (!points.length) return "";
    const path = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    return `<path d="${path}" class="trend-line" style="stroke:${color}" fill="none"><title>${escapeHtml(studentSeries.label)}</title></path>`;
  }).join("");

  const areaSvg = complianceDaysTrendViewMode === "area" ? series.map((studentSeries, studentIdx) => {
    const color = studentColors[studentIdx];
    const points = monthlyRows.map((row, monthIdx) => ({
      value: Number(row.values[studentIdx] || 0),
      x: xForMonth(monthIdx),
      y: yFor(Number(row.values[studentIdx] || 0))
    })).filter((point) => point.value > 0);
    if (points.length < 2) return "";
    const linePath = points.map((point, idx) => `${idx === 0 ? "M" : "L"} ${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(" ");
    const first = points[0];
    const last = points[points.length - 1];
    return `<path d="${linePath} L ${last.x.toFixed(2)} ${baselineY.toFixed(2)} L ${first.x.toFixed(2)} ${baselineY.toFixed(2)} Z" class="trend-area" style="fill:${color}"></path>`;
  }).join("") : "";

  const pointSvg = complianceDaysTrendShowDataPoints ? series.flatMap((studentSeries, studentIdx) => monthlyRows.map((row, monthIdx) => {
    const value = Number(row.values[studentIdx] || 0);
    if (value <= 0) return "";
    const x = xForMonth(monthIdx);
    const y = yFor(value);
    const color = studentColors[studentIdx];
    const monthTooltip = series.map((entry, idx) => {
      const monthValue = Number(monthlyRows[monthIdx]?.values[idx] || 0);
      return `${entry.label} ${row.label}: ${formatDays(monthValue)} days`;
    }).join("\n");
    return `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" class="trend-point" style="fill:${color};stroke:${color}"><title>${escapeHtml(monthTooltip)}</title></circle>`;
  })).join("") : "";

  const monthHoverZoneSvg = monthlyRows.map((row, monthIdx) => {
    const x = xForMonth(monthIdx);
    const previousX = monthIdx > 0 ? xForMonth(monthIdx - 1) : margin.left;
    const nextX = monthIdx < monthlyRows.length - 1 ? xForMonth(monthIdx + 1) : width - margin.right;
    const left = monthIdx > 0 ? (previousX + x) / 2 : margin.left;
    const right = monthIdx < monthlyRows.length - 1 ? (x + nextX) / 2 : width - margin.right;
    const monthTooltip = series.map((entry, idx) => {
      const monthValue = Number(row.values[idx] || 0);
      return `${entry.label} ${row.label}: ${formatDays(monthValue)} days`;
    }).join("\n");
    return `<rect x="${left.toFixed(2)}" y="${margin.top}" width="${Math.max(1, right - left).toFixed(2)}" height="${plotH.toFixed(2)}" fill="transparent" pointer-events="all"><title>${escapeHtml(monthTooltip)}</title></rect>`;
  }).join("");

  const labelTop = margin.top + 10;
  const labelBottom = height - margin.bottom - 6;
  const minLabelGap = 12;
  const valueLabelParts = [];
  monthlyRows.forEach((_, monthIdx) => {
    const monthLabels = series.map((studentSeries, studentIdx) => {
      const value = Number(studentSeries.monthly[monthIdx]?.days || 0);
      if (value <= 0) return null;
      const x = xForMonth(monthIdx);
      const y = yFor(value);
      const nearTop = y <= margin.top + 16;
      const nearBottom = y >= (height - margin.bottom - 10);
      const offsetBase = ((monthIdx + studentIdx) % 2 === 0) ? -10 : 14;
      const offset = nearTop ? 22 : (nearBottom ? -10 : offsetBase);
      return {
        color: studentColors[studentIdx],
        text: formatDays(value),
        x,
        preferredY: clamp(y + offset, labelTop, labelBottom)
      };
    }).filter(Boolean).sort((a, b) => a.preferredY - b.preferredY);

    for (let i = 1; i < monthLabels.length; i += 1) {
      if (monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
        monthLabels[i].preferredY = monthLabels[i - 1].preferredY + minLabelGap;
      }
    }
    const overflow = monthLabels.length ? monthLabels[monthLabels.length - 1].preferredY - labelBottom : 0;
    if (overflow > 0) {
      for (let i = monthLabels.length - 1; i >= 0; i -= 1) {
        monthLabels[i].preferredY -= overflow;
        if (i > 0 && monthLabels[i].preferredY - monthLabels[i - 1].preferredY < minLabelGap) {
          monthLabels[i - 1].preferredY = monthLabels[i].preferredY - minLabelGap;
        }
      }
    }
    monthLabels.forEach((label) => {
      label.preferredY = clamp(label.preferredY, labelTop, labelBottom);
      const labelWidth = 37;
      valueLabelParts.push(`<g class="trend-value-pill"><rect x="${(label.x - labelWidth / 2).toFixed(2)}" y="${(label.preferredY - 12).toFixed(2)}" width="${labelWidth}" height="18" rx="6" style="fill:${label.color};stroke:${label.color}"></rect><text x="${label.x.toFixed(2)}" y="${label.preferredY.toFixed(2)}" text-anchor="middle" class="trend-value-label" style="fill:${label.color}">${label.text}</text></g>`);
    });
  });
  const valueLabelSvg = complianceDaysTrendShowDataPoints ? valueLabelParts.join("") : "";

  const totalDays = series.reduce((sum, studentSeries) => sum + studentSeries.monthly.reduce((inner, row) => inner + Number(row.days || 0), 0), 0);
  const noData = totalDays === 0
    ? `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No completed instruction days for the selected filters</text>`
    : "";
  const summaryRows = monthlyRows.map((row) => ({
    label: row.label,
    total: row.values.reduce((sum, value) => sum + Number(value || 0), 0)
  })).filter((row) => row.total > 0);
  const lastRow = summaryRows[summaryRows.length - 1];
  const previousRow = summaryRows[summaryRows.length - 2];
  const trendDelta = lastRow && previousRow ? lastRow.total - previousRow.total : null;
  const highestPoint = series.flatMap((studentSeries, studentIdx) => studentSeries.monthly
    .filter((row) => Number(row.days || 0) > 0)
    .map((row) => ({ label: studentSeries.label, month: row.label, value: Number(row.days || 0), color: studentColors[studentIdx] })))
    .sort((a, b) => b.value - a.value)[0];
  const lowestPoint = series.flatMap((studentSeries, studentIdx) => studentSeries.monthly
    .filter((row) => Number(row.days || 0) > 0)
    .map((row) => ({ label: studentSeries.label, month: row.label, value: Number(row.days || 0), color: studentColors[studentIdx] })))
    .sort((a, b) => a.value - b.value)[0];
  const averageValue = summaryRows.length ? totalDays / summaryRows.length : null;
  const deltaLabel = trendDelta === null ? "No prior month" : `${trendDelta >= 0 ? "+" : ""}${formatDays(trendDelta)}`;
  const deltaClass = trendDelta === null ? "neutral" : (trendDelta >= 0 ? "positive" : "negative");
  const trendIconSvg = trendDelta === null
    ? `<svg viewBox="0 0 24 24"><path d="M5 12h14"/><path d="M15 8l4 4-4 4"/></svg>`
    : (trendDelta >= 0
      ? `<svg viewBox="0 0 24 24"><path d="M4 17l5-5 4 4 7-8"/><path d="M16 8h4v4"/></svg>`
      : `<svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg>`);
  const summaryHtml = `
    <div class="trend-summary-strip">
      <div class="trend-summary-card ${deltaClass}"><span class="trend-summary-icon" aria-hidden="true">${trendIconSvg}</span><div><span>Overall Trend ${lastRow ? `(${escapeHtml(lastRow.label)})` : ""}</span><strong>${deltaLabel}</strong><small>${previousRow ? `vs. ${escapeHtml(previousRow.label)}` : "Need another month"}</small></div></div>
      <div class="trend-summary-card positive"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M7 4h10v4a5 5 0 0 1-10 0V4z"/><path d="M5 5H3v2a4 4 0 0 0 4 4"/><path d="M19 5h2v2a4 4 0 0 1-4 4"/></svg></span><div><span>Highest Days</span><strong>${highestPoint ? formatDays(highestPoint.value) : "-"}</strong><small>${highestPoint ? `${escapeHtml(highestPoint.label)} (${escapeHtml(highestPoint.month)})` : "No days"}</small></div></div>
      <div class="trend-summary-card negative"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7l5 5 4-4 7 8"/><path d="M16 16h4v-4"/></svg></span><div><span>Lowest Days</span><strong>${lowestPoint ? formatDays(lowestPoint.value) : "-"}</strong><small>${lowestPoint ? `${escapeHtml(lowestPoint.label)} (${escapeHtml(lowestPoint.month)})` : "No days"}</small></div></div>
      <div class="trend-summary-card neutral"><span class="trend-summary-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 20V10"/><path d="M12 20V4"/><path d="M19 20v-7"/></svg></span><div><span>${months.length}-Month Average</span><strong>${averageValue === null ? "-" : formatDays(averageValue)}</strong><small>${selectedStudentIds.length ? `${selectedStudentIds.length} selected students` : "All Students"}</small></div></div>
    </div>`;
  const legendHtml = `
    <div class="trend-legend">
      ${series.map((studentSeries, idx) => `
        <span class="trend-legend-item">
          <span class="trend-legend-line" style="background:${studentColors[idx]}"></span>
          <span>${escapeHtml(studentSeries.label)}</span>
        </span>`).join("")}
    </div>`;

  chartHost.innerHTML = `
    <div class="trend-chart-panel">
      <div class="trend-chart-toolbar">
        <div class="trend-view-toggle" aria-label="Instruction days chart view">
          <button type="button" data-compliance-days-trend-view="line" class="${complianceDaysTrendViewMode === "line" ? "active" : ""}">Line View</button>
          <button type="button" data-compliance-days-trend-view="area" class="${complianceDaysTrendViewMode === "area" ? "active" : ""}">Area View</button>
        </div>
        <label class="trend-data-toggle"><span>Show Data Points</span><input id="compliance-days-trend-data-points-toggle" type="checkbox"${complianceDaysTrendShowDataPoints ? " checked" : ""}><span aria-hidden="true"></span></label>
      </div>
      <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly instruction days line chart">
        <defs>
          <filter id="gradeTrendGlow" x="-15%" y="-40%" width="130%" height="180%"><feGaussianBlur stdDeviation="2.5" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
        </defs>
        <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
        <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
        ${yTickSvg}
        ${xTickSvg}
        ${areaSvg}
        ${lineSvg}
        ${pointSvg}
        ${valueLabelSvg}
        ${monthHoverZoneSvg}
        ${noData}
        <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
        <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Instruction Days</text>
      </svg>
      ${legendHtml}
    </div>
    ${summaryHtml}`;
}

function renderGradeTypeVolumeChart() {
  const chartHost = document.getElementById("grade-type-volume-chart");
  if (!chartHost) return;
  const allowedStudentIds = visibleStudentIds();
  const preferredTypeOrder = ["Assignment", "Quiz", "Test", "Quarterly Final"];
  const typeOrderValue = (type) => {
    const index = preferredTypeOrder.indexOf(type);
    return index === -1 ? preferredTypeOrder.length : index;
  };
  const displayGradeTypeVolumeLabel = (type) => type === "Quarterly Final" ? "Quarter Final" : type;

  const sy = state.settings.schoolYear;
  const syStart = toDate(sy.startDate);
  const syEnd = toDate(sy.endDate);
  const today = toDate(todayISO());
  const effectiveEnd = syEnd < today ? syEnd : today;
  const months = schoolYearMonths(sy.startDate, toISO(effectiveEnd));
  if (!months.length) {
    chartHost.innerHTML = syStart > today
      ? "<p class='muted'>School year has not started yet.</p>"
      : "<p class='muted'>No school year range set.</p>";
    return;
  }

  const quarterFilter = document.getElementById("volume-filter-quarter")?.value || "all";
  const subjectFilter = document.getElementById("volume-filter-subject")?.value || "all";
  const instructorFilter = document.getElementById("volume-filter-instructor")?.value || "all";
  const gradeTypeFilter = document.getElementById("volume-filter-grade-type")?.value || "all";
  const selectedStudentIds = getVolumeSelectedStudentIds();
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);

  const knownTypes = (availableGradeTypes().length ? [...availableGradeTypes()] : [...DEFAULT_GRADE_TYPES])
    .sort((a, b) => typeOrderValue(a) - typeOrderValue(b) || a.localeCompare(b));
  const inYearTests = state.tests.filter((t) => inRange(t.date, sy.startDate, sy.endDate));
  const filteredTests = inYearTests.filter((t) => {
    if (!allowedStudentIds.has(t.studentId)) return false;
    if (quarterRange && quarterFilter !== "all" && !inRange(t.date, quarterRange.startDate, quarterRange.endDate)) return false;
    if (subjectFilter !== "all" && t.subjectId !== subjectFilter) return false;
    if (!testMatchesInstructorFilter(t, instructorFilter)) return false;
    const thisType = gradeTypeName(t);
    if (gradeTypeFilter !== "all" && thisType !== gradeTypeFilter) return false;
    if (selectedStudentIds.length && !selectedStudentIds.includes(t.studentId)) return false;
    return true;
  });

  filteredTests.forEach((test) => {
    const gradeType = gradeTypeName(test);
    if (!knownTypes.includes(gradeType)) knownTypes.push(gradeType);
  });
  knownTypes.sort((a, b) => typeOrderValue(a) - typeOrderValue(b) || a.localeCompare(b));

  const monthlyCounts = months.map((entry) => {
    const monthStart = new Date(entry.year, entry.month, 1, 12, 0, 0);
    const monthEnd = new Date(entry.year, entry.month + 1, 0, 12, 0, 0);
    const monthStartIso = toISO(monthStart);
    const monthEndIso = toISO(monthEnd);
    const tests = filteredTests.filter((t) => inRange(t.date, monthStartIso, monthEndIso));
    const counts = new Map(knownTypes.map((type) => [type, 0]));
    tests.forEach((test) => {
      const gradeType = gradeTypeName(test);
      counts.set(gradeType, (counts.get(gradeType) || 0) + 1);
    });
    return {
      label: monthStart.toLocaleDateString(undefined, { month: "short" }),
      counts
    };
  });

  const maxCount = Math.max(1, ...monthlyCounts.flatMap((m) => knownTypes.map((type) => m.counts.get(type) || 0)));
  const yTickStep = maxCount <= 10 ? 1 : (maxCount <= 30 ? 5 : 10);
  const yAxisMax = Math.ceil((maxCount + yTickStep) / yTickStep) * yTickStep;
  const yTicks = [];
  for (let tick = 0; tick <= yAxisMax; tick += yTickStep) yTicks.push(tick);

  const width = 960;
  const height = 320;
  const margin = { top: 28, right: 20, bottom: 62, left: 52 };
  const plotW = width - margin.left - margin.right;
  const plotH = height - margin.top - margin.bottom;

  const groupCount = months.length;
  const groupSlot = plotW / Math.max(1, groupCount);
  const groupWidth = Math.min(86, groupSlot * 0.82);
  const barGap = 2;
  const barCount = Math.max(1, knownTypes.length);
  const barWidth = Math.max(3, (groupWidth - (barGap * (barCount - 1))) / barCount);

  const xGroupStart = (idx) => margin.left + (idx * groupSlot) + ((groupSlot - groupWidth) / 2);
  const xForBar = (monthIdx, typeIdx) => xGroupStart(monthIdx) + (typeIdx * (barWidth + barGap));
  const yFor = (value) => margin.top + ((yAxisMax - value) / yAxisMax) * plotH;

  const yTickSvg = yTicks.map((tick) => {
    const y = yFor(tick);
    return `<g><line x1="${margin.left}" y1="${y.toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${y.toFixed(2)}" class="trend-grid"/><text x="${(margin.left - 10).toFixed(2)}" y="${(y + 4).toFixed(2)}" text-anchor="end" class="trend-axis-label">${tick}</text></g>`;
  }).join("");

  const xTickSvg = monthlyCounts.map((row, idx) => {
    const x = xGroupStart(idx) + (groupWidth / 2);
    return `<text x="${x.toFixed(2)}" y="${(height - margin.bottom + 18).toFixed(2)}" text-anchor="middle" class="trend-axis-label">${row.label}</text>`;
  }).join("");

  const palette = ["#a66a32", "#2d5d8c", "#b0525c", "#3f8b5d", "#8e4de6", "#f19012", "#35736f", "#9b4d2f"];
  const metricIcons = {
    Assignment: `<svg viewBox="0 0 24 24"><path d="M6 2h8l4 4v16H6z"/><path d="M14 2v5h5"/></svg>`,
    "Quarterly Final": `<svg viewBox="0 0 24 24"><path d="M5 5v14"/><path d="M5 5c4-2 7 2 11 0v9c-4 2-7-2-11 0"/></svg>`,
    Quiz: `<svg viewBox="0 0 24 24"><path d="M8 6h12"/><path d="M8 12h12"/><path d="M8 18h12"/><circle cx="4" cy="6" r="1"/><circle cx="4" cy="12" r="1"/><circle cx="4" cy="18" r="1"/></svg>`,
    Test: `<svg viewBox="0 0 24 24"><path d="M9 5h6"/><path d="M9 3h6v4H9z"/><path d="M5 5h14v16H5z"/><path d="m9 14 2 2 4-5"/></svg>`
  };
  const barsSvg = monthlyCounts.flatMap((row, monthIdx) =>
    knownTypes.map((type, typeIdx) => {
      const count = row.counts.get(type) || 0;
      const x = xForBar(monthIdx, typeIdx);
      const y = yFor(count);
      const h = Math.max(0, (height - margin.bottom) - y);
      const color = palette[typeIdx % palette.length];
      const labelY = Math.max(margin.top + 14, y - 7);
      const labelX = x + (barWidth / 2);
      const valueLabel = `<text x="${labelX.toFixed(2)}" y="${labelY.toFixed(2)}" text-anchor="middle" class="grade-type-volume-value" fill="${color}">${count}</text>`;
      return `<g><rect class="grade-type-volume-bar" x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${barWidth.toFixed(2)}" height="${h.toFixed(2)}" rx="3" fill="${color}"><title>${row.label} ${displayGradeTypeVolumeLabel(type)}: ${count}</title></rect>${valueLabel}</g>`;
    })
  ).join("");

  const totalCounts = monthlyCounts.reduce((sum, row) =>
    sum + knownTypes.reduce((inner, type) => inner + (row.counts.get(type) || 0), 0), 0);
  const noData = totalCounts === 0
    ? `<text x="${(margin.left + plotW / 2).toFixed(2)}" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" class="trend-empty">No grade entries for this school year</text>`
    : "";

  const legendHtml = `
    <div class="trend-legend">
      ${knownTypes.map((type, idx) => `
        <span class="trend-legend-item">
          <span class="volume-legend-box" style="background:${palette[idx % palette.length]}"></span>
          <span>${displayGradeTypeVolumeLabel(type)}</span>
        </span>`).join("")}
    </div>`;
  const metricHtml = `
    <div class="grade-type-volume-metrics">
      ${knownTypes.map((type, idx) => {
        const total = monthlyCounts.reduce((sum, row) => sum + (row.counts.get(type) || 0), 0);
        const label = displayGradeTypeVolumeLabel(type);
        const plural = type === "Quiz" ? "Quizzes" : (type === "Test" ? "Tests" : `${label}s`);
        return `
          <article class="grade-type-volume-metric" style="--volume-accent:${palette[idx % palette.length]}">
            <span class="grade-type-volume-metric-icon" aria-hidden="true">${metricIcons[type] || metricIcons.Assignment}</span>
            <span>
              <small>Total ${plural}</small>
              <strong>${total}</strong>
              <em>All Time</em>
            </span>
          </article>`;
      }).join("")}
    </div>`;
  const tableHtml = `
    <div class="grade-type-volume-table-wrap hidden">
      <table class="student-performance-table grade-type-volume-table">
        <thead>
          <tr><th>Month</th>${knownTypes.map((type) => `<th>${displayGradeTypeVolumeLabel(type)}</th>`).join("")}</tr>
        </thead>
        <tbody>
          ${monthlyCounts.map((row) => `
            <tr>
              <td>${row.label}</td>
              ${knownTypes.map((type) => `<td>${row.counts.get(type) || 0}</td>`).join("")}
            </tr>`).join("")}
        </tbody>
      </table>
    </div>`;

  chartHost.innerHTML = `
    <div class="grade-type-volume-panel">
      <div class="grade-type-volume-panel-header">
        <div class="student-performance-heading">
          <span class="student-performance-heading-icon grade-type-volume-heading-icon" aria-hidden="true">
            <svg viewBox="0 0 24 24"><path d="M4 19V5"/><path d="M8 19V9"/><path d="M12 19V7"/><path d="M16 19v-5"/><path d="M20 19V11"/></svg>
          </span>
          <div>
            <h4>Grade Volume by Type</h4>
            <p class="muted">Showing grade counts by month</p>
          </div>
        </div>
        <button type="button" class="grade-type-volume-table-toggle" aria-pressed="false"><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 18h16"/><path d="M6 15l4-4 3 3 5-7"/><path d="M15 7h3v3"/></svg></span><span>View as Table</span></button>
      </div>
      <div class="grade-type-volume-chart-scroll">
        <svg viewBox="0 0 ${width} ${height}" class="trend-chart" role="img" aria-label="Monthly grade type volume bar chart">
          <line x1="${margin.left}" y1="${(height - margin.bottom).toFixed(2)}" x2="${(width - margin.right).toFixed(2)}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
          <line x1="${margin.left}" y1="${margin.top}" x2="${margin.left}" y2="${(height - margin.bottom).toFixed(2)}" class="trend-axis"></line>
          ${yTickSvg}
          ${xTickSvg}
          ${barsSvg}
          ${noData}
          <text x="${(width / 2).toFixed(2)}" y="${(height - 8).toFixed(2)}" text-anchor="middle" class="trend-axis-title">Month</text>
          <text x="16" y="${(margin.top + plotH / 2).toFixed(2)}" text-anchor="middle" transform="rotate(-90 16 ${(margin.top + plotH / 2).toFixed(2)})" class="trend-axis-title">Count</text>
        </svg>
      </div>
      ${tableHtml}
      ${legendHtml}
    </div>
    ${metricHtml}`;
}

function renderWorkDistributionChart() {
  const chartHost = document.getElementById("work-distribution-chart");
  if (!chartHost) return;
  const allowedStudentIds = visibleStudentIds();
  const availableTypes = availableGradeTypes();
  const selectedGradeTypes = workDistributionSelectedGradeTypes.size
    ? Array.from(workDistributionSelectedGradeTypes)
    : availableTypes;
  const selectedGradeTypeSet = new Set(selectedGradeTypes);

  const sy = state.settings.schoolYear;
  const quarterFilter = document.getElementById("work-filter-quarter")?.value || "all";
  const instructorFilter = document.getElementById("work-filter-instructor")?.value || "all";
  const selectedStudentIds = getWorkSelectedStudentIds();
  const quarterRange = state.settings.quarters.find((q) => q.name === quarterFilter);

  const filteredTests = state.tests.filter((t) => {
    if (!allowedStudentIds.has(t.studentId)) return false;
    if (!inRange(t.date, sy.startDate, sy.endDate)) return false;
    if (quarterRange && quarterFilter !== "all" && !inRange(t.date, quarterRange.startDate, quarterRange.endDate)) return false;
    if (selectedStudentIds.length && !selectedStudentIds.includes(t.studentId)) return false;
    if (!testMatchesInstructorFilter(t, instructorFilter)) return false;
    const gradeType = resolveGradeType(t);
    if (!gradeType) return false;
    return selectedGradeTypeSet.has(gradeType);
  });

  const bySubject = new Map();
  filteredTests.forEach((test) => {
    const subjectName = getSubjectName(test.subjectId);
    bySubject.set(subjectName, (bySubject.get(subjectName) || 0) + 1);
  });

  const entries = Array.from(bySubject.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const total = entries.reduce((sum, [, count]) => sum + count, 0);
  const selectedGradeTypeLabel = selectedGradeTypes.length === availableTypes.length
    ? "All"
    : selectedGradeTypes.join(", ");

  if (!total) {
    chartHost.innerHTML = `<p class='muted'>No grades found for the selected grade types: ${escapeHtml(selectedGradeTypeLabel)}.</p>`;
    return;
  }

  const palette = ["#a36122", "#2f7a43", "#245b8d", "#a6383c", "#b88709", "#6c3ba1", "#3a837f", "#f5660a"];
  const size = 620;
  const cx = 310;
  const cy = 310;
  const outerRadius = 260;
  const innerRadius = 118;

  function polarToCartesian(centerX, centerY, r, angleDeg) {
    const angleRad = ((angleDeg - 90) * Math.PI) / 180;
    return {
      x: centerX + (r * Math.cos(angleRad)),
      y: centerY + (r * Math.sin(angleRad))
    };
  }

  function donutArcPath(centerX, centerY, outerR, innerR, startAngle, endAngle) {
    const outerStart = polarToCartesian(centerX, centerY, outerR, endAngle);
    const outerEnd = polarToCartesian(centerX, centerY, outerR, startAngle);
    const innerStart = polarToCartesian(centerX, centerY, innerR, startAngle);
    const innerEnd = polarToCartesian(centerX, centerY, innerR, endAngle);
    const largeArc = endAngle - startAngle > 180 ? 1 : 0;
    return [
      `M ${outerStart.x.toFixed(2)} ${outerStart.y.toFixed(2)}`,
      `A ${outerR} ${outerR} 0 ${largeArc} 0 ${outerEnd.x.toFixed(2)} ${outerEnd.y.toFixed(2)}`,
      `L ${innerStart.x.toFixed(2)} ${innerStart.y.toFixed(2)}`,
      `A ${innerR} ${innerR} 0 ${largeArc} 1 ${innerEnd.x.toFixed(2)} ${innerEnd.y.toFixed(2)}`,
      "Z"
    ].join(" ");
  }

  let currentAngle = 0;
  const slices = entries.map(([subject, count], idx) => {
    const pctValue = (count / total) * 100;
    const startAngle = currentAngle;
    const endAngle = currentAngle + ((count / total) * 360);
    currentAngle = endAngle;
    const color = palette[idx % palette.length];
    return {
      subject,
      count,
      pctValue,
      pctText: `${pctValue.toFixed(1)}%`,
      color,
      isFull: pctValue >= 99.999,
      startAngle,
      endAngle,
      path: donutArcPath(cx, cy, outerRadius, innerRadius, startAngle, endAngle)
    };
  });

  const sliceSvg = slices.map((slice) =>
    slice.isFull
      ? `<circle cx="${cx}" cy="${cy}" r="${(outerRadius + innerRadius) / 2}" fill="none" stroke="${slice.color}" stroke-width="${outerRadius - innerRadius}" class="work-dist-donut-slice"><title>${slice.subject}: ${slice.count} (${slice.pctText})</title></circle>`
      : `<path d="${slice.path}" fill="${slice.color}" stroke="#ffffff" stroke-width="3" class="work-dist-donut-slice"><title>${slice.subject}: ${slice.count} (${slice.pctText})</title></path>`
  ).join("");

  const labelSvg = slices.map((slice) => {
    if (slice.pctValue < 4) return "";
    const midAngle = (slice.startAngle + slice.endAngle) / 2;
    const point = polarToCartesian(cx, cy, (outerRadius + innerRadius) / 2, midAngle);
    return `<g class="work-dist-donut-label"><svg x="${(point.x - 15).toFixed(2)}" y="${(point.y - 37).toFixed(2)}" width="30" height="30" viewBox="0 0 24 24" class="work-dist-slice-icon" aria-hidden="true">${workDistributionSubjectIconPaths(slice.subject)}</svg><text x="${point.x.toFixed(2)}" y="${(point.y + 16).toFixed(2)}" text-anchor="middle">${slice.pctText}</text></g>`;
  }).join("");

  const maxPct = Math.max(...slices.map((slice) => slice.pctValue), 1);
  const rowsHtml = slices.map((slice) => `
    <article class="work-dist-breakdown-row" style="--work-color:${slice.color};--work-width:${((slice.pctValue / maxPct) * 100).toFixed(1)}%">
      <span class="work-dist-breakdown-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${workDistributionSubjectIconPaths(slice.subject)}</svg></span>
      <div class="work-dist-breakdown-main">
        <span>${escapeHtml(slice.subject)}</span>
        <i><b></b></i>
      </div>
      <strong>${slice.pctText}</strong>
    </article>`).join("");

  chartHost.innerHTML = `
    <div class="work-dist-chart-panel">
      <div class="work-dist-donut-stage">
        <svg viewBox="0 0 ${size} ${size}" class="work-dist-donut-chart" role="img" aria-label="Work distribution by subject">
          <defs>
            <filter id="workDistributionGlow" x="-18%" y="-18%" width="136%" height="136%"><feDropShadow dx="0" dy="16" stdDeviation="12" flood-color="#17243d" flood-opacity="0.16"/></filter>
          </defs>
          <g filter="url(#workDistributionGlow)">
            ${sliceSvg}
          </g>
          ${labelSvg}
        </svg>
        <div class="work-dist-donut-center" aria-hidden="true">
          <span><svg viewBox="0 0 24 24"><path d="M5 19V9"/><path d="M12 19V5"/><path d="M19 19v-8"/></svg></span>
          <em>Total Work</em>
          <strong>100%</strong>
          <small>${total} grades</small>
        </div>
      </div>
      <div class="work-dist-breakdown">
        <div class="work-dist-breakdown-header"><span>Work Type</span><span>Percentage</span></div>
        ${rowsHtml}
        <div class="work-dist-breakdown-total"><span>Total</span><strong>100%</strong></div>
      </div>
    </div>`;
}

function formatDashboardAverageCell(avgValue, count, selectedGradeMethods) {
  if (count <= 0) return `<span class="student-performance-no-grades"><span aria-hidden="true">-</span><span>No grades</span></span>`;
  const parts = selectedGradeMethods.map((method) => {
    if (method === "Percentage") {
      return `<span class="student-performance-score-pill ${dashboardAverageScoreClass(avgValue)}">${avgValue.toFixed(1)}%</span>`;
    }
    if (method === "Letter") return `<span>${scoreToLetterGrade(avgValue) || "-"}</span>`;
    if (method === "GPA") return `<span>${averageToGpa(avgValue).toFixed(2)}</span>`;
    return "";
  }).filter(Boolean);
  return `<span class="student-performance-average-cell">${parts.join("<span class=\"student-performance-average-separator\">/</span>")}<span class="student-performance-trend ${dashboardAverageScoreClass(avgValue)}" aria-hidden="true"><svg viewBox="0 0 16 16"><path d="M2 11l4-4 3 3 5-6"/><path d="M10 4h4v4"/></svg></span></span>`;
}

function dashboardAverageScoreClass(value) {
  const score = Number(clamp(Number(value || 0), 0, 100).toFixed(1));
  if (score >= 90) return "excellent";
  if (score >= 80) return "strong";
  if (score >= 70) return "watch";
  if (score >= 60) return "risk";
  return "critical";
}

function dashboardGradeTypeIcon(gradeType = "") {
  return gradeTypeIconMarkup(gradeTypeIconKeyForName(gradeType), gradeType, "student-performance-type-icon-img");
}

function formatDashboardInstructionalHoursCell(bucketMetrics) {
  const earned = Number(bucketMetrics?.earned || 0).toFixed(1);
  const projected = Number(bucketMetrics?.projected || 0).toFixed(1);
  return `<span class="instructional-hours-cell">${earned} / ${projected} hrs</span>`;
}

function renderDashboardToggleGlyph(expanded) {
  return `<span class="student-avg-toggle-glyph" aria-hidden="true">${expanded ? "-" : "+"}</span>`;
}

function renderStudentInitialsBadge(name) {
  const initials = String(name || "")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() || "")
    .join("") || "?";
  return `<span class="student-analytics-avatar">${escapeHtml(initials)}</span>`;
}

function renderInstructionalHoursAnalyticCell(bucketMetrics) {
  const earned = Number(bucketMetrics?.earned || 0);
  const projected = Number(bucketMetrics?.projected || 0);
  const percent = projected > 0 ? clamp((earned / projected) * 100, 0, 100) : 0;
  return `<div class="hours-analytics-cell"><span>${earned.toFixed(1)} / ${projected.toFixed(1)} hrs</span><i><b style="width: ${percent.toFixed(1)}%"></b></i></div>`;
}

function renderDashboardExpandableTables() {
  const context = dashboardExpandableRenderCache;
  if (!context) return;

  const {
    dashboardStudents,
    totalAttendanceDays,
    attendanceDatesThroughToday,
    quarterByName,
    selectedGradeMethods,
    studentPerformanceInstructorFilter,
    studentInstructionalHoursInstructorFilter
  } = context;

  const gradeTypeOrder = ["Assignment", "Quiz", "Test", "Quarterly Final", "Final", "Quarter Final"];
  const q1 = quarterByName.get("Q1");
  const q2 = quarterByName.get("Q2");
  const q3 = quarterByName.get("Q3");
  const q4 = quarterByName.get("Q4");

  const studentMetrics = dashboardStudents
    .map((student) => {
      const studentTests = state.tests.filter((t) => t.studentId === student.id && testMatchesInstructorFilter(t, studentPerformanceInstructorFilter));
      const q1Tests = q1 ? studentTests.filter((t) => inRange(t.date, q1.startDate, q1.endDate)) : [];
      const q2Tests = q2 ? studentTests.filter((t) => inRange(t.date, q2.startDate, q2.endDate)) : [];
      const q3Tests = q3 ? studentTests.filter((t) => inRange(t.date, q3.startDate, q3.endDate)) : [];
      const q4Tests = q4 ? studentTests.filter((t) => inRange(t.date, q4.startDate, q4.endDate)) : [];
      const q1Avg = weightedAverageForTests(q1Tests, { quarterScoped: true });
      const q2Avg = weightedAverageForTests(q2Tests, { quarterScoped: true });
      const q3Avg = weightedAverageForTests(q3Tests, { quarterScoped: true });
      const q4Avg = weightedAverageForTests(q4Tests, { quarterScoped: true });
      const totalAvg = weightedAverageForTests(studentTests);
      const subjectMap = new Map();
      studentTests.forEach((test) => {
        const subjectId = test.subjectId || "__unknown_subject__";
        if (!subjectMap.has(subjectId)) subjectMap.set(subjectId, []);
        subjectMap.get(subjectId).push(test);
      });
      const subjectRows = Array.from(subjectMap.entries())
        .sort((a, b) => getSubjectName(a[0]).localeCompare(getSubjectName(b[0])))
        .flatMap(([subjectId, testsForSubject]) => {
          const subjectName = getSubjectName(subjectId);
          const q1TestsBySubject = q1 ? testsForSubject.filter((test) => inRange(test.date, q1.startDate, q1.endDate)) : [];
          const q2TestsBySubject = q2 ? testsForSubject.filter((test) => inRange(test.date, q2.startDate, q2.endDate)) : [];
          const q3TestsBySubject = q3 ? testsForSubject.filter((test) => inRange(test.date, q3.startDate, q3.endDate)) : [];
          const q4TestsBySubject = q4 ? testsForSubject.filter((test) => inRange(test.date, q4.startDate, q4.endDate)) : [];
          const q1AvgBySubject = weightedAverageForTests(q1TestsBySubject, { quarterScoped: true });
          const q2AvgBySubject = weightedAverageForTests(q2TestsBySubject, { quarterScoped: true });
          const q3AvgBySubject = weightedAverageForTests(q3TestsBySubject, { quarterScoped: true });
          const q4AvgBySubject = weightedAverageForTests(q4TestsBySubject, { quarterScoped: true });
          const totalAvgBySubject = weightedAverageForTests(testsForSubject);

          const subjectKey = `${student.id}::${subjectId}`;
          const expandedSubject = expandedSubjectAverageRows.has(subjectKey);
          const subjectRow = `<tr class="student-avg-detail-row"><td class="student-avg-subject-cell"><button type="button" class="student-avg-toggle student-avg-subtoggle" data-toggle-subject-avg="${subjectKey}" aria-expanded="${expandedSubject ? "true" : "false"}">${renderDashboardToggleGlyph(expandedSubject)}</button>${escapeHtml(subjectName)}</td><td>${requiredSubjectBadge(subjectId)}</td><td>${formatDashboardAverageCell(totalAvgBySubject, testsForSubject.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q1AvgBySubject, q1TestsBySubject.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q2AvgBySubject, q2TestsBySubject.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q3AvgBySubject, q3TestsBySubject.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q4AvgBySubject, q4TestsBySubject.length, selectedGradeMethods)}</td></tr>`;
          if (!expandedSubject) return [subjectRow];

          const typeMap = new Map();
          testsForSubject.forEach((test) => {
            const gradeType = gradeTypeName(test) || "Other";
            if (!typeMap.has(gradeType)) typeMap.set(gradeType, []);
            typeMap.get(gradeType).push(test);
          });
          const sortedTypes = Array.from(typeMap.keys()).sort((a, b) => {
            const ai = gradeTypeOrder.indexOf(a);
            const bi = gradeTypeOrder.indexOf(b);
            const av = ai === -1 ? Number.MAX_SAFE_INTEGER : ai;
            const bv = bi === -1 ? Number.MAX_SAFE_INTEGER : bi;
            return av - bv || a.localeCompare(b);
          });
          const typeRows = sortedTypes.map((gradeType) => {
            const typeTests = typeMap.get(gradeType) || [];
            const q1TypeTests = q1 ? typeTests.filter((test) => inRange(test.date, q1.startDate, q1.endDate)) : [];
            const q2TypeTests = q2 ? typeTests.filter((test) => inRange(test.date, q2.startDate, q2.endDate)) : [];
            const q3TypeTests = q3 ? typeTests.filter((test) => inRange(test.date, q3.startDate, q3.endDate)) : [];
            const q4TypeTests = q4 ? typeTests.filter((test) => inRange(test.date, q4.startDate, q4.endDate)) : [];
            const q1TypeAvg = weightedAverageForTests(q1TypeTests, { quarterScoped: true });
            const q2TypeAvg = weightedAverageForTests(q2TypeTests, { quarterScoped: true });
            const q3TypeAvg = weightedAverageForTests(q3TypeTests, { quarterScoped: true });
            const q4TypeAvg = weightedAverageForTests(q4TypeTests, { quarterScoped: true });
            const totalTypeAvg = weightedAverageForTests(typeTests);
            return `<tr class="student-avg-type-row"><td class="student-avg-type-cell">${escapeHtml(gradeType)}</td><td></td><td>${formatDashboardAverageCell(totalTypeAvg, typeTests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q1TypeAvg, q1TypeTests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q2TypeAvg, q2TypeTests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q3TypeAvg, q3TypeTests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q4TypeAvg, q4TypeTests.length, selectedGradeMethods)}</td></tr>`;
          });
          return [subjectRow, ...typeRows];
        })
        .join("");
      const expanded = expandedStudentAverageRows.has(student.id);
      const detailRows = subjectRows || "<tr class='student-avg-detail-row'><td colspan='7' class='muted student-avg-detail-empty'>No subject grades yet.</td></tr>";
      return {
        studentId: student.id,
        studentName: `${student.firstName} ${student.lastName}`,
        totalCount: studentTests.length,
        q1Count: q1Tests.length,
        q2Count: q2Tests.length,
        q3Count: q3Tests.length,
        q4Count: q4Tests.length,
        totalValue: studentTests.length ? totalAvg : -1,
        q1Value: q1Avg,
        q2Value: q2Avg,
        q3Value: q3Avg,
        q4Value: q4Avg,
        row: `<tr><td><button type="button" class="student-avg-toggle" data-toggle-student-avg="${student.id}" aria-expanded="${expanded ? "true" : "false"}">${renderDashboardToggleGlyph(expanded)}</button> ${escapeHtml(student.firstName)} ${escapeHtml(student.lastName)}</td><td></td><td>${formatDashboardAverageCell(totalAvg, studentTests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q1Avg, q1Tests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q2Avg, q2Tests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q3Avg, q3Tests.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(q4Avg, q4Tests.length, selectedGradeMethods)}</td></tr>`,
        detailRow: expanded ? detailRows : ""
      };
    })
    .sort((a, b) => b.totalValue - a.totalValue || a.studentName.localeCompare(b.studentName));

  const studentRows = studentMetrics.flatMap((entry) => entry.detailRow ? [entry.row, entry.detailRow] : [entry.row]);
  if (studentMetrics.length) {
    const totals = {
      total: studentMetrics.filter((entry) => entry.totalCount > 0).map((entry) => entry.totalValue),
      q1: studentMetrics.filter((entry) => entry.q1Count > 0).map((entry) => entry.q1Value),
      q2: studentMetrics.filter((entry) => entry.q2Count > 0).map((entry) => entry.q2Value),
      q3: studentMetrics.filter((entry) => entry.q3Count > 0).map((entry) => entry.q3Value),
      q4: studentMetrics.filter((entry) => entry.q4Count > 0).map((entry) => entry.q4Value)
    };
    studentRows.push(`<tr><td><strong>Average</strong></td><td></td><td><strong>${formatDashboardAverageCell(avg(totals.total), totals.total.length, selectedGradeMethods)}</strong></td><td><strong>${formatDashboardAverageCell(avg(totals.q1), totals.q1.length, selectedGradeMethods)}</strong></td><td><strong>${formatDashboardAverageCell(avg(totals.q2), totals.q2.length, selectedGradeMethods)}</strong></td><td><strong>${formatDashboardAverageCell(avg(totals.q3), totals.q3.length, selectedGradeMethods)}</strong></td><td><strong>${formatDashboardAverageCell(avg(totals.q4), totals.q4.length, selectedGradeMethods)}</strong></td></tr>`);
  }
  rowOrEmpty(document.getElementById("student-avg-table"), studentRows, "No students added yet.", 7);

  const studentAttendanceRows = dashboardStudents.flatMap((student) => {
    const summary = studentAttendanceSummary(student.id);
    const presentCount = summary.attended;
    const absentCount = summary.absent;
    const attendanceAverage = totalAttendanceDays > 0 ? (presentCount / totalAttendanceDays) * 100 : 0;
    const expandedAttendance = expandedStudentAttendanceRows.has(student.id);
    const studentRow = `<tr><td><button type="button" class="student-avg-toggle" data-toggle-student-attendance="${student.id}" aria-expanded="${expandedAttendance ? "true" : "false"}">${renderDashboardToggleGlyph(expandedAttendance)}</button> ${student.firstName} ${student.lastName}</td><td>${totalAttendanceDays}</td><td>${presentCount}</td><td>${absentCount}</td><td>${totalAttendanceDays > 0 ? `${attendanceAverage.toFixed(1)}%` : "No days yet"}</td></tr>`;
    if (!expandedAttendance) return [studentRow];
    const quarterRows = state.settings.quarters.map((quarter) => {
      const quarterDates = attendanceDatesThroughToday.filter((d) => inRange(d, quarter.startDate, quarter.endDate));
      const quarterTotalDays = quarterDates.length;
      const quarterSummary = studentAttendanceSummaryByRange(student.id, quarter.startDate, quarter.endDate);
      const quarterPresent = quarterSummary.attended;
      const quarterAbsent = quarterSummary.absent;
      const quarterAverage = quarterTotalDays > 0 ? (quarterPresent / quarterTotalDays) * 100 : 0;
      return `<tr class="student-avg-detail-row"><td class="student-avg-subject-cell">${quarter.name}</td><td>${quarterTotalDays}</td><td>${quarterPresent}</td><td>${quarterAbsent}</td><td>${quarterTotalDays > 0 ? `${quarterAverage.toFixed(1)}%` : "No days yet"}</td></tr>`;
    });
    return [studentRow, ...quarterRows];
  });
  rowOrEmpty(document.getElementById("dashboard-student-attendance-table"), studentAttendanceRows, "No students added yet.", 5);

  const instructionalHours = buildInstructionalHoursSnapshot(dashboardStudents.map((student) => student.id), { instructorId: studentInstructionalHoursInstructorFilter });
  const instructionalHourRows = dashboardStudents
    .map((student) => {
      const studentSummary = instructionalHours.summaryByStudent.get(student.id) || {
        buckets: Object.fromEntries(instructionalHours.buckets.map((bucket) => [bucket.key, { earned: 0, projected: 0 }])),
        subjects: new Map()
      };
      const expanded = expandedStudentInstructionalHourRows.has(student.id);
      const detailRows = Array.from(studentSummary.subjects.values())
        .sort((a, b) => (b.buckets.total.earned - a.buckets.total.earned) || getSubjectName(a.subjectId).localeCompare(getSubjectName(b.subjectId)))
        .map((subjectSummary) => `<tr class="student-avg-detail-row"><td class="student-avg-subject-cell">${getSubjectName(subjectSummary.subjectId)}</td>${instructionalHours.buckets.map((bucket) => `<td>${formatDashboardInstructionalHoursCell(subjectSummary.buckets[bucket.key])}</td>`).join("")}</tr>`)
        .join("");
      return {
        studentName: `${student.firstName} ${student.lastName}`,
        earnedTotal: studentSummary.buckets.total.earned,
        row: `<tr><td><button type="button" class="student-avg-toggle" data-toggle-student-instructional-hours="${student.id}" aria-expanded="${expanded ? "true" : "false"}">${renderDashboardToggleGlyph(expanded)}</button> ${student.firstName} ${student.lastName}</td>${instructionalHours.buckets.map((bucket) => `<td>${formatDashboardInstructionalHoursCell(studentSummary.buckets[bucket.key])}</td>`).join("")}</tr>`,
        detailRow: expanded ? (detailRows || "<tr class='student-avg-detail-row'><td colspan='6' class='muted student-avg-detail-empty'>No scheduled instructional hours yet.</td></tr>") : ""
      };
    })
    .sort((a, b) => b.earnedTotal - a.earnedTotal || a.studentName.localeCompare(b.studentName));
  rowOrEmpty(
    document.getElementById("dashboard-student-instructional-hours-table"),
    instructionalHourRows.flatMap((entry) => entry.detailRow ? [entry.row, entry.detailRow] : [entry.row]),
    "No students added yet.",
    6
  );
}

function buildDashboardExpandableMetrics(
  dashboardStudents,
  totalAttendanceDays,
  attendanceDatesThroughToday,
  quarterByName,
  studentPerformanceInstructorFilter,
  studentInstructionalHoursInstructorFilter,
  options = {}
) {
  const includePerformance = options.includePerformance !== false;
  const includeAttendance = options.includeAttendance !== false;
  const includeInstructionalHours = options.includeInstructionalHours !== false;
  const metricsStartedAt = performanceDiagnosticsEnabled() ? performanceNow() : 0;
  const gradeTypeOrder = ["Assignment", "Quiz", "Test", "Quarterly Final", "Final", "Quarter Final"];
  const q1 = quarterByName.get("Q1");
  const q2 = quarterByName.get("Q2");
  const q3 = quarterByName.get("Q3");
  const q4 = quarterByName.get("Q4");

  const performanceMetrics = includePerformance ? dashboardStudents
    .map((student) => {
      const studentTests = state.tests.filter((t) => t.studentId === student.id && testMatchesInstructorFilter(t, studentPerformanceInstructorFilter));
      const q1Tests = q1 ? studentTests.filter((t) => inRange(t.date, q1.startDate, q1.endDate)) : [];
      const q2Tests = q2 ? studentTests.filter((t) => inRange(t.date, q2.startDate, q2.endDate)) : [];
      const q3Tests = q3 ? studentTests.filter((t) => inRange(t.date, q3.startDate, q3.endDate)) : [];
      const q4Tests = q4 ? studentTests.filter((t) => inRange(t.date, q4.startDate, q4.endDate)) : [];
      const subjectMap = new Map();
      studentTests.forEach((test) => {
        const subjectId = test.subjectId || "__unknown_subject__";
        if (!subjectMap.has(subjectId)) subjectMap.set(subjectId, []);
        subjectMap.get(subjectId).push(test);
      });
      const subjects = Array.from(subjectMap.entries())
        .sort((a, b) => getSubjectName(a[0]).localeCompare(getSubjectName(b[0])))
        .map(([subjectId, testsForSubject]) => {
          const q1TestsBySubject = q1 ? testsForSubject.filter((test) => inRange(test.date, q1.startDate, q1.endDate)) : [];
          const q2TestsBySubject = q2 ? testsForSubject.filter((test) => inRange(test.date, q2.startDate, q2.endDate)) : [];
          const q3TestsBySubject = q3 ? testsForSubject.filter((test) => inRange(test.date, q3.startDate, q3.endDate)) : [];
          const q4TestsBySubject = q4 ? testsForSubject.filter((test) => inRange(test.date, q4.startDate, q4.endDate)) : [];
          const typeMap = new Map();
          testsForSubject.forEach((test) => {
            const gradeType = gradeTypeName(test) || "Other";
            if (!typeMap.has(gradeType)) typeMap.set(gradeType, []);
            typeMap.get(gradeType).push(test);
          });
          const types = Array.from(typeMap.keys())
            .sort((a, b) => {
              const ai = gradeTypeOrder.indexOf(a);
              const bi = gradeTypeOrder.indexOf(b);
              const av = ai === -1 ? Number.MAX_SAFE_INTEGER : ai;
              const bv = bi === -1 ? Number.MAX_SAFE_INTEGER : bi;
              return av - bv || a.localeCompare(b);
            })
            .map((gradeType) => {
              const typeTests = typeMap.get(gradeType) || [];
              const q1TypeTests = q1 ? typeTests.filter((test) => inRange(test.date, q1.startDate, q1.endDate)) : [];
              const q2TypeTests = q2 ? typeTests.filter((test) => inRange(test.date, q2.startDate, q2.endDate)) : [];
              const q3TypeTests = q3 ? typeTests.filter((test) => inRange(test.date, q3.startDate, q3.endDate)) : [];
              const q4TypeTests = q4 ? typeTests.filter((test) => inRange(test.date, q4.startDate, q4.endDate)) : [];
              return {
                gradeType,
                count: typeTests.length,
                totalAvg: weightedAverageForTests(typeTests),
                q1Count: q1TypeTests.length,
                q2Count: q2TypeTests.length,
                q3Count: q3TypeTests.length,
                q4Count: q4TypeTests.length,
                q1Avg: weightedAverageForTests(q1TypeTests, { quarterScoped: true }),
                q2Avg: weightedAverageForTests(q2TypeTests, { quarterScoped: true }),
                q3Avg: weightedAverageForTests(q3TypeTests, { quarterScoped: true }),
                q4Avg: weightedAverageForTests(q4TypeTests, { quarterScoped: true })
              };
            });
          return {
            subjectId,
            subjectName: getSubjectName(subjectId),
            count: testsForSubject.length,
            totalAvg: weightedAverageForTests(testsForSubject),
            q1Count: q1TestsBySubject.length,
            q2Count: q2TestsBySubject.length,
            q3Count: q3TestsBySubject.length,
            q4Count: q4TestsBySubject.length,
            q1Avg: weightedAverageForTests(q1TestsBySubject, { quarterScoped: true }),
            q2Avg: weightedAverageForTests(q2TestsBySubject, { quarterScoped: true }),
            q3Avg: weightedAverageForTests(q3TestsBySubject, { quarterScoped: true }),
            q4Avg: weightedAverageForTests(q4TestsBySubject, { quarterScoped: true }),
            types
          };
        });
      const totalAvg = weightedAverageForTests(studentTests);
      return {
        studentId: student.id,
        studentName: `${student.firstName} ${student.lastName}`,
        totalCount: studentTests.length,
        q1Count: q1Tests.length,
        q2Count: q2Tests.length,
        q3Count: q3Tests.length,
        q4Count: q4Tests.length,
        totalAvg,
        q1Avg: weightedAverageForTests(q1Tests, { quarterScoped: true }),
        q2Avg: weightedAverageForTests(q2Tests, { quarterScoped: true }),
        q3Avg: weightedAverageForTests(q3Tests, { quarterScoped: true }),
        q4Avg: weightedAverageForTests(q4Tests, { quarterScoped: true }),
        sortValue: studentTests.length ? totalAvg : -1,
        subjects
      };
    })
    .sort((a, b) => b.sortValue - a.sortValue || a.studentName.localeCompare(b.studentName)) : null;

  const attendanceMetrics = includeAttendance ? dashboardStudents.map((student) => {
    const summary = studentAttendanceSummary(student.id);
    return {
      studentId: student.id,
      studentName: `${student.firstName} ${student.lastName}`,
      totalDays: totalAttendanceDays,
      present: summary.attended,
      absent: summary.absent,
      attendanceAverage: totalAttendanceDays > 0 ? (summary.attended / totalAttendanceDays) * 100 : 0,
      quarters: state.settings.quarters.map((quarter) => {
        const quarterDates = attendanceDatesThroughToday.filter((d) => inRange(d, quarter.startDate, quarter.endDate));
        const quarterSummary = studentAttendanceSummaryByRange(student.id, quarter.startDate, quarter.endDate);
        return {
          name: quarter.name,
          totalDays: quarterDates.length,
          present: quarterSummary.attended,
          absent: quarterSummary.absent
        };
      })
    };
  }) : null;

  let instructionalHours = null;
  let instructionalHourMetrics = null;
  if (includeInstructionalHours) {
    instructionalHours = buildInstructionalHoursSnapshot(dashboardStudents.map((student) => student.id), { instructorId: studentInstructionalHoursInstructorFilter });
    instructionalHourMetrics = dashboardStudents
      .map((student) => {
        const studentSummary = instructionalHours.summaryByStudent.get(student.id) || {
          buckets: Object.fromEntries(instructionalHours.buckets.map((bucket) => [bucket.key, { earned: 0, projected: 0 }])),
          subjects: new Map()
        };
        return {
          studentId: student.id,
          studentName: `${student.firstName} ${student.lastName}`,
          earnedTotal: studentSummary.buckets.total.earned,
          buckets: studentSummary.buckets,
          subjects: Array.from(studentSummary.subjects.values())
            .sort((a, b) => (b.buckets.total.earned - a.buckets.total.earned) || getSubjectName(a.subjectId).localeCompare(getSubjectName(b.subjectId)))
            .map((subjectSummary) => ({
              subjectId: subjectSummary.subjectId,
              subjectName: getSubjectName(subjectSummary.subjectId),
              buckets: subjectSummary.buckets
            }))
        };
      })
      .sort((a, b) => b.earnedTotal - a.earnedTotal || a.studentName.localeCompare(b.studentName));
  }

  if (metricsStartedAt) {
    recordPerformanceMetric("dashboard.buildExpandableMetrics", performanceNow() - metricsStartedAt, {
      students: dashboardStudents.length,
      includePerformance,
      includeAttendance,
      includeInstructionalHours,
      tests: state.tests.length,
      attendance: state.attendance.length,
      instructionActuals: state.instructionActuals.length
    });
  }
  return { performanceMetrics, attendanceMetrics, instructionalHours, instructionalHourMetrics };
}

function renderDashboardExpandableTablesFast() {
  const context = dashboardExpandableRenderCache;
  const metrics = dashboardExpandableMetricsCache;
  if (!context || !metrics) return;

  const { selectedGradeMethods = STUDENT_PERFORMANCE_GRADE_METHODS } = context;
  const { performanceMetrics, attendanceMetrics, instructionalHours, instructionalHourMetrics } = metrics;

  if (Array.isArray(performanceMetrics)) {
    const studentRows = performanceMetrics.flatMap((entry) => {
    const expanded = expandedStudentAverageRows.has(entry.studentId);
    const subjectRows = entry.subjects.flatMap((subject) => {
      const subjectKey = `${entry.studentId}::${subject.subjectId}`;
      const expandedSubject = expandedSubjectAverageRows.has(subjectKey);
      const subjectRow = `<tr class="student-performance-row student-performance-subject-row"><td class="student-avg-subject-cell"><span class="student-performance-branch" aria-hidden="true"></span><button type="button" class="student-avg-toggle student-avg-subtoggle" data-toggle-subject-avg="${subjectKey}" aria-expanded="${expandedSubject ? "true" : "false"}">${renderDashboardToggleGlyph(expandedSubject)}</button><span class="student-performance-row-title">${escapeHtml(subject.subjectName)}</span></td><td>${requiredSubjectBadge(subject.subjectId)}</td><td>${formatDashboardAverageCell(subject.totalAvg, subject.count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(subject.q1Avg, subject.q1Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(subject.q2Avg, subject.q2Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(subject.q3Avg, subject.q3Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(subject.q4Avg, subject.q4Count, selectedGradeMethods)}</td></tr>`;
      if (!expandedSubject) return [subjectRow];
      const typeRows = subject.types.map((type) => `<tr class="student-performance-row student-performance-type-row"><td class="student-avg-type-cell"><span class="student-performance-branch" aria-hidden="true"></span><span class="student-performance-type-icon">${dashboardGradeTypeIcon(type.gradeType)}</span><span class="student-performance-row-title">${escapeHtml(type.gradeType)}</span></td><td></td><td>${formatDashboardAverageCell(type.totalAvg, type.count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(type.q1Avg, type.q1Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(type.q2Avg, type.q2Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(type.q3Avg, type.q3Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(type.q4Avg, type.q4Count, selectedGradeMethods)}</td></tr>`);
      return [subjectRow, ...typeRows];
    }).join("");
    const row = `<tr class="student-performance-row student-performance-student-row"><td><button type="button" class="student-avg-toggle" data-toggle-student-avg="${entry.studentId}" aria-expanded="${expanded ? "true" : "false"}">${renderDashboardToggleGlyph(expanded)}</button><span class="student-performance-row-title">${escapeHtml(entry.studentName)}</span></td><td></td><td>${formatDashboardAverageCell(entry.totalAvg, entry.totalCount, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(entry.q1Avg, entry.q1Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(entry.q2Avg, entry.q2Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(entry.q3Avg, entry.q3Count, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(entry.q4Avg, entry.q4Count, selectedGradeMethods)}</td></tr>`;
    const detailRow = expanded ? (subjectRows || "<tr class='student-avg-detail-row'><td colspan='7' class='muted student-avg-detail-empty'>No subject grades yet.</td></tr>") : "";
    return detailRow ? [row, detailRow] : [row];
  });
    if (performanceMetrics.length) {
      const totals = {
        total: performanceMetrics.filter((entry) => entry.totalCount > 0).map((entry) => entry.totalAvg),
        q1: performanceMetrics.filter((entry) => entry.q1Count > 0).map((entry) => entry.q1Avg),
        q2: performanceMetrics.filter((entry) => entry.q2Count > 0).map((entry) => entry.q2Avg),
        q3: performanceMetrics.filter((entry) => entry.q3Count > 0).map((entry) => entry.q3Avg),
        q4: performanceMetrics.filter((entry) => entry.q4Count > 0).map((entry) => entry.q4Avg)
      };
      studentRows.push(`<tr class="student-performance-row student-performance-average-row"><td><strong>Average</strong></td><td></td><td>${formatDashboardAverageCell(avg(totals.total), totals.total.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(avg(totals.q1), totals.q1.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(avg(totals.q2), totals.q2.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(avg(totals.q3), totals.q3.length, selectedGradeMethods)}</td><td>${formatDashboardAverageCell(avg(totals.q4), totals.q4.length, selectedGradeMethods)}</td></tr>`);
    }
    rowOrEmpty(document.getElementById("student-avg-table"), studentRows, "No students added yet.", 7);
  }

  if (Array.isArray(attendanceMetrics)) {
    const studentAttendanceRows = attendanceMetrics.flatMap((entry) => {
    const expandedAttendance = expandedStudentAttendanceRows.has(entry.studentId);
    const attendancePercent = entry.totalDays > 0 ? clamp(entry.attendanceAverage, 0, 100) : 0;
    const studentRow = `<tr class="student-analytics-row"><td><div class="student-analytics-name"><button type="button" class="student-avg-toggle" data-toggle-student-attendance="${entry.studentId}" aria-expanded="${expandedAttendance ? "true" : "false"}">${renderDashboardToggleGlyph(expandedAttendance)}</button>${renderStudentInitialsBadge(entry.studentName)}<span>${escapeHtml(entry.studentName)}<small>${entry.totalDays > 0 ? `${entry.present} present, ${entry.absent} absent` : "No days yet"}</small></span></div></td><td>${entry.totalDays}</td><td>${entry.present}</td><td>${entry.absent}</td><td><div class="hours-analytics-cell attendance-analytics-cell"><span>${entry.totalDays > 0 ? `${entry.attendanceAverage.toFixed(1)}%` : "No days yet"}</span><i><b style="width: ${attendancePercent.toFixed(1)}%"></b></i></div></td></tr>`;
    if (!expandedAttendance) return [studentRow];
    const quarterRows = entry.quarters.map((quarter) => {
      const quarterAverage = quarter.totalDays > 0 ? (quarter.present / quarter.totalDays) * 100 : 0;
      return `<tr class="student-avg-detail-row"><td class="student-avg-subject-cell">${quarter.name}</td><td>${quarter.totalDays}</td><td>${quarter.present}</td><td>${quarter.absent}</td><td>${quarter.totalDays > 0 ? `${quarterAverage.toFixed(1)}%` : "No days yet"}</td></tr>`;
    });
    return [studentRow, ...quarterRows];
  });
    rowOrEmpty(document.getElementById("dashboard-student-attendance-table"), studentAttendanceRows, "No students added yet.", 5);
  }

  if (instructionalHours && Array.isArray(instructionalHourMetrics)) {
    const selectedInstructionalHoursStudentId = studentInstructionalHoursSelectedStudentId || "all";
    const visibleInstructionalHourMetrics = selectedInstructionalHoursStudentId === "all"
      ? instructionalHourMetrics
      : instructionalHourMetrics.filter((entry) => entry.studentId === selectedInstructionalHoursStudentId);
    const instructionalHourRows = visibleInstructionalHourMetrics.flatMap((entry) => {
    const expanded = expandedStudentInstructionalHourRows.has(entry.studentId);
    const detailRows = entry.subjects.map((subjectSummary) => `<tr class="student-avg-detail-row"><td class="student-avg-subject-cell">${subjectNameWithRequiredBadge(subjectSummary.subjectId)}</td>${instructionalHours.buckets.map((bucket) => `<td>${formatDashboardInstructionalHoursCell(subjectSummary.buckets[bucket.key])}</td>`).join("")}<td></td></tr>`).join("");
    const projectedTotal = Number(entry.buckets.total?.projected || 0);
    const earnedTotal = Number(entry.buckets.total?.earned || 0);
    const projectedDiff = projectedTotal - Number(state.settings.schoolYear.requiredInstructionalHours || 0);
    const statusClass = projectedDiff < -1 ? "behind" : earnedTotal >= projectedTotal && projectedTotal > 0 ? "ahead" : "on-pace";
    const statusLabel = projectedDiff < -1 ? "Projected Short" : earnedTotal >= projectedTotal && projectedTotal > 0 ? "Ahead" : "On Track";
    const row = `<tr class="student-analytics-row"><td><div class="student-analytics-name"><button type="button" class="student-avg-toggle" data-toggle-student-instructional-hours="${entry.studentId}" aria-expanded="${expanded ? "true" : "false"}">${renderDashboardToggleGlyph(expanded)}</button>${renderStudentInitialsBadge(entry.studentName)}<span>${entry.studentName}<small>${statusLabel}</small></span></div></td>${instructionalHours.buckets.map((bucket) => `<td>${renderInstructionalHoursAnalyticCell(entry.buckets[bucket.key])}</td>`).join("")}</tr>`;
    const detailRow = expanded ? (detailRows || "<tr class='student-avg-detail-row'><td colspan='7' class='muted student-avg-detail-empty'>No scheduled instructional hours yet.</td></tr>") : "";
    return detailRow ? [row, detailRow] : [row];
  });
    rowOrEmpty(
      document.getElementById("dashboard-student-instructional-hours-table"),
      instructionalHourRows,
      selectedInstructionalHoursStudentId === "all" ? "No students added yet." : "No instructional hours found for the selected student.",
      6
    );
  }
}

function buildDashboardExecutionSnapshot(referenceISO, dashboardStudents, filters = {}) {
  const snapshotStartedAt = performanceDiagnosticsEnabled() ? performanceNow() : 0;
  const targetStudents = Array.isArray(dashboardStudents) ? dashboardStudents : visibleStudents();
  const studentIds = targetStudents.map((student) => student.id);
  const blocksByStudent = dailyScheduledBlocks(referenceISO, studentIds);
  const instructorIds = Array.isArray(filters.instructorIds) ? filters.instructorIds.filter(Boolean) : [];
  const subjectId = filters.subjectId || "all";
  const students = targetStudents.map((student) => {
    const instructionBlocks = (blocksByStudent.get(student.id) || [])
      .filter((block) => block.type === "instruction")
      .filter((block) => subjectId === "all" || getCourse(block.courseId)?.subjectId === subjectId)
      .filter((block) => !instructorIds.length || instructorIds.some((instructorId) => instructionMatchesInstructorFilter(student.id, block.courseId, referenceISO, instructorId)));
    if (!instructionBlocks.length) return null;
    const activeInstructionBlocks = instructionBlocks.filter((block) => !effectiveInstructionExcused(student.id, block.courseId, referenceISO));
    const excusedCount = instructionBlocks.length - activeInstructionBlocks.length;
    const completedCount = activeInstructionBlocks.filter((block) => effectiveInstructionCompleted(student.id, block.courseId, referenceISO)).length;
    const needsGradeCount = activeInstructionBlocks.filter((block) => gradeRecordsForStudentCourseDate(student.id, block.courseId, referenceISO).length === 0).length;
    const pastDueCount = instructionBlocks.filter((block) => schoolDayInstructionPastDue(block, referenceISO)).length;
    const overrideCount = instructionBlocks.filter((block) => hasInstructionExecutionOverride(student.id, block.courseId, referenceISO)).length;
    const attendance = attendanceRecordForStudentDate(student.id, referenceISO);
    const completedMinutes = instructionBlocks.reduce((sum, block) => (
      effectiveInstructionCompleted(student.id, block.courseId, referenceISO)
        ? sum + effectiveInstructionMinutes(student.id, block.courseId, referenceISO)
        : sum
    ), 0);
    const scheduledMinutes = instructionBlocks.reduce((sum, block) => (
      effectiveInstructionExcused(student.id, block.courseId, referenceISO)
        ? sum
        : sum + effectiveInstructionMinutes(student.id, block.courseId, referenceISO)
    ), 0);
    const gradedCount = activeInstructionBlocks.filter((block) => gradeRecordsForStudentCourseDate(student.id, block.courseId, referenceISO).length > 0).length;
    return {
      student,
      scheduledCount: instructionBlocks.length,
      completableCount: activeInstructionBlocks.length,
      completedCount,
      excusedCount,
      openCount: Math.max(activeInstructionBlocks.length - completedCount, 0),
      gradedCount,
      needsGradeCount,
      pastDueCount,
      overrideCount,
      completedMinutes,
      scheduledMinutes,
      attendanceState: attendance ? (attendance.present ? "present" : "absent") : "open"
    };
  }).filter(Boolean);

  const totals = students.reduce((summary, entry) => {
    summary.scheduledCount += entry.scheduledCount;
    summary.completableCount += entry.completableCount;
    summary.completedCount += entry.completedCount;
    summary.excusedCount += entry.excusedCount;
    summary.gradedCount += entry.gradedCount;
    summary.needsGradeCount += entry.needsGradeCount;
    summary.pastDueCount += entry.pastDueCount;
    summary.overrideCount += entry.overrideCount;
    summary.needsCompletionCount += entry.openCount;
    summary.completedMinutes += entry.completedMinutes;
    summary.scheduledMinutes += entry.scheduledMinutes;
    if (entry.attendanceState === "open") summary.needsAttendanceCount += 1;
    if (entry.attendanceState === "present") summary.presentCount += 1;
    if (entry.attendanceState === "absent") summary.absentCount += 1;
    return summary;
  }, {
    scheduledCount: 0,
    completableCount: 0,
    completedCount: 0,
    excusedCount: 0,
    gradedCount: 0,
    needsGradeCount: 0,
    pastDueCount: 0,
    overrideCount: 0,
    needsCompletionCount: 0,
    needsAttendanceCount: 0,
    presentCount: 0,
    absentCount: 0,
    completedMinutes: 0,
    scheduledMinutes: 0
  });

  const snapshot = {
    date: referenceISO,
    students,
    completionPercent: totals.completableCount > 0 ? (totals.completedCount / totals.completableCount) * 100 : 0,
    gradedPercent: totals.completableCount > 0 ? (totals.gradedCount / totals.completableCount) * 100 : 0,
    loggedHoursPercent: totals.scheduledMinutes > 0 ? (totals.completedMinutes / totals.scheduledMinutes) * 100 : 0,
    attentionTotal: totals.needsAttendanceCount + totals.needsGradeCount + totals.needsCompletionCount + totals.overrideCount,
    ...totals
  };
  if (snapshotStartedAt) {
    recordPerformanceMetric("dashboard.buildExecutionSnapshot", performanceNow() - snapshotStartedAt, {
      date: referenceISO,
      students: targetStudents.length,
      filteredStudents: students.length,
      attendance: state.attendance.length,
      instructionActuals: state.instructionActuals.length,
      tests: state.tests.length
    });
  }
  return snapshot;
}

function renderCompletionTodayFilterOptions(dashboardStudents) {
  const students = Array.isArray(dashboardStudents) ? dashboardStudents : visibleStudents();
  const validIds = new Set(students.map((student) => student.id));
  Array.from(completionTodaySelectedStudentIds).forEach((studentId) => {
    if (!validIds.has(studentId)) completionTodaySelectedStudentIds.delete(studentId);
  });
  Array.from(completionTodaySelectedInstructorIds).forEach((instructorId) => {
    if (!assignableInstructorOptions().some((instructor) => instructor.id === instructorId)) completionTodaySelectedInstructorIds.delete(instructorId);
  });
  if (completionTodaySelectedSubjectId !== "all" && !state.subjects.some((subject) => subject.id === completionTodaySelectedSubjectId)) {
    completionTodaySelectedSubjectId = "all";
  }

  const studentOptions = document.getElementById("completion-today-student-options");
  if (studentOptions) {
    studentOptions.innerHTML = students
      .slice()
      .sort((a, b) => `${a.lastName}, ${a.firstName}`.localeCompare(`${b.lastName}, ${b.firstName}`))
      .map((student, idx) => {
        const checked = completionTodaySelectedStudentIds.has(student.id) ? " checked" : "";
        const inputId = `completion-today-student-${idx}-${student.id}`;
        return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="completion-today-student-checkbox" value="${student.id}"${checked}><label for="${inputId}">${student.firstName} ${student.lastName}</label></div>`;
      }).join("") || "<span>No students available.</span>";
  }
  const studentSummary = document.getElementById("completion-today-student-summary");
  if (studentSummary) studentSummary.textContent = `Students (${completionTodaySelectedStudentIds.size} selected)`;

  const instructorOptions = document.getElementById("completion-today-instructor-options");
  if (instructorOptions) {
    instructorOptions.innerHTML = assignableInstructorOptions()
      .map((instructor, idx) => {
        const checked = completionTodaySelectedInstructorIds.has(instructor.id) ? " checked" : "";
        const inputId = `completion-today-instructor-${idx}-${instructor.id}`;
        return `<div class="checklist-row"><input id="${inputId}" type="checkbox" class="completion-today-instructor-checkbox" value="${instructor.id}"${checked}><label for="${inputId}">${escapeHtml(instructorDisplayName(instructor))}</label></div>`;
      }).join("") || "<span>No instructors available.</span>";
  }
  const instructorSummary = document.getElementById("completion-today-instructor-summary");
  if (instructorSummary) instructorSummary.textContent = `Instructors (${completionTodaySelectedInstructorIds.size} selected)`;

  const subjectSelect = document.getElementById("completion-today-subject-filter");
  if (subjectSelect) {
    subjectSelect.innerHTML = "<option value=\"all\">All Subjects</option>";
    state.subjects
      .slice()
      .sort((a, b) => a.name.localeCompare(b.name))
      .forEach((subject) => {
        const option = document.createElement("option");
        option.value = subject.id;
        option.textContent = subject.name;
        subjectSelect.appendChild(option);
      });
    subjectSelect.value = completionTodaySelectedSubjectId;
  }
}

function buildDashboardInstructionHourPaceSnapshot(dashboardStudents, instructionalHoursSnapshot, yearProgressPercent, referenceDate = defaultReferenceDateForActiveYear()) {
  const studentCount = Array.isArray(dashboardStudents) ? dashboardStudents.length : 0;
  const requiredPerStudent = Number(state.settings.schoolYear.requiredInstructionalHours || 0);
  const progressPct = clamp(yearProgressPercent, 0, 100) / 100;
  const requiredTotal = requiredPerStudent * studentCount;
  const expectedToDate = requiredTotal * progressPct;
  const actualToDate = Array.from(instructionalHoursSnapshot.summaryByStudent.values()).reduce((sum, studentSummary) => {
    return sum + Number(studentSummary.buckets.total?.earned || 0);
  }, 0);
  const projectedTotal = Array.from(instructionalHoursSnapshot.summaryByStudent.values()).reduce((sum, studentSummary) => {
    return sum + Number(studentSummary.buckets.total?.projected || 0);
  }, 0);
  const varianceHours = actualToDate - expectedToDate;
  const projectedVarianceHours = projectedTotal - requiredTotal;
  const toleranceHours = Math.max(1, expectedToDate * 0.02);
  const projectedToleranceHours = Math.max(1, requiredTotal * 0.01);
  let status = "On Pace";
  let statusClass = "on-pace";
  if (projectedVarianceHours < -projectedToleranceHours) {
    status = "Projected Short";
    statusClass = "behind";
  } else if (expectedToDate <= 0.01 && actualToDate <= 0.01) {
    status = "Year Opening";
    statusClass = "starting";
  } else if (varianceHours < -toleranceHours) {
    status = "Behind Pace";
    statusClass = "behind";
  } else if (varianceHours > toleranceHours) {
    status = "Ahead of Pace";
    statusClass = "ahead";
  }
  const studentRows = (dashboardStudents || []).map((student) => {
    const studentExpectedToDate = requiredPerStudent * progressPct;
    const studentActualToDate = Number(instructionalHoursSnapshot.summaryByStudent.get(student.id)?.buckets?.total?.earned || 0);
    const studentProjectedTotal = Number(instructionalHoursSnapshot.summaryByStudent.get(student.id)?.buckets?.total?.projected || 0);
    const studentVarianceHours = studentActualToDate - studentExpectedToDate;
    const studentProjectedVarianceHours = studentProjectedTotal - requiredPerStudent;
    const studentToleranceHours = Math.max(1, studentExpectedToDate * 0.02);
    const studentProjectedToleranceHours = Math.max(1, requiredPerStudent * 0.01);
    let studentStatus = "On Pace";
    let studentStatusClass = "on-pace";
    if (studentProjectedVarianceHours < -studentProjectedToleranceHours) {
      studentStatus = "Projected Short";
      studentStatusClass = "behind";
    } else if (studentExpectedToDate <= 0.01 && studentActualToDate <= 0.01) {
      studentStatus = "Year Opening";
      studentStatusClass = "starting";
    } else if (studentVarianceHours < -studentToleranceHours) {
      studentStatus = "Behind Pace";
      studentStatusClass = "behind";
    } else if (studentVarianceHours > studentToleranceHours) {
      studentStatus = "Ahead of Pace";
      studentStatusClass = "ahead";
    }
    return {
      studentId: student.id,
      studentName: `${student.firstName} ${student.lastName}`,
      requiredTotal: requiredPerStudent,
      expectedToDate: studentExpectedToDate,
      actualToDate: studentActualToDate,
      varianceHours: studentVarianceHours,
      projectedTotal: studentProjectedTotal,
      projectedVarianceHours: studentProjectedVarianceHours,
      status: studentStatus,
      statusClass: studentStatusClass
    };
  }).sort((a, b) => a.studentName.localeCompare(b.studentName));
  return {
    referenceDate,
    studentCount,
    requiredTotal,
    expectedToDate,
    actualToDate,
    varianceHours,
    projectedTotal,
    projectedVarianceHours,
    status,
    statusClass,
    studentRows
  };
}

function buildDashboardMissingGradesSnapshot(referenceISO, dashboardStudents) {
  const targetStudents = Array.isArray(dashboardStudents) ? dashboardStudents : visibleStudents();
  const studentIds = targetStudents.map((student) => student.id);
  const blocksByStudent = dailyScheduledBlocks(referenceISO, studentIds);
  const rows = [];
  targetStudents.forEach((student) => {
    const instructionBlocks = (blocksByStudent.get(student.id) || []).filter((block) => block.type === "instruction");
    instructionBlocks.forEach((block) => {
      const isCompleted = effectiveInstructionCompleted(student.id, block.courseId, referenceISO);
      const hasGrade = gradeRecordsForStudentCourseDate(student.id, block.courseId, referenceISO).length > 0;
      if (!isCompleted || hasGrade) return;
      rows.push({
        studentId: student.id,
        studentName: `${student.firstName} ${student.lastName}`,
        courseId: block.courseId,
        courseName: getCourseName(block.courseId),
        subjectName: getSubjectName(block.subjectId),
        timeLabel: `${formatClockTime(block.start)} - ${formatClockTime(block.end)}`,
        statusLabel: "Completed / Awaiting Grade"
      });
    });
  });
  rows.sort((a, b) => a.studentName.localeCompare(b.studentName) || a.timeLabel.localeCompare(b.timeLabel) || a.courseName.localeCompare(b.courseName));
  return {
    date: referenceISO,
    count: rows.length,
    rows
  };
}

function buildDashboardGradeRiskSnapshot(dashboardStudents) {
  const snapshotStartedAt = performanceDiagnosticsEnabled() ? performanceNow() : 0;
  const allowedStudentIds = new Set((dashboardStudents || []).map((student) => student.id));
  const quarter = currentQuarter(toDate(defaultReferenceDateForActiveYear()));
  const quarterTests = state.tests.filter((test) => {
    if (!allowedStudentIds.has(test.studentId)) return false;
    if (!quarter) return recordDateInActiveYear(test);
    return inRange(test.date, quarter.startDate, quarter.endDate);
  });
  const byStudentCourse = new Map();
  quarterTests.forEach((test) => {
    const key = `${test.studentId}||${test.courseId}`;
    if (!byStudentCourse.has(key)) byStudentCourse.set(key, []);
    byStudentCourse.get(key).push(test);
  });
  const rows = Array.from(byStudentCourse.entries()).map(([key, tests]) => {
    const [studentId, courseId] = key.split("||");
    const averageScore = weightedAverageForTests(tests, { quarterScoped: true });
    const subjectId = tests[0]?.subjectId || getCourse(courseId)?.subjectId || "";
    return {
      studentId,
      studentName: getStudentName(studentId),
      courseId,
      courseName: getCourseName(courseId),
      subjectId,
      subjectName: subjectId ? getSubjectName(subjectId) : "Unknown Subject",
      averageScore,
      letterGrade: scoreToLetterGrade(averageScore) || "-",
      gpa: averageToGpa(averageScore),
      riskLevel: averageScore < 70 ? "At Risk" : averageScore < 80 ? "Watch" : "Monitor"
    };
  })
    .filter((row) => row.averageScore < 85)
    .sort((a, b) => a.averageScore - b.averageScore || a.studentName.localeCompare(b.studentName) || a.courseName.localeCompare(b.courseName));
  const snapshot = {
    quarterName: quarter?.name || "Current Quarter",
    count: rows.length,
    rows
  };
  if (snapshotStartedAt) {
    recordPerformanceMetric("dashboard.buildGradeRiskSnapshot", performanceNow() - snapshotStartedAt, {
      students: allowedStudentIds.size,
      tests: state.tests.length,
      scopedTests: quarterTests.length,
      rows: rows.length
    });
  }
  return snapshot;
}

function currentSchoolWeekRange(referenceISO = defaultReferenceDateForActiveYear()) {
  const reference = toDate(referenceISO);
  const day = reference.getDay();
  const mondayOffset = day === 0 ? -6 : 1 - day;
  const fridayOffset = mondayOffset + 4;
  const start = new Date(reference);
  start.setDate(reference.getDate() + mondayOffset);
  const end = new Date(reference);
  end.setDate(reference.getDate() + fridayOffset);
  const activeRange = activeSchoolYearRange();
  return {
    startDate: toISO(start) < activeRange.startDate ? activeRange.startDate : toISO(start),
    endDate: toISO(end) > activeRange.endDate ? activeRange.endDate : toISO(end)
  };
}

function buildDashboardWeeklyGradeRiskSnapshot(dashboardStudents, referenceISO = defaultReferenceDateForActiveYear()) {
  const alertConfig = workspaceConfig?.alerts || DEFAULT_WORKSPACE_CONFIG.alerts;
  const allowedStudentIds = new Set((dashboardStudents || []).map((student) => student.id));
  const weekRange = currentSchoolWeekRange(referenceISO);
  const weekTests = state.tests.filter((test) => (
    allowedStudentIds.has(test.studentId)
    && inRange(test.date, weekRange.startDate, weekRange.endDate)
  ));
  const averageRiskSnapshot = buildDashboardGradeRiskSnapshot(dashboardStudents);
  const singleRows = weekTests.filter((test) => pct(test.score, test.maxScore) < alertConfig.singleGradeRiskThresholdPercent);
  const averageCount = averageRiskSnapshot.count;
  const singleCount = alertConfig.showSingleGradeRisk ? singleRows.length : 0;
  return {
    ...weekRange,
    averageCount,
    singleCount,
    totalCount: averageCount + singleCount
  };
}

function renderDashboardWeeklyGradeRiskSummary(snapshot) {
  const totalNode = document.getElementById("dashboard-overview-grade-risk-value");
  const averageNode = document.getElementById("dashboard-overview-average-grade-risk-count");
  const singleNode = document.getElementById("dashboard-overview-single-grade-risk-count");
  const noteNode = document.getElementById("dashboard-overview-grade-risk-note");
  if (totalNode) totalNode.textContent = String(snapshot.totalCount);
  if (averageNode) averageNode.textContent = String(snapshot.averageCount);
  if (singleNode) singleNode.textContent = String(snapshot.singleCount);
  if (noteNode) {
    noteNode.textContent = snapshot.totalCount
      ? `${snapshot.totalCount} grade risk${snapshot.totalCount === 1 ? "" : "s"} for ${formatDisplayDate(snapshot.startDate)} to ${formatDisplayDate(snapshot.endDate)}.`
      : `No grade risks for ${formatDisplayDate(snapshot.startDate)} to ${formatDisplayDate(snapshot.endDate)}.`;
  }
}

function buildDashboardMissingRequiredSubjectsSnapshot(dashboardStudents) {
  const rows = (dashboardStudents || [])
    .filter((student) => !studentIsArchived(student))
    .map((student) => ({
      student,
      missingSubjects: studentMissingRequiredSubjects(student.id)
    }))
    .filter((entry) => entry.missingSubjects.length > 0)
    .sort((a, b) => `${a.student.lastName || ""} ${a.student.firstName || ""}`.localeCompare(`${b.student.lastName || ""} ${b.student.firstName || ""}`));
  return { count: rows.length, rows };
}

function renderDashboardMissingRequiredSubjectsSummary(snapshot) {
  const valueNode = document.getElementById("dashboard-overview-required-subject-value");
  const listNode = document.getElementById("dashboard-overview-required-subject-list");
  const noteNode = document.getElementById("dashboard-overview-required-subject-note");
  if (valueNode) valueNode.textContent = String(snapshot.count || 0);
  if (listNode) {
    listNode.innerHTML = (snapshot.rows || []).map((entry) => {
      const name = `${entry.student.firstName || ""} ${entry.student.lastName || ""}`.trim();
      const missingText = entry.missingSubjects.map((subject) => subject.name).join(", ");
      return `<button type="button" data-open-missing-required-student="${entry.student.id}" title="${escapeHtml(missingText)}"><b>${escapeHtml(name)}</b><small>${entry.missingSubjects.length} missing</small></button>`;
    }).join("");
  }
  if (noteNode) {
    noteNode.textContent = snapshot.count
      ? `${snapshot.count} student${snapshot.count === 1 ? "" : "s"} missing required subject enrollment.`
      : "All students have required subjects.";
  }
}

function buildDashboardOpenClassesSnapshot(dashboardStudents) {
  const targetStudents = (Array.isArray(dashboardStudents) ? dashboardStudents : visibleStudents())
    .filter((student) => !studentIsArchived(student));
  const studentIds = targetStudents.map((student) => student.id);
  const today = todayISO();
  const schoolYear = currentSchoolYear();
  const startCandidates = [schoolYear?.startDate || OPEN_CLASSES_TRACKING_START_DATE, OPEN_CLASSES_TRACKING_START_DATE]
    .filter(Boolean)
    .sort();
  const startDate = startCandidates[startCandidates.length - 1] || OPEN_CLASSES_TRACKING_START_DATE;
  const endDate = [today, schoolYear?.endDate || today].sort()[0] || today;
  if (!studentIds.length || startDate > endDate) {
    return { count: 0, rows: [], startDate, endDate };
  }
  const rows = instructionalDatesByRangeForSchoolYear(schoolYear, startDate, endDate)
    .filter((dateKey) => dateKey >= startDate && dateKey <= endDate)
    .map((dateKey) => {
      const count = Array.from(dailyScheduledBlocks(dateKey, studentIds).values())
        .flat()
        .filter((block) =>
          block.type === "instruction"
          && effectiveInstructionStatus(block.studentId, block.courseId, dateKey) === INSTRUCTION_STATUS_SCHEDULED
          && (dateKey < today || schoolDayPlannedEndHasPassed(block, dateKey))
        ).length;
      return { date: dateKey, count };
    })
    .filter((row) => row.count > 0)
    .sort((a, b) => a.date.localeCompare(b.date));
  return {
    count: rows.reduce((sum, row) => sum + row.count, 0),
    rows,
    startDate,
    endDate
  };
}

function renderDashboardOpenClassesSummary(snapshot) {
  const valueNode = document.getElementById("dashboard-overview-open-classes-value");
  const listNode = document.getElementById("dashboard-overview-open-classes-list");
  const noteNode = document.getElementById("dashboard-overview-open-classes-note");
  if (valueNode) valueNode.textContent = String(snapshot.count || 0);
  if (listNode) {
    const visibleRows = (snapshot.rows || []).slice(0, 4);
    listNode.innerHTML = visibleRows.map((row) => {
      const quickFilter = row.date === todayISO() ? "past-due" : "";
      return `<button type="button" data-dashboard-open-school-day="1" data-dashboard-school-day-tab="daily-schedule" data-date="${row.date}" data-school-day-status-filter="${INSTRUCTION_STATUS_SCHEDULED}"${quickFilter ? ` data-school-day-quick-filter="${quickFilter}"` : ""} data-dashboard-context-label="Open Classes"><b>${formatDisplayDate(row.date)}</b><small>${row.count} open</small></button>`;
    }).join("");
  }
  if (noteNode) {
    if (snapshot.count) {
      const hiddenCount = Math.max(0, (snapshot.rows || []).length - 4);
      noteNode.textContent = `${snapshot.count} scheduled class${snapshot.count === 1 ? "" : "es"} past planned completion since ${formatDisplayDate(snapshot.startDate)}${hiddenCount ? `; ${hiddenCount} more date${hiddenCount === 1 ? "" : "s"}.` : "."}`;
    } else {
      noteNode.textContent = `No open scheduled classes since ${formatDisplayDate(snapshot.startDate)}.`;
    }
  }
}

