    if (openButton) {
      const index = Number(openButton.getAttribute("data-alert-open-index"));
      const alert = buildAlertsSnapshot().alerts[index];
      openAlertAction(alert);
      return;
    }
    const acknowledgeButton = event.target.closest("[data-alert-ack-index]");
